/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240226-6","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"区民委員会","time":"午前１０時００分～午後 ０時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","topics":[{"id":"topic-01","title":"第１７号議案、品川区手数料条例の一部を改正する条例","agenda":"第１７号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせてください。これは法律のことで、私はよく分からないことで、少し見てみたのですが、調べきれなかったのですけれども、なぜ３月１日からの法令改正なのかということです。新年度が４月から始まるから、恐らくそういったところでの手続きが増えてしまうために３月にしたのかなどと思ってはいるのですけれども、それは国のほうから何か説明があったのかどうかということが一つ。","respondent":"吉野戸籍住民課長","answer":"３月１日なのですけれども、これは国からの説明はなかったのですけれども、恐らく４月１日からちょうど繁忙期になりますので、その前にこの施行をという形になったかと思われます。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"２点目のところについて、例えばその戸籍情報を添付をするというものが、１６桁のパスワードというか識別符号を、これも手数料を払ってということになっていますけれども、これには例えば期限みたいなものがあるのかどうか、例えば具体例としてどのようなものがあるのかということだけ少し確認させてください。","respondent":"吉野戸籍住民課長","answer":"それ以外のものについての連携のためのものになりますので、まだこれはどこの省庁がやるかというところは決まっていないのですけれども、こういったところで戸籍証明書の連携を図るというような仕様になっています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"一例で、何かパスポートに添付するようなものにもこの戸籍電子証明書識別符号が使えるというようなお話もあったと思うのですが、これはいつ頃の運用になるかというのは、国から情報が来ていますでしょうか。","respondent":"吉野戸籍住民課長","answer":"これは各省庁のシステム改修によるものみたいで、法務省では既に準備ができてはいるのですけれども、今おっしゃったパスポートであったりとか、そういったもののシステム改修次第になります。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"１点お伺いします。手数料の部分なのですけれども、戸籍電子証明書提供用識別符号の発行と、除籍電子証明書提供用識別符号の発行で、新旧対照表の５ページから７ページに書いてある部分の確認なのですけれども、こちらは同じ内容の戸籍証明書、除籍証明書と同時に申請する場合は、手数料は無料ということでよろしいのでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、例えば紙と電子とを発行した場合には、いわゆる電子のほうは無料になります。マイナポータルを使っての申請の場合も、今現在は改修中なのですけれども、こちらのほうも無料になる予定です。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"委員長に質問なのですが、建築課長の説明というのはこれからあるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"建築課長に質問しますが、都市環境部関係の（５）の説明で、今日この区民委員会に出席してくださっていると思うのです。資料を読むと、改正後が「建築物のエネルギー消費性能の向上等に関する」という「等」の部分が増えているので、改正前と改正後という形で文書には出ていると思うのです。この「等」の部分が一番の変更だと思うのですけれども、この「等」の部分について説明していただけますか。","respondent":"長尾建築課長","answer":"こちらの「等」というのが追加された背景としましては、これまで建築物省エネ法と言われていましたこの法律自体は、建物が消費するそのエネルギーの消費を抑えるというところを主とした法令だったのですけれども、改正の中で、今後は創エネ。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"今、発電という話でしたけれども、その発電というのは具体的には、例えば太陽光パネルとかそういうふうに考えてよろしいのでしょうか。","respondent":"長尾建築課長","answer":"おっしゃるとおりです。太陽光発電、あと太陽熱の利用とか、そういったものが想定されております。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問","question":"私からも１点質問させてください。今回、３月１日から改正されて、このように手数料を取ることになるわけなのですけれども、窓口の職員の皆様の、区民の皆さんがいらっしゃることに対しての準備状況とか、事前にどのように周知されて、職員の皆様に認識していただいているかということについて教えてください。","respondent":"吉野戸籍住民課長","answer":"今回、広域交付というのは新たなシステムになりますので、もう大分前から地域センターを含めてシステムの研修をやっているところです。はこの料金の部分での設定も、今進めているところです。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"新しいこういった大きな変化、それから手数料をいただくですので、くれぐれも、遺漏のないように進めていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"令和６年陳情第１８号、デジタルアプリをクリエイターに支援するための陳情","agenda":"令和６年陳情第１８号、デジタルアプリをクリエイターに支援するための陳情","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"今回何かすごく思ってしまったのです。その辺についていかがでしょうか、というのがまず商業・ものづくり課長への質問です。文化観光課長、ぜひ教えていただきたいのですが、「映画産業が集中」と陳情に書いてあるのだけれども、実際に映画産業が集中しているのですか。というのは、これは大事ではないですか。","respondent":"小林商業・ものづくり課長、篠田文化観光課長","answer":"もし今回のようなクリエイターに限らず、ＤＸを更に推進するような動きであれば、それに対応した補助金がありますので、そういう中でご支援もできるのかなと考えています。映画産業というのをどういう産業として捉えるか、範疇がよく分からないところはあるのですけれども、いわゆる一般的に映画産業と言うと、例えば東宝、東映みたいな大きな映画会社があって。","id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"だからそういう意味において、その時代がどんどん変わっていく中で、２０４５年はシンギュラリティが来ると言われている中で、やはりスタートアップも含めて何か特化して応援していってあげるというのも、今からどんどん進めていくというのが、将来、品川区を特徴とする大きい産業となっていくと思うので、私は何か応援したいと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"せらく委員","kind":"意見","question":"今回個々で助成を行うのは、行政として支援するのは難しいところがあると感じておりまして、ただ、物価高騰・エネルギー価格高騰の支援として、今、銭湯や運送業への支援をしていると思うのですけれども、そちらとの違いについて行政として考えていることがありましたらお知らせください。","respondent":"小林商業・ものづくり課長","answer":"エネルギーについて冒頭の説明で申し上げましたけれども、２０２０年を１００とした場合の値上がり率が非常に大きく、２０％以上値上がりするような中で、特にエネルギーは広範囲に、業種全般に幅広く影響を受けているというところを考えております。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"映画産業がどこまでとか、集中は認識していないというお話があって、この陳情の「クリエイターを生業にしている小規模事業者の区民は現在でも多い」というのは、区としてはこの小規模事業者のクリエイターの方が何名程度いるのかというのは把握していらっしゃるのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"産業分類において、このクリエイターが個別に何人いるかというのはちょっと難しいですけれども、区内には全体的に約２万の事業者がいる中で、こういった個人事業主、特にクリエイターという方も最近デジタルの取組が増えている中で一定程度いらっしゃるのかなと考えています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"商業・ものづくり課のご説明に関して確認をさせていただきたいのですけれども、現在区で進めているこの物価高騰に対する支援の制度ですが、こちらを利用している事業者の方々の業種というのは主にどういったところが多いのでしょうか。そして、そのデジタル関連の事業者の方がどのぐらい利用しているかというのがお分かりでしたら、教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"ただいまご質問の、物価高騰の融資あっせんがどういった業種に利用されているのかですけれども、幅広くございまして、例えば多いのは製造業ですとかサービス業、あるいは情報通信業、建設業まで、特に業種を特定のところに絞ってというものではございませんので。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点ほど確認させてください。これが物価高騰しているのですよということを表している、しかも企業同士のやり取りですから、その中に陳情に例示があるようなアプリというものも含まれるという認識でいいのか。すみません、ちょっと私はそこがよく分かっていないので教えていただきたいのです。","respondent":"小林商業・ものづくり課長","answer":"１点目、統計データの中で５００品目ある中でですけれども、今、この陳情に出ている、こういったソフトウエア自体が品目名で直接出てくるというわけではなくて、全体を日本銀行が調べているような物価統計の高騰が進む中で、こういったソフトウエア分野も当然ながら。","id":"exchange-015"},{"speaker":"横山委員","kind":"確認","question":"先ほどＳＨＩＰで一部アプリの操作指導をやっているということだったのですけれども、どういったアプリの操作指導等をやっているのかというところを確認させてください。","respondent":"小林商業・ものづくり課長","answer":"先ほどの私の説明の中で、ソフトウエアの操作指導というお話を申し上げました。今回の陳情の中でいきますと、このＡｕｔｏｄｅｓｋ社のＦｕｓｉｏｎ３６０というものですけれども、これはいわゆる３Ｄ－ＣＡＤというか３Ｄモデリングをやるためのソフトです。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"確認","question":"もう一つ、その五反田バレーを含めて、ＩＴのことについて力を入れていくというのは今の質疑の中で確認をさせていただいて、これは来年度予算案の話になりますけれども、そこについては品川区としてもスタートアップ・創業支援ということで、つまびらかには申し上げませんが、まさに五反田バレーへの支援というような項目も入っているというところで、なかなか現時点では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出して、不採択でお願いいたします。併せて意見を申し上げます。これは費用増による影響、陳情者の思いは理解します。品川区には五反田バレーがあり、デジタル産業の振興を進め、特色のある区としていくべきであるということも共感いたします。それぞれの支援策については、クリエイターの皆様にもっと使っていただけるように周知していただきたいと要望したいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"私は趣旨採択でお願いします。この年間５万円程度という陳情に関しては、金額がこのように出ているので、採択と言うと５万円出してくださいというふうになってしまうのだけれども、この物価が上がる中にいろいろな業種があって、だから５万円となってしまうと、という思いはあるのです。ただこの全体的な文章を読ませていただくと、やはりこれからですよね。ですので、趣旨採択します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。今までもすごく努力されていると思うのですけれども、そういうふうにも思います。そういった相談などニーズを把握する上でも、商業・ものづくり課の皆様には親身になって相談を引き続き聞いていただいて、クリエイターや個人事業主の皆様にいろいろな支援の提供をしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"アーティストやクリエイターの方々に対しては、先進的な取組を実施している他国の状況ですとか、文化庁のメディア芸術クリエイター育成支援事業などの、国ですとか、都、他の自治体の状況等を把握していただきながら、また学生のところは所管が今はないということだったのですけれども、例えば学割等が設定されているＡｄｏｂｅ社などはそうだと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"児童見守りシステム（まもるっち）のリプレイス","agenda":"児童見守りシステム（まもるっち）のリプレイス","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"すごく重要だと考えています。ランニングコストも２,６００万円削減ということですが、私からはシステムの移行に伴うサービスの一時停止の期間が令和６年３月３０日から４月２日で、多分これはちょうど子どもたちが春休みの期間なのですかね。まもるっちがない期間なので、特に周知を行ってほしいという、これは希望ですけれども、こちらをお聞かせ願えますでしょうか。","respondent":"河合生活安全担当課長","answer":"保護者への周知関係なのですけれども、既に学校を通じまして、各ご家庭で事前にどう対応するかを検討していただくために学校経由の連絡網で周知しているとともに、私立・国公立関係、区立ではない学校には保護者に個別で手紙を出させていただきまして、周知を行っております。","id":"exchange-022"},{"speaker":"えのした委員","kind":"質問","question":"もう周知されているということで、安心しました。ただ、先ほどの１点、万が一システム移行の失敗というか遅延があったときというのは、２日の午前７時半以降から入学式までの、その間で対応ができるということでよろしいのでしょうか。","respondent":"河合生活安全担当課長","answer":"システムの不具合が出たときにつきましては、どの程度の規模かちょっと分かりませんけれども、やはり速やかに対応するというところで、規模等を含めてちょっと遅延するようであればすぐに周知をするという形で、警察にも周知いたしまして、その期間。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"何点か確認をさせてください。このまもるっちのリプレイスは、先ほどえのした委員からもありましたが、学校の負担軽減やコストダウン、セキュリティ強化と様々よい点があって、ぜひとも進めていただきたいということで考えております。今回のこのきっかけ、これにはどういう背景があるのか、既存のこの契約期間がちょうど満期を迎えてのリプレイスの対応なのかという背景を教えていただきたいです。","respondent":"河合生活安全担当課長","answer":"最初に、リプレイスのきっかけですが、おっしゃるように５年の契約でやっているのですけれども、その契約更新に際してリプレイス、今ある課題、そのコスト面とかそういったものを踏まえて検討して。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"契約期限に合わせて、よりよいサービスに変えようということで考えて、こういった内容になったということで理解をいたしました。この機会をしっかりと生かしてよいものにしていくという取組は、とてもよいと思っています。クラウドについても、比較検討して信頼性の高いものを選んでいただいたということで理解をいたしました。しっかりとこれを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"各種申請の電子化のところで新規契約についてなのですけれども、新１年生になると、入学式でまもるっちが配られると思うのですけれども、その手続きの際に、保護者が何かしていくことが今後出てくるのかどうかをお聞きしたいです。","respondent":"河合生活安全担当課長","answer":"新規契約の今度の新１年生の手続きなのですけれども、学校連絡会のほうで既に説明会が始まっておりまして、そちらでまもるっちの新規申込の手続きについて行う形になっておりまして、入学式のときに端末を全て。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問","question":"そうしたら保護者の皆さんは、新規契約の部分では、これまでになかった手続きを新たに踏まなければならないというような状況にはならないという理解でよろしいでしょうか。新規契約の部分だけご答弁をお願いします。","respondent":"河合生活安全担当課長","answer":"学校側には最後のそういった取りまとめといいますか、新年度前ですので、そういった申込みの手続きは学校側にお願いしているところになっております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"このまもるっちという施策ができてからもう２０年近くになりますかね。今日この場で数字がどうだということは伺わないのですけれども、担当課として、そこはしっかり押さえておいていただきたいと思うのです。その辺についてはいかがでしょうか。","respondent":"河合生活安全担当課長","answer":"委員ご指摘のとおり、予算も大きな配分になっておりまして、その効果はしっかり把握しなくてはいけないということは私も認識しております。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"もちろんおっしゃるとおりなのです。だからまず、そこら辺をもう一回答弁していただきたいです。コストダウンしましたではなくて、これだけ児童が守られているのですということのほうを行政として全面的に言っていただきたいと思うし、コストがかかるものはかかるのだから、だからそれは議会にかけて予算をつけて承認していくわけですから。その辺も含めて答弁していただけますか。","respondent":"河合生活安全担当課長","answer":"児童の安全・安心が保たれているというところで、まもるっち全体で年間大体８万件弱発報するのですけれども、そこで緊急で児童の安全を確保する必要があるということで対応したのが、今年ですと緊急案件１５件ということで、比率的にはすごく少ないのですけれども。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"誤作動も含めて、８万件あるのですね。８万件というのはすごい数字ではないですか。実際にというのは１５件という話だったけれども、今８万件あるという話で、そのうちの１件でも大きな事件に巻き込まれてもいけないと私は思っているのです。今日はうれしかったです。１５件あって一つも大きい事件にならかったということは、本当によかったですねと本気で思います。その辺の思いを最後に伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"やはりこのシステムがあるからこそ、リアルタイムで安全が確認できるということが大きな武器になっておりますが、システムがよくても事案にどう対応するかで全然違いますので、システムをしっかり活用しながら、指揮者としてしっかりやっていきたいと考えております。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"幾つか確認をさせていただきたいと思います。２点目が経費等のところで、ランニングコスト、初年度においてはそのバッテリー交換等ができなかったのでその部分と、時限的な保守点検の状況ということなのですけれども、今後の保守点検のスケジュールというのは、特に数年はバッテリー交換ですとかは初年度以外は予定していないということなのでしょうか。","respondent":"河合生活安全担当課長","answer":"警察へも、まもるっちがその間使えないというところになりますので、そういったところの警戒もお願いする形で、連携しながら対応したいと考えております。","id":"exchange-031"}]},{"id":"topic-04","title":"令和５年度八潮地区まちづくり事業の進捗状況","agenda":"令和５年度八潮地区まちづくり事業の進捗状況","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"防犯がテーマで、先ほどもまもるっち、これは子どもたちのほうでしたけれども、やはり我がこと化で関心が高いと感じております。それと今後の展望として、来年度はまちづくりに参画を希望する２０代・３０代の方からも意見を伺いたいとありますが、これは先ほど大学生のグループが活動されているというお話でしたけれども、やはり２０代・３０代の方は現状少ないのかというのを教えてください。","respondent":"中西八潮まちづくり担当課長","answer":"ＬＩＮＥですが、これは八潮で取組を進めているものでございまして、八潮学園から不審者情報をもらいまして、各自治会長ですとか防災協議会の方は区から防災タブレットが貸与されていますので、そちらのほうに情報を展開して、先ほど委員がおっしゃったとおり。","id":"exchange-032"},{"speaker":"えのした委員","kind":"質問・要望","question":"ただ、こういった八潮の取組のように、やはり品川区のほかの地域でもそういったＬＩＮＥからの情報というのは、品川区のＬＩＮＥも早いですけれども、警視庁からの的確な間違いのない情報であれば、もし間違いがあったとしても不審ということであれば、そういった情報が地域の方に届くというシステムの取組をお考えいただければと、これは私の要望ですけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせてください。これが二つ目です。実際そこのところはどのようになっているのかというのが三つ目。最後に、先ほど２０代・３０代の方々に声をかけて、八潮出身の大学生にも参加をというお話でしたけれども、その大学生の方たちは八潮に住んでいるということなのでしょうか。それとも、住んではいないけれども、ふるさととして何か参画をしているということなのか、四つお伺いいたします。","respondent":"中西八潮まちづくり担当課長","answer":"最後の大学生のお話、すみません、私の説明が曖昧で申し訳なかったのですが、今も八潮団地に住んでいる学生で、今も住んでいるのでまちづくりを何とか一緒にやりたいといったことで、今回声をかけてくださったグループがあったといったところで。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"やはりその事業主体はこれからというお話だったと思いますけれども、やはり事業主体が入らないと、築４０年ですから地場のマンション等を見ていても、４０年程度ではあまり建て替えと言うと、程度と言ってはあれですけれども、老朽化は進んできていろいろ不具合が出てきているとは思うのですが、修繕の度合いによってもいろいろ違ってくるでしょうし。","respondent":"中西八潮まちづくり担当課長","answer":"こちらのガイドライン自体は、今後まちづくりをしていく中での考え方といったところで都市計画課がまとめたところでございまして、具体的にこうしましょう、こういうふうに変えていきましょうといったところまでは行き着いていないという認識を私は持ってありますので。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"防犯について伺いたいのですけれども、八潮地区における防犯カメラの設置はどうなっているのでしょうか。それと、資料の１、八潮地区まちづくり事業についてのところなのですけれども、「人口の高齢化等により、地域ニーズが変化・多様化している」とあるではないですか。そうしたら、八潮のまちづくりではないではないですか。逆に基本は都営住宅だとかがあって、区営住宅はないわけではないですか。","respondent":"中西八潮まちづくり担当課長","answer":"防犯カメラについてです。防犯カメラに関しましては、各号棟で必要に応じておつけいただいております。ですので、すごくたくさんつけていらっしゃる自治会、管理組合の号棟もありますし、まだまだつけ切れていないような号棟もあるかなという認識はしています。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"課長、建て替えのときの話に入れていないというだけで、八潮に住んでいる住民の方は八潮みらい懇談会には入っているということですね。それなら安心しました。よかったです。なぜなら八潮の住民ですからね。","respondent":"中西八潮まちづくり担当課長","answer":"自治会連合会の方々にメンバーで入っていただいておりますので、例えば都営住宅であれ、そのＪＫＫの建物であれ、そこに自治会がありますので、そこのメンバーに八潮みらい懇談会に入っていただいております。地域住民の方に関しては入っていただいております。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"分かりました。よく分かって安心しました。それはそうですよね。運河があって。その連続性というのは、もし犯罪が起きたときにどう逃走したかなどという意味で。だからそこを、八潮という意味と、せっかくお隣に生活安全担当課長が座っているわけですから、やはりこれは防犯という意味でやっていかないとと思っています。それと橋等の防犯カメラの連続性、その辺についてはどのように考えるか教えてください。","respondent":"河合生活安全担当課長","answer":"委員ご指摘のとおり、防犯カメラの連続性のところで、八潮団地に入るところに、現状は八潮はやはり号棟ごとの自治会が主体になって防犯カメラをつけてくださっているというところで、自治会連合会という地域全体でやっていただいたことに対して助成というのは。","id":"exchange-038"}]},{"id":"topic-05","title":"住民基本台帳事務における特定個人情報保護評価の実施結果","agenda":"住民基本台帳事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"第三者点検のところで、この品川区個人情報保護審議会には、構成員の方が３名いらっしゃって、私も調べたら弁護士の方で、これは公表されているのでしょうか。言ってしまっていいのですか。","respondent":"吉野戸籍住民課長","answer":"大丈夫です。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"それにもかかわらず、これに関する内容を今回のこの評価で取り扱うことの是非ということを、どうなのでしょうかと聞かれていることに対して、この回答は、その是々非々については述べていないのですけれども、その読み取れるところを見ると、住民基本台帳事務に関わるということを言っているのだと思うのですが、もう少し説明していただいてもよろしいでしょうか。","respondent":"吉野戸籍住民課長","answer":"これに関しましては、本区では印鑑登録証自体と印鑑登録のカードとマイナンバーカードを一体化できる仕様でやっておりますので、それで印鑑のそういったシステムを記載させていただいたという次第です。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"おっしゃったようなことは、例えばコンビニ等でマイナンバーカードで印鑑証明が取れるというのは印鑑登録証としての機能があるからということで、その印鑑登録証の機能というのは住民基本台帳事務に関わるそのデータを使っているから、評価をしていただいて結構なのですよということでよかったでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおりです。","id":"exchange-041"}]},{"id":"topic-06","title":"臨海部広域斎場組合施設整備基本方針（案）","agenda":"臨海部広域斎場組合施設整備基本方針（案）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"そもそも論で分からないのですが、基本方針（案）の３ページ、臨海斎場において将来の火葬需要が最も高まる年が２０６０年から６４年と書いてあるでしょう。ここがどうしても分からないのです。ですから、逆に教えていただきたいです。こうやって数字を出してくるわけですから。改めて伺います。なぜ２０６０年から２０６４年が火葬需要が最も高まる年度なのかという根拠を教えてください。","respondent":"吉野戸籍住民課長","answer":"こちらに基づきまして、委員のご指摘のとおり、実際に増えるそういったところの見方もあるかもしれませんが、人口ビジョン数値に基づいた結果では、２０６０年になるというふうに結果が出ている次第です。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"人口ビジョンに出ているからしようがないですよね。けれど、私が言いたいことは分かりますよね。だって、２０２５年から団塊の世代が全部後期高齢者になるのだと言っているわけですね。人口のウエートが一番大きいところが。だけど、人口ビジョンでそう出ているのですからね。でも安心しました。私も１００歳を越えられるなという思いを楽しみつつ、この質問はこれで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"そうした中で、まずいわゆる式場の数を増やす。その後感染症であるとか余裕を持った炉の配置というところがいろいろと書いてあるのですけれども、これは炉については１０基というところで、もうこれ以上は増やさないということなのですか。プラス６基から１０基だというところで、余裕を持たせるというところで、もう少し増やすというのはなかなか難しいのかなというところです。その辺りを教えてください。","respondent":"吉野戸籍住民課長","answer":"今回の増設は、今の敷地の中の駐車場を使って増やしますので、これ以上増やす予定は今のところありませんが、あと１０基、要は計２０基になれば、先ほどご質問いただきましたが、この一番の死亡率が多いところは全て対応できるというような試算になっております。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"確認","question":"もう一回確認なのですけれども、最初のところのまとめのところでは１０基増設し、合計２０基とするとあるのですけれども、今回に関しては、これは２０基になるということでよかったのでしたか。","respondent":"吉野戸籍住民課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"ではこれで余裕をもつということですか。分かりました。まだそれまでには若干数年間あるのですけれども、この前おっしゃっていた、陳情審査のときにあったものについては、ここの待合室の増設で、それによって待機時間が短くなるという、そういった理解でよろしかったでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおりで間違いありません。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺っていくのですけれども、こちらの臨海部広域斎場組合施設整備基本方針（案）の４ページの、２番目の丸の「組織区の臨海斎場への持込率が増加した場合においては」のところなのですけれども、死亡者数がピークとなる２０６０年から２０６４年の段階でのお話で大分先の話ですけれども、こちらに１万８,４０８件を他斎場で対応すれば間に合う計算となるという記載があるのです。","respondent":"吉野戸籍住民課長","answer":"今、炉の回転数を３.５回転で計算しているのですけれども、非常時には４回転、５回転というような対応も可能であると聞いております。それから二つ目のお伺いですけれども、２０基のうち１基、これは運用予備炉として、１９基で動かすという計算になります。","id":"exchange-047"},{"speaker":"横山委員","kind":"確認","question":"理解いたしました。ありがとうございました。１９ページなのですけれども、こちらも私が勉強不足の部分があるのですが、斎場の耐用年数は４０年間という形なのでしょうか。（２）の今後の見通しのところで、中長期修繕、ＬＣＣ計画を作成したとあるのですけれども、こちらは２０４４年まで、次の２０ページに計画が記載されているかと思うのですけれども、その辺りを確認させてください。","respondent":"吉野戸籍住民課長","answer":"予備炉１基なのですけれども、現在１０基でやっているところも実は１基は予備炉としたいところではあるのですけれども、１日３５件回しているところです。","id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"地域でも炉の問題もあるのですけれども、やはり遺体を安置している場所も少ない。これはどのように試算されて、４庫増えて２０庫になったのかというのをお知らせ願えるでしょうか。","respondent":"吉野戸籍住民課長","answer":"保冷庫は今は２４庫あるのですけれども、増築時には４４庫に増やします。２０庫増やすようなイメージになっています。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"６基増やすというところを、足元の見通しを踏まえて１０基の増設にしていただいたということで、前向きに柔軟に増やしていただいていると受け止めております。ほかの委員のご質疑もありましたので、理解が深まりました。資金計画の増築施設整備のところで、都市計画交付金で火葬場部分の９割はやられるというところですと、その残りの１０％のところはどういう見通しなのでしょうか。","respondent":"吉野戸籍住民課長","answer":"そちらの１０％は、施設整備基金から取り崩すような形になると思います。","id":"exchange-050"},{"speaker":"山本委員","kind":"確認","question":"この基金のほうから取り崩すということで、炉を当初計画よりも増やし、１５億円増えるけれども、資金計画的にはもう見通しが立っていて問題ないというのが今の考えでいいでしょうかという念のための確認です。","respondent":"吉野戸籍住民課長","answer":"この利用料収入なのですけれども、先ほど言った式場を開設しますので、その部分の利用料収入も今後は見込まれるだろうというところで、この利用料収入という記載になっております。","id":"exchange-051"},{"speaker":"山本委員","kind":"質問","question":"収入増を見込んでいるということなのですけれども、単価としては特に上がるとかそういうことではなく、引き続き同じような水準で使えるという前提でよろしいでしょうか。","respondent":"吉野戸籍住民課長","answer":"今の待合室自体が、貸出が２万円となっておりまして、そこを式場とした場合、面積案分でいきますと、今、式場自体が５万６,０００円なのですけれども、それよりも若干下がりまして３万５,０００円ぐらいで想定しておりまして、それを合わせた額になりますので。","id":"exchange-052"}]},{"id":"topic-07","title":"しながわシティランの開催","agenda":"しながわシティランの開催","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"本当にいよいよ近づいてきたなと感じておりますが、４の今後の主な予定、機運醸成のための記念イベント・プレ大会の1)です。しながわシティラン１年前記念イベントで初心者向けのマラソン教室。ただその当時はやはり予算的になかなか限られているものですから、「初めてでも楽しいマラソン教室」のように有名な講師の方をお呼びすることができなかったので、今回とても楽しみにしております。","respondent":"三井スポーツ推進課長","answer":"今後のかけっこ教室等なのですが、今年度についてはこれで以上なのですが、来年度については実行委員会の中で考えていくような形、まだちょっとそこまで考えられていないのが現状にはなりますが、今後の検討課題とさせていただければと思います。","id":"exchange-053"},{"speaker":"山本委員","kind":"質問・要望","question":"開催に向けて様々なイベント等で機運を醸成していっていただきたいと思っています。質問は、今回大会要項を示されたということなので固まってきたことで、定員と申込方法のところで一部確認させていただきたいです。特に小学生・中学生などは割と多く参加したいとなると、限られた定員になってしまうのかなと少し思って、お聞きする次第です。","respondent":"三井スポーツ推進課長","answer":"申込方法の先着・抽選なのですが、こちらについては今検討中になっておりまして、申込前までに。ほかの大会を見ると大体抽選とかそういうことが多いのかなと。ただ、区民の方優先にするかとか、そういうところも踏まえて検討していきたいと考えております。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問・要望","question":"今まさに検討中ということと、あと、ファミリーのところは人気だということで理解いたしました。やはり、高校生以上の方のところでも品川区民の方が優先的に走れるようにご配慮、ご検討いただきたいということと、人数が多かったときにはやはり抽選のような平等になるような形での検討を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"何かそれは今回はそういうことをしなかった、そういう旧東海道を一気通貫するようなコース、南品川から北品川まで通過するようなコースにしなかった理由とか、今後何かそういう検討の余地、警察の意見等も含めてお考えの余地があるのかどうか、その辺りを教えてください。","respondent":"三井スポーツ推進課長","answer":"今後は、今、警察との交渉の中で何度も言われているのが、やはり安全・安心でまず第１回を迎えられなくてはいけないというところで、それが持続可能な大会になるかどうかという命運を左右するということを私たちは認識していますので、まず安心・安全な大会となるよう。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"前段の部分で、障害者の方も実行委員会には入っているのでしたか。障害者の団体の方は入っているのでしたか。その方から、いわゆる車いす参加の是非についてのご意見というのは特になかったのですか。特にこのことに関して要項を、これから先、そういったご意見が出るとか出ないとかということについて、出ているのか出ていないのかというところも含めて、最後に教えてください。","respondent":"三井スポーツ推進課長","answer":"現在、実行委員会の中にはそういった団体の方は入っておりませんで、実際に車いすの参加についての声というのを聞けていないような現状です。ただ、今回のコースについて言いますと、安全の対策でいうとなかなか難しいのかなと考えております。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"意見","question":"そういった特に身体障害のある方についての今回のこの要項については、しっかり説明をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"葬儀後の火葬場への移動が負担となるため、臨海斎場の式場が選択されるためであるということがあったのですが、今、友引の日はそういった措置をするということでしたけれども、なぎさ会館の在り方というか使用について、何か今検討していることがあるのであれば、それについて教えていただければと思います。","respondent":"吉野戸籍住民課長","answer":"なぎさ会館自体のところが今ちょうど再開発なども入っているところがありますので、いろいろと今後検討していかなければいけないことはたくさんあるかなと考えています。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965719?Template=document&Id=2982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":54359,"voices":176}},{"id":"r06-20240226-7","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"厚生委員会","time":"午前１０時００分～午後 ５時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を138件抜き出しています。","topics":[{"id":"topic-01","title":"第２２号議案 品川区立大原児童発達支援センター条例","agenda":"第２２号議案 品川区立大原児童発達支援センター条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"新たな児童発達支援センターができるということは、本当によかったと思っています。歓迎です。それから、これまでベルは、たしか区独自の一般財源で行っていたと思うのですけれども、今度は、地域生活支援事業で行うということになるのか、そうすると、そのことで変わるものがあるのかについても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"時間によって、今度は、３階の児童センターの遊戯室なども活用しながら事業実施をすることを見込んでおりますので、事業実施には特段支障はないと考えております。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"今回は、たくさんの事業をやることになるのですけれども、指定管理者というところで言うと、この１階、２階、３階の部分まで、児童センターも含めた形での事業者の公募になるのでしょうかということと、そうなると、これまでもグループホームの公募でも、３００者、４００者に働きかけても指定管理者が１者という状況が続いてきたと思うのですけれども。","respondent":"川崎障害者施策推進課長","answer":"随意契約ではありませんので、同一の受託者で継続することは前提ではありません。ですので、今回、大原児童発達支援センターの１つの事業として、インクルーシブひろばベルを実施することになるので、指定管理者として改めて公募をいたします。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ幅広い事業を行う施設になるわけですけれども、スペースとしては、そんなに広くはないのですけれども、職員体制としては、どういう体制になるのか、どのような専門職が何人ずつ配置されて、合計何人になるのかが見通しができているのではないかと思うのですけれども、その点を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"公募に関しては４月以降になるので、職員の体制であるとか、どのような専門分野ということに関しましては、これから子ども育成課とも詰めてまいります。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、大人のいわゆる指定特定相談支援事業所という形、大人のケアプランをつくる、そういう事業をやるというわけではないということなのですか。その点をもう１回お願いします。そういうときには、代替施設は、もうどこか考えられているようなところがあるのか。十数年後に建て替えということも踏まえての今回の大規模改修ということなのか、その確認だけお願いします。","respondent":"松山障害者支援課長","answer":"もしこれが改築になった場合になりますけれども、現在の建物のボリュームからすると、現在の建築基準法との観点から、縮小せざるを得ないということも施設整備課からは聞いておりますので、今後の改築につきましては、企画課、それから施設整備課とも十分検討してまいります。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"今もお話が出ていましたけれども、この事業内容を、主に６点あります。児童センターの運営、発達支援センターの運営、同じ子どもを対応する事業なのですが、やはり障害というところとすると、事業者がこれを一緒に全部ができるということは、なかなか難しいのではないかと想像するのですけれども、その辺をお伺いしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今回、大原児童発達支援センターとベルと、そして児童センターと、指定管理で１者が行っていくというふうに考えております。児童発達支援センターと児童センターを含めて、建物を一体にインクルージョンの推進を実現していきたいと考えております。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"例えば、それぞれの事業があって、一体的なインクルージョンなのだけれども、それを統括するというイメージなのか、そうすると、１つ１つの事業をそれぞれのところにというか、委託をしながらやるということができるのか、指定管理者が一部事業者に委託をして、そこも一緒に一体的に統括しながらやるという事業運営なのか、その辺、もう少し教えていただけますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"公募に際しては、今後の４月以降にはなりますので、その辺につきましては、子ども育成課とも十分検討しながら、指定管理者の中身を詰めていくことになります。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"これから公募をされていく中で、今ご説明があった一体的なのか、事業体なのかというところもお話がありましたけれども、これは１つ懸念されるのが、グループをつくったときに、そのときにやはり事業体がこの体制をつくったといったところが非常に懸念されるところですので、どうか今回のこの条例をつくって指定管理でやっていくというところは、私たちも応援をしていきたいというふうには思うのですけれども。","respondent":"川崎障害者施策推進課長","answer":"繰り返しにはなりますけれども、公募の選定に当たっては、公募の趣旨と、そして設置目的から、指定管理者として最も優れている業者を総合的に判断してまいりたいと思います。区としても、事業者との連携を丁寧に進めていきたいと、そこは確実に決めてまいりたいと思います。","id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"確認の質問になろうかと思うのですけれども、品川区立大原児童発達支援センター条例ということですけれども、条例というと、包括的につくられるのかと思いまして、例えば、児童発達支援センター条例とか、そうしたもう少し抽象的な条例にするのではないのかと思うのですけれども、わざわざこれを個別的に、大原児童発達支援センターのための条例ということで、そうすると、今後。","respondent":"川崎障害者施策推進課長","answer":"今後、小山台児童発達支援センターが整備される予定になります。","id":"exchange-008"}]},{"id":"topic-02","title":"第２３号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２３号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"初めに、(2)の特別給付費のところで、地域密着型ケアハウスサービスの廃止のことを伺いたいのですけれども、これはケアホーム東大井の月２万円の減免制度のことだと思うのですけれども、今まで市町村特別給付でやってきたものが、今度は指定管理料として、その分を管理料として上乗せするというか、そういうふうな形で出すということになるということは。","respondent":"菅野高齢者福祉課長","answer":"こちらの給付につきまして、今回、事務事業評価等でも１つ１つの事業について検証させていただいたのですけれども、やはりこのケアハウスができて１５年がたったというところで、当時は地域密着型の特定施設の入居者生活介護サービスが全国的にも少し珍しい施設だったので。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で品川区がやってきたということがあるので、私は、この市町村特別給付の残りの２つの事業も、これは必要だと思うのですけれども、それを市町村特別給付ではなく、今回のケアホームのように、保険料に連動させないという形で、一般財源でやっていただきたいと思うのですけれども、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらについては、事務事業評価の中でも、やはり適格性がどうかというところも検討はさせていただいたのですけれども、今回の部分については、先ほども説明させていただいたように、介護保険では補い切れない部分の方たちについて。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"続いての質問ですけれども、保険料について伺いたいと思います。それから、今年度、約２０億円の基金ということなのですけれども、これ、決算でもう少し増えるかもしれないと思うのですけれども、２０億円の基金を今の段階で幾ら取り崩して、３年後の第９期の終わりには何億円の基金を残すという計画なのか、また、残す金額は、なぜその金額にするのかという考え方についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"それが今度、１７段階になったときに、２,５００万円以上はというところで、７９５人と試算しているところです。先ほどの質問で３,０００万円以上は約６００人と試算させていただいています。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが６.５億円というその考え方も伺いたいと思います。ただ、応能の負担というところからは、まだまだ遠いと思うのです。所得に占める保険料の割合は、まだまだ本当に低所得者に重い負担となっているので、２,５００万円までで打ち切りにした、２,５００万円以上は、どのように所得があっても同じ額というふうなことで、２,５００万円で打ち切りとした理由を伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういったところの理解を、支払う側の理解を得られるとか、そういったバランスも考えないといけないというところも総合的にシミュレーションさせていただきまして、今回は上限を２,５００万円、３.３倍というところで決めさせていただいた次第です。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"働く人にとっては低賃金で長時間過密労働だし、事業者にとっても人手不足で赤字続きというところで、自公政権の社会保障削減路線の中で、現場が本当に大変になっていると思うのですけれども、現場としては必死に頑張っているけれども、いつまで続けられるのかという、そういう話ばかりお聞きするわけなのですけれども、このままでいくと。","respondent":"菅野高齢者福祉課長","answer":"地域支援事業というところで、そこも第８期に比べて少し伸びておりまして、地域包括ケアシステムの中で、特に介護予防事業については力を入れるというところで、そこについての給付費の見込みも若干増えているというふうに捉えているところです。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"確認","question":"全国的なところでは、ずっとそうやって出し続けているということは分かっているのですけれども、特別区長会とか、そういうところでは、そういう動きはないのでしょうか。そういうだけではなくて、声を上げていくということが必要なのではないかと思うのですけれども、そういう動きは今のところはないというところなのですか。その辺だけ確認したい、よろしくお願いします。","respondent":"今井福祉部長","answer":"特別区長会の対応ですけれども、私たちもほかの自治体と共に、東京都または国への要望を取りまとめて行っているところですけれども、今、手元に全部新しいデータはないのですけれども、介護保険制度に関しましても、特別区長会として国に対して充実の要望を上げておりまして。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"介護事業に係るサービスのサービス料が、高齢化も伴って費用の増加が見込まれるということは当然あるのですけれども、予防にやはり力を入れて給付費の抑制をぜひ図っていただきたいというふうに考えているのですけれども、そういったところで何か区で今お考えのような新たな事業とか、計画があるのでしたら、教えていただきたいと思いますが、いかがでしょうか。","respondent":"川原高齢者地域支援課長、菅野高齢者福祉課長","answer":"その通知を確認した上で、区としてどういった給付または支援ができるかということを考えていきたいと考えているところでございまして。介護報酬が悩ましいところで、サービス給付が増えて、そして今も人材不足というところで処遇改善のお話がありますが、そういった場合。先ほど、総合事業に係る部分、要支援、要介護の部分で申し上げたのですが、一般介護予防事業では６５歳以上の元気な高齢者の方、参加できる事業は。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それぞれありがとうあります。やはり介護報酬を上げると利用者の自己負担が増えてしまうというところの綱引きが難しいところがあるというのは本当に実感しておるのですけれども、そういうところでいうと、今回、品川区も来年度予算で出している居住等支援補助金でしたか、月１万円の。ああいう取組は非常にすばらしいというふうに思っております。何かあれば、お願いします。","respondent":"菅野高齢者福祉課長","answer":"国も介護報酬約６,０００円の引き上げと、あと、東京都も手当を別途支給するというふうには取り組んでおりますが、そういった国や都の動き等も踏まえながら、区としてできることは何かというところで考えたものですので、そういったところをまた事業者の声を聞きながら。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなのに、今度、引き下がるということになるので、すごく大変な状況になるのではないかと思うのですけれども、そこら辺は区としてどう捉えられているのか伺えたらと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらについては、国は、処遇改善の加算のほうが大きいのでというところで、そこでカバーリングできるのではないかという話もありますので、そういったところを実際にうちのほうも現場の事業者と、お話を聞きながら、どういう実態なのかというところは。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際にカバーできるというのは、その加算をとっていない１割ぐらいのところしかないというふうに言われていて、だから、実際のところは、ほとんどのところが本当に大変な状況に追いやられるというふうなところだと思うので、ぜひそれは現場の状況もつかみながら、上にも声を上げていただきたいということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"なので、そういった意味でも事情を把握していない可能性があります。それは苦肉の策というか、というふうな状況が生まれる可能性があるということをぜひ承知しておいていただいて、今後の、この４月以降の訪問看護がどうなるかということを、ぜひ最大限に注視して、それこそヘルパー不足によって地域包括ケアシステムが品川区で崩壊しないように対応していただきたいと思うのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"なので、区内の訪問介護の事業者、数者いろいろとやり取りしているところもありますので、そういったところのお声も聞きながら、この緊急声明とか、いろいろなメンバーが、当事者団体が拝見していますけれども、この実態。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私も現場の方たちに、いろいろ声を聞きながら、ここで提案とかをしますので、ぜひご協力のほど、お願いします。私も一般質問で時間がなくて言えなかったことを、今、追加で言えたので、今後ともよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"意見","question":"この条例は、介護保険料値上げの条例なので反対です。先ほども申し上げましたけれども、介護保険料は、２０００年開始から２倍の値上げになっています。大本では国の負担割合を増やすということですべきだと思います。制度開始から２倍になった介護保険料は、応能負担の徹底だったりとか、一般財源を投入してでも、値上げではなく引き下げることが必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"様々お話を聞いて、反対ではあるのですけれども、ただ、やはり区の取組は一定評価いたしますし、大阪などは、今回、月１,１５５円上がって、１４.３％、年間の月額が１１万９８８円と物すごく上がったりしている中で、品川区としての取組も評価いたしますけれども、やはり今後も厳しい状況が続くのではないかということで、一般財源の組み入れも考えていただきたいというところで、反対ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"(2)のところなのですけれども、多機能系というのは、小規模多機能だと思うのですけれども、看護小規模多機能型居宅介護もあると思うのですけれども、それから、施設系サービスというのは、特養ホームや老健施設ということと、居住系サービスというのは、グループホームや特定施設ということでいいのでしょうかということは確認させていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"管理者が人手不足なのかというご質問については、今回の運営基準の改正自体が、今後、介護人材の確保が一層困難になると予測される中、生産性向上による業務能率化や。実際に施設の委員会が、現在どのように動いているかというのは、各施設の取組になっておりますので、詳細までは、分かりかねているのですけれども、ただ、区としましては、施設については、昨年度。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"それなのに、こういうふうに３対０.９人とかということで人員配置を規制緩和して、もっと少ない人数でやれということになると、もっと行き届かないということになっていくのではないのかというふうな思いがするのですけれども、そういうことは、なぜそこが出てきたのか、そのような対応が必要なのか、現場からもそういう声が上がっているのか、そこの点は伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"条件としましては、見守り機器などの複数活用とか、職員間の役割分担などにより生産性向上に先進的に取り組む特定施設に限ってという条件をつけているところもありますので、現場の実態等も踏まえて。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"確認","question":"２ページ目の「書面掲示」の見直しなのですけれども、もともと書面掲示、施設に運営規程を張っておく。それに加えて、これからは、法人のホームページとか、都でやっているもの、情報公開システム上にも公表するというようなことなのですけれども、今回のこの改正は、運営規程をしっかり利用者の方、もしくは家族の方に見てもらうというような趣旨での改正ということでよろしいですか。確認です。","respondent":"菅野高齢者福祉課長","answer":"こちらの書面掲示のみならずというところで、ホームページ等で公開する部分については、事業所内のみならず、公にきちんと公表するようにというところで、サービスの適正といいますか、そういったものを図ろうとしていると解釈しております。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実際、介護施設で、正直、わざわざ見る人はほぼいないのです。しかも、それが細かい文字だと、余計やはり目に留まらないので、であれば、特にフォントについて、幾つ以上でなければいけないということを、高齢者も見やすいように、大きい字での掲載をされると、よりそういうふうに周知を目指すのであれば、いいかなと思うのですけれども、その点はいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"現在も施設の中で、各施設、工夫していただいているのかなと思いますが、この辺の運用については検討させていただきたいと思います。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問","question":"次ですけれども、第２６号議案、第２７号議案のほうの２ページ目のケアマネジャーの担当というか、受け持ちの件なのですけれども、様々緩和されたということで、基本的には５人まで、ざっくり言うと、基本的に５人ぐらい受け持ちが増えるということと、介護予防に関しては、２分の１の換算が３分の１に緩和されるというような受け止めでよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"こちらのケアプランの件数等につきましては、委員ご指摘のとおりで、５人ぐらいの件数が増えるというところと、ただし、介護予防については、今まで２分の１を乗じていたものを３分の１になるというところで。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問","question":"大田区などは本当に小さい事業所が無数にあって、品川区の３倍ぐらいあるのではないかという、私も働いていた印象だとあるのですけれども、品川区は、割とやはりその辺は、ケアマネ事務所としてまとめられていて、大きいところに集約されているようなイメージなので、そうなると。","respondent":"菅野高齢者福祉課長","answer":"民間の居宅介護支援事業所については、民間ですので、その辺りの経営者のご判断にもよるというところもありますので、区としては、在宅介護支援センターのほうでできる限り予防支援はしていくというような方針も持っておりますので、予防支援、３分の１を乗じるというところで。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ現場の声を注視していただきたいというふうに思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"在宅介護支援センターの状況はつかまれていると思うのですけれども、在宅介護支援センターも本当に大変な中で頑張られていると思うのですけれども、そういうところでは、在宅介護支援センターが要支援のところも多くを受け持っていただいている中で、この４４件までで要支援は３倍も受け持てるというふうなことになったら、現実問題、できるのですかねという思いがするのですけれども、そこら辺のところは。","respondent":"菅野高齢者福祉課長","answer":"１つ、これは緩和されたとはいっても、まず、居宅介護支援事業所につきましては、民間の居宅介護支援事業所ですので、ここの件数が上限だということも踏まえて、できる範囲でやっていただくということしか区としては申し上げられないのかというところと、あとは、では一方で。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それは人それぞれあるのかもしれないですけれども、なので、やるならケアマネジャーに納得してもらえるような形の研修、充実した内容にしていただきたいと思いますし、本当は、やはりこういった講習というか、更新自体を本当はなくしてほしいという声が現場からは圧倒的に多くいただいておりますので、最低でも研修内容の充実とか、費用の負担を行政がするとか。","respondent":"菅野高齢者福祉課長","answer":"やはり限られた資源のいろいろな介護サービスをいかにケアマネがうまくその方にご意見を聞きながらケアマネジメントしていくかというのは、介護保険制度の中で大きな鍵となっておりますので。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"座学での研修も分かるのですけれども、例えば、私が現場のケアマネジャーと接していて思うのは、やはり優秀なケアマネジャーは、地域の資源をたくさん知っているのです。いろいろなサービスがあるという、ボランティアとか、無償でやっているようなものも含めて、地域のあらゆることに精通していて、それをうまく提示できる。現在のところ、そういった取組はされていらっしゃいますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"割と民間の居宅ですと、一人親方が多かったりとかする部分もありますので、そういった研修を通して、通知をただ流すだけではなくて、研修等を通して、そういった部分についても気づいていってもらうことが重要ではないかと思っているところです。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。別件で、第２４号議案、第２５号議案の１ページ目の(2)のところなのですけれども、介護サービスの質の確保および職員の負担軽減に資する方策を検討する委員会の設置を３年の経過措置で義務づけるということなのですけれども、こういったことの実施の趣旨というか、どういった目的で行われるのか教えてください。","respondent":"菅野高齢者福祉課長","answer":"こちらについては、介護現場における生産性の向上に資する取組の促進というところで、国としては、例えば介護ロボットとか、ＩＣＴ機器の導入などの対応も含めた方策というところなので、やはり業務負担とか、あとは。","id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私の調べたところだと、こういった業務効率を含めた委員会みたいなものを定期的に行っている事業所は、いわゆる業務効率とか、生産性が向上しているというようなデータがあっての実施というふうに伺っているのですけれども、ただ、やはり割と大きい事業者はこういったことも取組としてできるのかなと思うのですけれども、中規模、小規模の事業所ですと、大分こういった取組は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"賛成です。ただ、本当に現場の大変なところを規制緩和で乗り切ろうというのではなくて、やはり大本のところをしっかりと体制を整えていただきたいということでは要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"意見","question":"賛成ですが、全般を通してなのですけれども、今回この改正を区として見たときに一番気になったのが、やはり管理者の兼務のところで、今回、現場の人員配置の緩和であったりとか、こういったいろいろな変更がある中で、常勤の管理者を置くとうたっているのにもかかわらず、その管理者が同一敷地内にいない可能性が出てくるということで、働くスタッフの方もそうですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"賛成ではある、やはり国の指針といいますか、改正に合わせてのことということがありますし、賛成ではあるのですけれども、やはり人員配置の緩和と職員の負担軽減はどうしても相いれないところがあると思いますので、こういったことは、区としてもぜひ都ですとか国に、介護職員、ケアマネジャーを含めて、介護職で働く皆さんの業務負担が増えないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"意見","question":"これは先ほども申し上げましたけれども、現場からは、ケアプランはこれ以上もう限界というふうな状況ですので、やはりケアマネジャーの待遇改善、そして成り手を増やす、そういう形でしっかりと利用者に寄り添ってケアプランをつくれる、そういう体制こそすべきであって、足りない分をケアマネジャーのより労働強化にするような点数の増というふうなものであるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはりケアマネジャーの緩和の件において、どうしても現場の声は相いれないと思うので、そこの点を含め、反対ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほどと同じ理由で反対で、ぜひ国や都に強く働きかけていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-03","title":"第３４号議案 東京都後期高齢者医療広域連合規約の変更","agenda":"第３４号議案 東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"前に保険料等比較表というものを出していただいていたのですけれども、こういうもので出していただくと、賦課総額が幾らで、これとこれが保険料の賦課額になって、これは一般財源で負担しますということで、幾らということまで全部書かれていて、この図がとても分かりやすいと思うのですけれども。","respondent":"池田国保医療年金課長","answer":"それともう１つ、収納率についての関わりだと思いますけれども、広域連合としての収納率の計算については、９９％ということで計算をさせていただいているということで、その中で保険料の未収金の補填金が算出されているところです。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、剰余金も充当しているし、保険料抑制のために財政安定化基金とかも充当していることもあるのですけれども、財政安定化基金が、今、どれぐらいたまっていて、そういうものを使って保険料を減額していただけたらいいのではないかと思うのですけれども、そういうところは、現行ではどうなっていたのかも伺います。","respondent":"池田国保医療年金課長","answer":"なかなかこの部分、難しい表でございまして、単純に一表になっているものではないので、同じものを作るということは少し難しいかと思いますけれども、似たようなものが作れるかどうか、そこら辺の検討はします。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。それと、賦課限度額も、今まで６６万円が、令和６年に７３万円になって、令和７年、８０万円ということで、今年度までからすると１４万円も上がっているのですけれども、多分、賦課限度額をここまで引き上げるということも初めてなのではないかと思うのですけれども、その点も、今までの経過も含めて伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"それと、医療制度改革における影響ということでは、こちらはＡ３の表の部分で(9)、左の黄色部分が医療保険制度改革で受ける影響でございまして、ここの部分については、被保険者に関わる(9)のところで、１人当たり６４１円ということでの見込みがあったということと。","id":"exchange-043"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最高限度額は２％を超えないようにということでということなのですけれども、でも、実際、ここを見ると、８０万円の人は２.５７％となっていて２％を超えていると思うのですけれども、これはそれでいいのですかという、今の説明と少し矛盾しないのですかというふうに思うのですけれども、それも伺います。","respondent":"池田国保医療年金課長","answer":"出産育児一時金についてですけれども、高齢者負担率の見直しにつきましては、現在の負担率の設定方法は、現役世代の減少が多くなっているところに目を入れたところでございまして、現役世代の負担を減らすというようなことで、高齢者負担率を上げているということで。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの財政安定化基金を保険料の引き下げに使いたいというふうなところが、東京都のオーケーが出なかったということなのですけれども、財政安定化基金を保険料引き下げに充当するかどうかということは、東京都が決めるという仕組みなのか、財政安定化基金の仕組みがよく分からないので教えていただきたいのと、結局、財政安定化基金は、どれぐい積まれているのか、そのこともお聞かせください。","respondent":"池田国保医療年金課長","answer":"財政安定化基金が幾らあるかと、後ほどまたご報告させてください。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの高齢者人口なのですけれども、これは東京都全体の高齢者人口なので、パーセンテージが出ているところで何人くらいかなというふうに思ったのですけれども、品川区の後期高齢者の人口もどこかに書いておいていただけると、イメージもつくなと思ったので、それは要望だけさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"確認","question":"あらかた鈴木委員のお話のとおりなのですけれども、確認なのですけれども、後期高齢者、２０２２年１０月から２割負担が導入されていると思うのですけれども、確認です、そういう認識で大丈夫でしょうか。","respondent":"池田国保医療年金課長","answer":"昨年から２割負担を導入しています。","id":"exchange-047"},{"speaker":"やなぎさわ委員","kind":"質問","question":"現在、恐らく経過措置として、３年間は１割負担プラス３,０００円の自己負担で医療が受けられるというか、負担を軽くするという処置がとられていると思うのですけれども、それもそういう認識で間違いないでしょうか。","respondent":"池田国保医療年金課長","answer":"配慮措置としまして、令和４年１０月１日から３年間ということでやっているところです。","id":"exchange-048"},{"speaker":"やなぎさわ委員","kind":"質問","question":"介護保険とかほかの保険制度も結局同じになってしまうのですけれども、国の制度上の欠陥を非常に感じてしまわざるを得なくて、区としてやれることは当然限られていて難しいとは思うのですけれども、こういった中で、区として、国や都に対して、どういった働きかけを今後していく予定というか、計画とか、そういった何かがあれば、お話を聞きたいのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"それともう１つ、申し訳ございません、話が少し前のほうに戻りますけれども、財政安定化基金の残高ですけれども、令和５年３月末現在で約２１２億円になってあります。","id":"exchange-049"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"強く継続的に国に求めていっていただきたいと思います。恐らくまた次の改定のときも上がってしまうのではないかと非常に危惧しておりますので。本当に国の制度上の欠陥と考えておりますので、議会もそうですし、区としても、ぜひ強く訴えていっていただきたいと思います。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この議案に対しては賛成です。保険料は広域連合で決定するということにはなっていますけれども、過去最大の値上げという状況ですので、本当にこれは品川区のほうからも強力に国のほうにも言っていただいて、後期高齢者はずっと負担増が続いていますので、軽減措置がなくなってからも、本当に負担増が続いていますので、これはぜひとも声を上げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-04","title":"第３６号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第３６号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"改めて、後期高齢者の保険料も過去最大の値上げということなのですけれども、今回の国保料も過去最大の値上げでということで、改めて厚生委員会の中でも確認させていただきたいのですけれども、１万円を超えての値上げは今までなかったと思うのですけれども、去年が１万１,２８３円の値上げで過去最大ということで、本当にすごい値上げだったのですけれども。","respondent":"池田国保医療年金課長","answer":"これを見る限り、保険料の伸び率については、今回、令和５年度と比べても高いということで、過去では、かなり上位のところというふうに認識しています。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"抜本改革の実現までの間は、５点、ぜひやってくださいと言って国交省に求めていて、それは、国庫負担割合の引き上げ、低所得者の負担の軽減、それから、子どもの均等割、子どもの国保料の、今、未就学児までが半額となっているけれども、この制限を撤廃して１８歳まで、そして、軽減の割合の拡大も実施するようにという、こういうことを５点にわたって求めているということなので。","respondent":"池田国保医療年金課長","answer":"保険料の金額について、高いかどうかということにつきましては、保険料の算定に当たりましては、所得の推定、それから医療費の推定等を出した上で保険料を算定してまいりますので、今回の金額については妥当な数字は出しているかと考えています。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区としても、その認識を持っていただきたいと思います。だって、組合健保や協会けんぽの２倍ですから、ほぼ２倍の、同じ収入の人が、国保という保険制度に入っているがために、組合健保とかの２倍の保険料になるというのは、どう考えても高過ぎるという認識をぜひ持っていただきたいと思うのです。組合健保にしても、協会けんぽにしても、収入で割合が決められているわけではないですか。","respondent":"池田国保医療年金課長","answer":"令和５年度前期で１億１,０００万円ほど執行停止の処分をさせていただいて、ちなみに、令和４年度につきましては２億６００万円ほどの執行停止という形になっております。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、これは保険料減額のための繰入れですから、去年に比べて７０億円近く減らしているので、これも踏まえた上で、ぜひ減額にしていただいて、そして過去最大の保険料値上げは、もっと引き下げていただきたいというふうに思うのですけれども、そこのところは、去年よりもかなり、これとこれというふうな形で限定しているので１４９億円となっていると思うのですけれども。","respondent":"池田国保医療年金課長","answer":"それがおおよその方、先ほど申しました今年は１６６件ほど差し押さえを実施しています。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問","question":"少しお伺いしたいのですけれども、一般会計の繰入金を、最終的にはなくそうというような方向で書かれていらっしゃるということで認識してよろしいでしょうか。","respondent":"池田国保医療年金課長","answer":"一般会計のその他の繰入金という名目でゼロにするということが国からの目標ということで来ているところです。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"国からそういう目標が来ているということで、その理由は、どういう理由で国はそういうふうにしろというふうにおっしゃっているのでしょうか。","respondent":"池田国保医療年金課長","answer":"実際に東京都がほとんどの部分で、そういった金額を使っているというところもございまして、平成３０年度に国民健康保険が市区町村の単位から広域化になったときに、財政の安定を図っているところがありますので、目的としましては、国保の財政安定を目的に。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"半数の自治体が繰入金を使っていないということで、逆に、品川区は、それこそ何十億円単位で使っていると思うのですけれども、他の使っていない自治体との差はどういうところに出てくるのですか。","respondent":"池田国保医療年金課長","answer":"各自治体によって使い方がありますので、はっきり言って、２３区内ではこういった使い方があるので、その他、保険料に補填しているその他の繰入金を使っている部分がどうかというのは、すぐお答えできるところではございません。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、国としては、こうやって特別区とかは非常にそういった繰入金が多いという事情は分かっているけれども、ほかの半数ぐらいの自治体は使っていないのだから、同じように、地域ごとの特性とかは特に考えずに、将来的には均一にどこも繰入金は使わないでというようなことでおっしゃっているということで、改めてそれでよろしいですか。","respondent":"池田国保医療年金課長","answer":"国は補填金を使わないで、こういった赤字は解消するということになっていまして、実際に今、半数と言われましたけれども、赤字を解消している自治体がありますので、東京都も赤字解消しろというような形になっているところです。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"意見","question":"それが本当に一番理想だと思うのですけれども、やはりこれからのことを考えると、そうですね、はい、理由は分かりました。やはり繰入金あっての現状だというふうに認識を深めましたので、結構、今後も上がってしまうのではないかという心配をしております。ひとまずこれでいいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"こんの委員","kind":"確認","question":"被保険者が減といったところは、やはりこれは後期高齢者医療に移る人が多くなってきているということが１つ要因としてあるのかということの確認と、あと、参考までに、医療費がやはり上がってしまっているというか、その削減取組というのでしょうか、改めてその辺はどのように取り組んでいらっしゃるのか、その辺を参考までに伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"健康についてですけれども、国民健康保険では、国保被保険者に健診の受診を呼びかけてありますけれども、そのほかに今年は、データヘルス計画を策定しているところでございまして、明日、報告事項でデータヘルスについて報告しますけれども、皆様に重症化にならないように。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"被保険者の状況が、数字を教えていただいたので、より一層よく分かりました。だけど、国民皆保険というこの制度は、本当に誰もが医療を受けられるという大事な制度でもあるかというふうに思いますと、現状をどう安定化した財源でこれを維持していくかといったところの取組の１つなのだろうというふうな理解をしております。意見で終わりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区長会の要望の中で、３番目に、子どもに係る均等割額の減額措置ということで言われていまして、本当にこれはずっと子どもの国保料の無料化であったり、減免は、ほとんど誰もが、そうあるべきだと思うものではないかと思うのですけれども、だからこそ区長会としても、全国市長会とかでも、ずっと要望し続けていると思うのですけれども、今回、改めてこの提言の中にもこうやって示されましたので、区としては。","respondent":"池田国保医療年金課長","answer":"私どもとしては、国のほうでこういった制度で一斉に子どもの保険料について軽減をしていただきたいということを考えているところです。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、１８歳以下の子どもの均等割を無料化したら、品川区の必要な額は幾らかということで、一般質問でも聞いたときに、多分、国の負担分を減らさないトータルの額でお答えいただいたかと思うのですけれども、国が負担している分を除いた額で１８歳以下の子どもの均等割を無料化するとしたら、区としては、どれだけの負担になるのか、その額も教えていただきたいと思います。","respondent":"池田国保医療年金課長","answer":"お子さんの保険料、１８歳以下の方の保険料について、均等割を全て無料にした場合にかかる経費として、およそ２億円ということでお答えしましたけれども、実際に６歳未満の方については、既にもう半額ということになっていますので、半額は国でやっておりますので。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ずっとこれを言い続けているにもかかわらず、ずっと国が動かないで、未就学児の半額がやっとですけれども、それ以上に拡大の動きはなかなか見えないと思うのですけれども、そういう中で、２３区が統一で子どもの国保料の減免の拡大、または１８歳までの無料化は、２３区統一で行おうというふうに、これだけ言っているのに、しかも、潤沢な財政なのに、出てこないのかなと、やはり国がやるべきだから。","respondent":"池田国保医療年金課長","answer":"保険料の軽減と免除の違いがございまして、例えば、１月から実際に始まっております出産される女性の保険料の軽減につきましては、これは国の制度になりますので、実際にご本人から申請書がなくても行うことができるのですけれども、減免というのは。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"収入のない子どもからまで全部一律保険料をとって、それで低所得者に対して、協会けんぽとか、組合健保の２倍の国保料にしているわけですから、だから、本当に子どもの国保料は、区独自にできることなので、ぜひ国に求めながらも、国がなかなか進まない中では、区の健全財政を活用して、子どもの国保料の無料化、ぜひ改めて強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今の子どもの国保料の無料化なのですけれども、やろうとしたら、大体どれぐらいかかりますでしょうか。","respondent":"池田国保医療年金課長","answer":"今年のベースでやりますと、およそ１億５,０００万円。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ほかの質問なのですけれども、１１ページの賦課限度額についてで、今回、２万円上がるということなのですけれども、いわゆる上限の年収は幾らぐらいになりますでしょうか。","respondent":"池田国保医療年金課長","answer":"医療分と支援分の賦課限度額が合わさった形が６５万円と２４万円ですので、８９万円になるかと思います。ですので、令和６年度の部分で、９００万円の方については、医療分と支援分を合わせると８２万６,０００円になっています。","id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私の認識不足で、ごめんなさい。それに介護納付金分が入って、１０６万円に……。１０６万円、４０歳以下の方になるということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問","question":"大体年収９００万円ぐらいということでよろしいですか。","respondent":"池田国保医療年金課長","answer":"もっと簡単なところを、申し訳ありません。先ほど、やなぎさわ委員がおっしゃったように、１１ページの下のほうに、「賦課限度額引き上げに伴う保険料への影響について」というところで、下のほうに表があるかと思います。限度額該当世帯というものがあるかと思います。","id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ごめんなさい、では、もう少し簡潔に言います。この限度額の年収は、例えば、今のままで収まっている、例えば、もっと高額所得の方に対して限度額を上げるみたいなことは、特に検討されているような状況はないということでしょうか。","respondent":"池田国保医療年金課長","answer":"後期高齢者支援分について、限度額を超える世帯が多くなったということで、これを２％以下に下げるために、後期高齢者支援分についての限度額が上がったという形になっております。","id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、賦課限度額の合計は介護納付金を含めると、１０６万円になりますけれども、例えば、もっと所得の高い方に限度額を上げるというようなことは法律的に難しいというような認識でよろしいですか。","respondent":"池田国保医療年金課長","answer":"そのとおりです。国のほうで限度額は幾らというふうに決めてありますので、国民健康保険法で定まっているところですので、品川区独自で上げることはできません。","id":"exchange-072"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。話を１回戻してしまうのですけれども、先ほどあった繰入金の、これは国の指導ということで、繰入金を使わずにというようにするのは、それも法律で決まっているとか、そういうことになるのですか。ただの指導ですか。繰入金を使わないというような国の方針というか、指導というか。","respondent":"池田国保医療年金課長","answer":"指導ということです。","id":"exchange-073"},{"speaker":"筒井委員","kind":"質問","question":"８ページの2)ですけれども、令和８年度で納付金の１００％を賦課総額とすることを決定、そのような旨が書いてあり、これは激変緩和措置も、令和８年で終わるという理解でよろしいのでしょうか。","respondent":"池田国保医療年金課長","answer":"現在のところ、目標は令和８年度で終了と考えているところです。","id":"exchange-074"},{"speaker":"筒井委員","kind":"質問","question":"そうしますと、令和８年度には保険料が値上がりするということで、１５ページの参考の品川区１人当たり保険料推移とありますけれども、これも順調に上がっていく見方になる。しかも、令和８年には激変緩和措置はなくなって、かなり大きな負担が来るという推定でよろしいのでしょうか。","respondent":"池田国保医療年金課長","answer":"ただ、これは保険料の率の問題ですので、先ほど言いましたように、加入されている方の所得が多くなったり、医療費が減額になれば、全体のパイが減りますので、保険料はそれほど高くないという楽観的な考え方もあります。","id":"exchange-075"},{"speaker":"筒井委員","kind":"質問","question":"一番いいのは、先ほどご答弁があったとおり、皆さんが健康になって、なるべく医療サービスとか、介護もそうですけれども、介護サービスを受けないような努力、サービスを受ける方の抑制が必要だと思うのですけれども、それについて、どのように、いろいろ計画とかを立てられていると思いますけれども、かなり実効性のあることをやらないといけないと思うのですけれども、その辺り。","respondent":"池田国保医療年金課長","answer":"多剤といいまして、一時に薬をたくさん服用された方については、多剤というようなことでの通知を差し上げて、そこの部分で、もう一度見直しをしていただくような多剤通知というようなことも考えているところでございまして、そういった医療費がかかった部分での通知のほかに。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど、介護保険のときも申し上げましたけれども、実質賃金が平均でピーク時よりも７０万円以上下がっているのに、それに追い打ちをかけるのが今回の国保料の制度開始以来最大の値上げだと思います。ここの区民の大変な実態にも寄り添って、国保料は引き下げこそすべきだと思います。区が独自に可能な１８歳以下の子どもの国保料無料化こそ品川区独自に行っていただくよう求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"鈴木委員と大体同じで、介護保険の後期高齢者も含めてですけれども、ここにいると誰も悪くないと思うのですけれども、やはりこういう値上げの話をしなくてはいけない、心苦しいですので、国への抜本的な改革をぜひ求めていただきたいということと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１.５億円で子どもを無料にできるということなので、そういったところもぜひ目指していただきたいというふうに思います。反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]},{"id":"topic-05","title":"令和６年陳情第１６号 ストーマに関わる給付金の引上げを求める陳情","agenda":"令和６年陳情第１６号 ストーマに関わる給付金の引上げを求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"この方にも直接電話をしてお伺いしたのですけれども、消費税が上がったことに合わせて、様々なものが上がってしまったということと、また、今回の物価高で、さらにまた上がったということで、２段階に値上げがされて、すごく負担になっていると伺ったのです。値上げしてほしいというのは、今の８,８５８円からどれぐらいの値上げにしてほしいという要望だったのか。","respondent":"松山障害者支援課長","answer":"２３区の状況についてです。現在、品川区と同じ金額、８,８５８円の区が１９区あります。８,８５８円より低い区、８,６００円の区が１区。ほか、８,８５８円より高い区は３つで、８,８６０円が１区。９,０１０円が１区。１万１,３００円が１区の状況です。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"８,８６０円というのは、ほぼ同じ感じかなと思ったのですけれども、その方も、本当に１万円を超えるとありがたいと言われていましたので、そのオストミー協会の見直しの１万１,０００円ということであれば、多分、かなり賄えることになるのかなと思いますので、ぜひオストミー協会の要望に沿った形で、ぜひ見直していただきたいなと思っています。この見直しというのは、どれくらいのスパンでされるのか。","respondent":"松山障害者支援課長","answer":"５７品目ありますので、それぞれ視覚、聴覚、内部障害、肢体不自由、それぞれかなり最新な機器を入れてほしいとか、こういった品目はもう使わないので廃止して、次の新たな品目を入れてほしいとか、給付限度額だけではなくて。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問","question":"１月３１日に見直しをされて、令和６年度、他区の状況も検討して、おおよそ他区の状況というのは把握されたということなのですけれども、さらに、実際にこれを上げていくとなると、補正予算を組んでということになるのですか。そして、それは令和６年度に入った中で、来年の１月の見直しを待たないでも、やる気になればできるということで考えていいのでしょうか。","respondent":"松山障害者支援課長","answer":"つきましては、令和６年度の他区の状況の情報を取りながら、再確認して、今後、また当事者の方と一緒に検討していく方法がよろしいかと考えております。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も要望させていただいたものもありますし、いろいろと５７品目、また、それにプラスされるものもあるかもしれないし、それが全部要綱で定められているということであれば、要綱を変えるときに、一斉に、これと、これと、これをこうしますという改定になる。そのような形で、これだけ単独でというよりは、今、見直している日常生活用具のほかのものも含めて検討した結果で示されていくということなのですね。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおりで、見直したご意見を総合して検討した結果、本年度はこうなりましたということで、また、ご参加いただいている障害者団体や障害者相談員、こちらの方に一斉にお示しをするとのがよろしいかと考えております。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"現在も６,６００万円ということであれば、莫大な人数ということではないので、障害の方は、それぞれ一人一人が本当に困っているというところに思いを寄せていただいて、できる限り要望にかなう形でやっていただいて、障害者権利条約の障害があることによって、自由な生活ができていないということへの保障という意味も含めて、ぜひ多くの要望をかなえていただきたいと思います。","respondent":"松山障害者支援課長","answer":"検討会で検討した後の結論としては、まず令和６年度の他区の状況を再確認します。ほかの品目につきましても、やはり同じような状況もありますので、ご意見を聞きながらということになりますと、やはり再来年度予算に向けてという形になろうかと考えております。","id":"exchange-084"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご説明ありがとうございました。もう一つ、ストーマには泌尿器系のほうもあると思っているのですが、先ほど、日本オストミー協会の要望で１万１,０００円ぐらいまで上げてほしいというところ。このところだと、もう既に１万１,６３９円と考えると、これは、恐らく、便の給付の金額の要望と思うのですが、泌尿器のところも、もしご希望の金額等ありましたら、そこも教えていただければと思います。","respondent":"松山障害者支援課長","answer":"日本オストミー協会によれば、尿路系のストーマ装具につきましては、希望額としては、同額１万３,０００円ということで、ご要望を頂いているところです。","id":"exchange-085"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう何点か伺いたいのですけれども、１月３１日の検討会の構成は、どのようなメンバーでお話をされているのか。ほかの日常生活用具の給付事業、５７品目ということでたくさんあると思うのですけれども、ほかの給付の内容も、皆様それぞれに金額を上げてほしいという要望がなされているのか。その点についても聞かせていただければと思います。","respondent":"松山障害者支援課長","answer":"日常生活用具等検討会の構成メンバーです。障害者団体の代表の方がお一人と、障害者相談員の方が３名です。そちらが外部の方。は障害者支援課です。その方の中には、それぞれ当事者の方がいらっしゃいます。","id":"exchange-086"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今の質問の趣旨としては、この物価高の影響というのは、１品目だけではなくて、ほかの品目も関わってくるのではないかなと思って、そのため、ほかの団体の方々から、この金額も上げてほしいという要望も出ているのではないかなと思って質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"こしば委員","kind":"確認","question":"結論を出すで、不採択とします。それと、今の段階で、オストミー協会をはじめとした、当事者も含めた検討会で、今後の値上げも含めたこともそうなのでしょうけれども、他区の状況を確認していきたいという前向きなご答弁も、質疑の中で頂いたので、そのような意味で、今後の区の状況を見守るという意味で、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日、結論を出すでお願いします。先ほど、質疑を聞いていて、まず１つ、他区の状況をということです。大変に大事な視点だと思いますし、また、５７品目の中の１つの陳情だというところは、この方の思いはすごく理解できるのですけれども、それとともに、ストーマ用具を使う方以外の方も、きっといろいろな新しい用具などが出てきたときに、そうしたものも要望として上がってくることも想像できる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すでお願いいたします。先ほども要望させていただきましたが、５７品目あるということで、１品目だけの値上げ、給付金の引上げということではなくて、全体的なところを見ながら、物価高騰に対する負担の軽減というものを検討いただきたいと思いますので、今回の陳情に対しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ大変な状況を出されて、私も具体的にお話を伺い、オストミー協会からも、このような形で要望も出されているということで、要望に応えていただきたい。この人に応えることで、ほかのところを応えないというのではなくて、ほかのところも要望があれば、できる限り全部応えればいいものであって、障害者福祉サービスの充実に、過去最大の品川区の予算をしっかりと使っていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。理由は、ほかの委員がおっしゃられているとおり、５７品目ありまして、ほかの用具品目との辺のバランスと、他区の状況も見ていかなくてはいけないなということであります。一方、こうした用具にも物価高騰の悪影響が出ているので、そうしたバランスや他区の状況を見て、前向きに給付金の引上げに向け、検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そうしたものが２回も値上げされているということで、本当に大変なのだなということを感じます。今、お話を聞いていますと、ほかに日常生活用具５７品目、様々な障害の方がいらっしゃって、要望が出ていないけれども、ほかの医療用具もきっと値上がりしているのではないかと思います。物価上昇の状況を見ながら、ぜひ今後、しっかりと予算を確保していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"結論を出すで、今回は不採択にします。ほかの委員もおっしゃるとおり、５７品目ということで、一方、鈴木委員の言うように、逆にこれを１つ上げることによって全体を上げるということも十分理解できます。ただ、このような要望があるということを受け止めていただいて、できれば、年に１回の検討会の見直しではなくて、適時行える状況を整えていただきたいなと思いつつ、今回は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"}]},{"id":"topic-06","title":"令和６年陳情第６号 障害者が安心して生活できる中重度対象グループホームの貸付期間の見直しを求める陳情","agenda":"令和６年陳情第６号 障害者が安心して生活できる中重度対象グループホームの貸付期間の見直しを求める陳情","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"今のご説明の中で確認なのですが、借地借家法で行くと、これは、いわゆる有償貸付けになる。そうすると、ここの部分は利用者にはどのような影響を与えてしまうのでしょうか。その辺を教えてください。","respondent":"川崎障害者施策推進課長","answer":"つまり、先ほども言いましたように、賃借料を利用者の家賃へ反映させますので、土地が無償であるということは、その分、家賃へ反映させることができませんので、利用者にとっては、家賃をある程度抑えることができる、負担軽減につながるものと考えております。","id":"exchange-095"},{"speaker":"こんの委員","kind":"意見","question":"今のご説明で行くと、事業者が参入しやすいように無償貸付けで、３０年というところはあるのかもしれないですけれども、更新も可能だとすると、事業者が３０年たったときに、社会情勢や、いろいろな状況を加味した上で、継続するのか、しないのか、その辺は聞いていただきながら、事業運営を進めていけると理解しているのですが、それでよろしいかというところ。２点目のほうだけご答弁ください。","respondent":"川崎障害者施策推進課長","answer":"委員おっしゃるとおり、先ほどの説明にもありましたとおり、品川区公有財産管理規則第２８条第３項の規定に基づき、更新は可能でありますので、３０年度の社会情勢、地域のニーズも含めて、そこを踏まえて、運営事業者とは定期的に丁寧にヒアリングを行う中で。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問","question":"建物も３０年たつとどのようになっていくのかというところも見ていくとなると、もし継続ということになったときに、３０年後、建物をメンテナンスするとなると、事業者がすることになるのですか。その辺を教えてください。","respondent":"川崎障害者施策推進課長","answer":"建物の部分に関しては、整備を含めて事業者になります。","id":"exchange-097"},{"speaker":"こんの委員","kind":"意見","question":"今、ご説明いただいて、先へ進めていく事業者のそのときの状況も加味してくださって、次の手を打っていかれようとする区の姿勢は理解できます。一番は、利用者の負担が軽減されて利用できるというところは大きいのかなと思います。分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"ひがし委員","kind":"質問・要望","question":"理由はどのように分析されているのかという点を聞かせていただきたいというのが１点です。私が品川区のものを見たときにそれを見つけ切れなくて、そのような記載をすることで、公募したときに幅広い事業者が参入できるのではないかなと思うのですけれども、その点についても見解があればお聞かせいただければと思います。","respondent":"川崎障害者施策推進課長","answer":"先ほど、ご説明したとおり、３０年後の社会情勢等も含めて、事業者とも定期的にヒアリングしながら、この用地の継続の希望を丁寧にヒアリングしていく中で検討していくことになります。","id":"exchange-099"},{"speaker":"ひがし委員","kind":"質問・要望","question":"説明会に参加された方々が応募しなかった理由というところは理解できました。ただ、公募の内容も、読んでいって決める部分もあると思いますので、すぐ更新できるという内容であれば、墨田区の事例のように一文添えていただくと、このような記載があるだけでも違うのではないかなと思いますので、その点については要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点をお聞かせください。前回のこのやり取りの中でも、この陳情に出されている８月のやり取りのところでも、委員から質問して、質問して、質問して、最終的には、協議により更新もできるという答弁もあるのです。なので、初めから、利用者にとっても、事業者にとっても安心できる材料として、ぜひ更新もできるという形にしていただきたいと思いますけれども、どうでしょうか。","respondent":"川崎障害者施策推進課長","answer":"更新につきましては、協議の上、更新は可能ではありますので、そこの部分は、今後、事業者ともヒアリングを重ねながら検討してまいります。","id":"exchange-101"},{"speaker":"鈴木委員","kind":"質問・要望","question":"協議により更新可能という、その一文を、やはり公募要領なり、要綱の中に入れていただきたいと思うのです。それを入れるということは、なかなかできないということでしょうか。３０年後も更新できますという形で行くのかというスタンスがあると思うので、そのところを伺いたいと思います。公募要領に書き込むというのは、なかなか難しいということでしょうか。ほかの区は書いています。","respondent":"川崎障害者施策推進課長","answer":"事業者もいろいろな現状があると思いますし、確かに手を挙げた業者が、実際に土地を見て検討された結果、このように１者だったということになりますので、引き続き、戸越四丁目についても、幅広く周知を行ってまいります。","id":"exchange-102"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことが、現場の社会福祉法人の実態だと思います。これから、まだまだグループホームを造っていかなくてはいけないと思いますので、ぜひ区が責任を持って、区立で、指定管理者で、そうすれば、区の土地なので、このようなことは全くないわけですから、そのようにしていただきたいと思うのですけれども、改めてご答弁をお願いしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ここは、やはり他区も参考にしながら、そして、事業者も十分参考にしながら、確実に整備は進めていきたいと考えております。","id":"exchange-103"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この間、ずっと議論してきたように、福祉や介護のいろいろな現場は、今、本当に大変深刻な状況になっていると思うのです。そのような点では、自治体が責任を持つというところに、また戻していくことが必要なのではないかなと思うのです。そのようなことも踏まえて、ぜひ区立でというところは要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"筒井委員","kind":"質問・要望","question":"公募要領に書面で記載していれば一番良かったのですけれども、事業者などからお問合せがあったときは、品川区公有財産管理規則第２８条第３項の更新可能ということについて情報提供していたのか。事業者としても、第２８条第３項の存在を知っていたのか、更新しようと思えば更新可能ということはご存じだったのかということを事実確認させていただきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"実際の説明においては、更新の有無については触れていないと思います。今後、戸越四丁目も含む民間での整備に当たっては、公有財産管理規則等を含めて、その説明はしてまいります。","id":"exchange-105"},{"speaker":"筒井委員","kind":"質問","question":"げんきさんも、第２８条第３項で更新可能ということは、現状ではご存じということでよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"私どもの耳には、げんきさんからこのようなお声は頂いておりません。ただ、公有財産管理規則についての認識はされております。","id":"exchange-106"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ一文、更新の可能性はあると書くだけで、工夫などは要らないと思うのです。そのように思うのですが、その辺はいかがですか。","respondent":"川崎障害者施策推進課長","answer":"今後、区として十分検討します。","id":"exchange-107"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ前向きに検討して、一文入れるだけで大分印象が違うと思いますので、よろしくお願いします。先ほど、鈴木委員もおっしゃっていましたけれども、私もこの公募のときに申し上げましたが、基本的には３０年、無償で借りられるというのは、補助金なども入ったりして、いろいろな計算で全部合わせて電卓をたたくと、大分安いです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問","question":"結論を出すということで、不採択とします。使用貸借によって無償になるわけですから、これが事業者だけでなく、利用者の負担の軽減にもつながっているということを理解した上で、今回のこの陳情の趣旨に添え難いと感じまして、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"こんの委員","kind":"確認","question":"本日、結論を出すでお願いいたします。更新のことについても、丁寧に意向を聞いていただくということも確認させていただきましたので、本陳情については、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご答弁で３０年以降も事業者と協議の上で更新が可能と確認ができました。事業者との協議をしっかり行いながら、まずは利用者第一で調整していただけるように求めます。公募が集まらないという課題については、以前から様々に要望しています。改めて公募要領の記載方法も含めて、多くの事業者が参入でき、障害のある方も品川区で安心して生活を送ることができるよう、体制を整えていただくよう、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。更新可能の一文を、ぜひ公募要領に入れていただきたいと思います。区が責任を持って区立への調節をしていただきたいという要望も、併せてさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択とします。理由は、今回の貸付期間３０年、無償によるものというのは、事業者が参入しやすいようにするためと、ひいては利用者の負担軽減のためのものであるということです。品川区公有財産管理規則第２８条第３項により、更新も可能ということであり、それについて、事業者に認識させていただいて、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。３０年の無償貸付け、そして、更新ありということで、安心いたしました。ですが、事業者がより参入しやすい環境を整えていただきたいと思い、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本日結論を出すで、私も、区のご答弁は非常に理解いたしました。その一方で、やはり３０年更新なしの記載がないというところで、参入障害になっていると思いますので、趣旨採択でお願いします。","respondent":"松永委員長","answer":"各会派のご意見を頂きました。採択と、趣旨採択に分かれておりますが、採択は一度しか諮ることができませんので、どちらかを諮ることになりますが、今の段階では趣旨採択と採択、いわゆる趣旨採択のほうがお二人なので。","id":"exchange-115"}]},{"id":"topic-07","title":"令和６年陳情第２号 国民健康保険料値下げに関する陳情","agenda":"令和６年陳情第２号 国民健康保険料値下げに関する陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"この３番目のところに保険料の上限を設けず、高額所得者からは能力に応じて保険徴収をしてくださいということがあるのですけれども、国が限度額を決めているということです。品川区で、限度額のお支払いをしている世帯というのは、何世帯、何％ぐらいあるのかということを伺いたいと思います。分かったら、それも教えていただきたいと思います。","respondent":"池田国保医療年金課長","answer":"それと、品川区の平均所得ですけれども、これについては、令和６年度の平均保険料が２０万５,６１２円になるというご説明を先ほど違うところでさせていただいたところです。","id":"exchange-116"},{"speaker":"鈴木委員","kind":"質問・要望","question":"年収２００万円というのは、所得で言えば、控除を引くとすごく低くなってしまうと思うのですけれども、年収２００万円ということでいいのですか。だから、年金で言えば、所得では５０万円ぐらいという感じですか。所得として計算できているものはないのか、どうなのか、それも教えていただけたらと思います。その赤い封筒はやめられたのか。その確認もさせていただきたいと思います。","respondent":"池田国保医療年金課長","answer":"限度額世帯について、何世帯かですけれども、令和４年度については、２,８３１世帯の方が限度額の世帯になっています。分母になります、そのときの総世帯は６万１,７７０世帯で、４.５８％というお答えをさせていただきました。","id":"exchange-117"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も、この委員会に持ってきたこともあったのですけれども、すごくドキッとする色で、区としては脅すという意味で出しているのだと思うのですが、これは脅して取るということではなくて、相談に乗りながら、その人の立場に立って相談に乗っていくという姿勢でやっていただきたいと思うので、この真っ赤な封筒はちょっとやめていただきたいということで、改めてお願いしたいのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"実際には、お支払いがなかなかできないような方につきましては、一括のお支払は難しいということで、分割納付という形をとらせていただいて、ご自身がお支払いできる範囲で、まずはお支払いを継続的に進めるということを説明させていただいています。","id":"exchange-118"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ優しい色にしていただきたいのです。なので、ぜひ区にご相談に来てくださいという優しい色にしていただきたい。真っ赤な封筒はやめていただいて、本当に血液のような真っ赤な色ですから、それはやめていただいて、優しい色にしていただきたいというのは、要望としてします。例えば、年金受給者１人世帯の場合。ぜひそのような立場に立っていただきたいなと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"ここら辺を出しているということは、区長会でも、国民健康保険の場合には、抜本的な改革が必要だと認識しています。","id":"exchange-119"},{"speaker":"鈴木委員","kind":"意見","question":"一気に増えるのです。例えば、年金が１５３万円の方は、年額１万９,６８０円ですけれども、２００万円になると１０万円と桁が変わるのです。その下もそうなのですけれども、２００万円になると、桁が１桁変わる。では、２００万円の人が、本当にどれだけの生活なのか。家族で生活できるのかというところで、そこを想像しながら、私たちは議論していくことが必要なのではないかなと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど、鈴木委員がお話しされていた滋賀県野洲市なのですけれども、滞納は市民からのＳＯＳとして捉え、税金を払いたくても払えない人こそ行政が手を差し伸べるべき人だとして、市長が自ら滞納を市民生活支援のきっかけにする。ただ、払いたくても払えない事情があるのだということを、ぜひ酌み取っていただきたいなと思います。質問ですが、何か受け止めがあればお願いします。","respondent":"池田国保医療年金課長","answer":"委員のご要望につきましては、私ども、保険料が未納になっている方につきましては、督促、催告書といったものを出しますけれども、お電話で納付相談、納付についてのご相談があった際には、しっかりとそこら辺の細かいところも受け止めまして。","id":"exchange-121"},{"speaker":"おぎの委員","kind":"提案","question":"私からは１つだけ。２番のワンストップ窓口を設けてくださいという陳情なのですが、現状、滞納者に寄り添ったワンストップ窓口、ご提案の設置というのは難しいのでしょうか。","respondent":"池田国保医療年金課長","answer":"役所の場合に、例えば、ほかに区民住宅の利用料などもありますし、いろいろな貸付金の返還、返済金もあるかと思いますので、全ての返済の窓口について、ワンストップでつくるというのはなかなか難しいものがあるかなと考えています。","id":"exchange-122"},{"speaker":"ひがし委員","kind":"確認","question":"私から１点確認したいのが、先ほど、ご答弁の中に生活状況調査というものを支払いが滞っている方々に送っているというお話が前回あったと思うのですけれども、これを送って、実際の返答率はどのぐらいなのかなというところ。","respondent":"池田国保医療年金課長","answer":"生活状況調査書の回答ですけれども、数字では特に捉えてはいませんけれども、督促状などに同封しているものに対しての回収率につきましては、それほど高くないところです。","id":"exchange-123"},{"speaker":"ひがし委員","kind":"質問・要望","question":"相談というところも、各課でしっかりと丁寧な対応をしていただきたいというところと、やはり信頼されていない。","respondent":"池田国保医療年金課長","answer":"赤信号と一緒なので、お願いしますという意味での赤い部分だと思ってください。内容については、委員がご意見を言われたように、もう少し分かりやすい部分で相談できるところを載せることが可能であるかを、また担当と検討します。","id":"exchange-124"},{"speaker":"ひがし委員","kind":"質問・要望","question":"相談しやすいというところも大切だと思いますので、ぜひ区民に寄り添った窓口の対応を強化していただければと思います。こちらは要望で終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"鈴木委員","kind":"質問・要望","question":"チェック。その人の状況に寄り添って、どこに困っていて、実際どうなのかという立場でやっていただかないと、この生活状況調査というものも、追い詰めるようなものになりかねないので、使い方は、現場で重々注意しながらやっていただきたいと思います。なので、連絡がつかない方に対して、訪問などの仕組みはあるのか、実際しているのか、訪問などをしているのであれば、その件数なども伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"国民健康保険料は、相互扶助の精神で制度が成り立っているものです。なおかつ、保険料の支払いが９０％を超える方、要は１０人の方が普通に払っていただいて、残りの１人の方に対して、こういった事務作業をさせていただいているところです。","id":"exchange-126"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう協会健保よりも、組合健保よりも２倍高い国民健康保険料が高過ぎるということが問題なのです。それで払えないわけですから、それが協会健保など、半分ぐらいになれば払える人はもっと増えるのではないかと思うので、そこが問題だと踏まえた上での対応で、払いたくても払えないという人には寄り添った相談という形で、ぜひやっていただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"筒井委員","kind":"質問","question":"端的に、この陳情の趣旨で、国民健康保険料を値下げしてくださいとあるのですけれども、先ほどご説明があったとおり、現在２３区は統一保険料方式をとっています。そういった状況で、品川区だけ国民健康保険料を下げるということは可能なのでしょうか。","respondent":"池田国保医療年金課長","answer":"基本的な方針としまして、私ども品川区は２３区の統一保険料を採用しているですので、特に品川区だけ保険料を変えるということは全く考えていないです。","id":"exchange-128"},{"speaker":"筒井委員","kind":"質問","question":"統一保険料率が定まる。所得割と均等割の割合が、特別区基準だと５８.４になるところを、品川区の場合、所得が高いことから、６０対４０になるのですけれども、この６０対４０というのも、機械的に算出され、何か基準があって自動的に決まるものなのですか。","respondent":"池田国保医療年金課長","answer":"令和５年８月時点の所得を見ておりますので、令和６年４月以降も、４月の時点でこの所得の方がいらっしゃるかどうかというのは分からないところです。実際に蓋を開けたときには６０対４０になっていないところが多かったりしているものが、つい最近の傾向ではあります。","id":"exchange-129"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほどのご答弁で、一応確認なのですけれども、２３区中４区は違う。江戸川区、中野区、千代田区など、採用されていないところも統一保険料にしていないところもあることはありますか。確認です。","respondent":"池田国保医療年金課長","answer":"保険料については、統一を基本方針とするけれども、統一でない場合、できないところはしなくても構いませんという方針をとっていまして、今、委員からお話がありましたように、千代田区ほか３区が統一保険料から外れているところです。","id":"exchange-130"},{"speaker":"こしば委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。逆もあるかもしれませんが、そういったことで対応を図っていく。常に図っておられると思いますが、これからも寄り添った対応をしていただきたいと思います。そういった意味も含めて、この趣旨の願意に添い難く、不採択にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"今日、結論を出すでお願いいたします。保険料が少しでも安い。ですが、そもそもこの保険料は、２３区統一の保険料方式を採用しているということですので、それはなかなか難しいだろうとも理解しております。ここで、この方たちが求めているのは、とにかく滞納してしまったときの対応といったところが大きいのかなと思います。要望で終わります。ですので、今回は不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"ひがし委員","kind":"質問・要望","question":"様々お話があったとおりに、統一保険料方式ということで、なかなか品川区だけで変更することは難しいということが理解できました。個人情報保護の観点からも、徐々に伝えることが難しいというところで行くと、しっかりと各部署で、生活の状況に寄り添った相談が行えるように、その方に寄り添った対応を求めていければと思います。今回は不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"鈴木委員","kind":"提案","question":"ワンストップの窓口で、滞納者への寄り添った対応というのも、相談に来たら、区から提案して生活再建につなげていく。ぜひそのようにやっていただきたいと思います。今回、介護保険のところでも、２,５００万円まで能力に応じた保険料ということで提案されていますけれども、そのような考え方を国民健康保険の中にも取り入れていくということは、検討すべきなのではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-134"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由は、品川区の場合は統一保険料方式をとっているので、現実的にそこは難しいのかなということであります。ですので、もっと丁寧なご対応と、重層的支援体制の趣旨も踏まえて、各種様々なほかの窓口にもつないでいただけるようなモデルとしていっていただきたいと考えております。これは、要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今日決めるでお願いします。やはり、今、物価高が続いて、どんどん重くなっているという現状の人々の生活をよく見て、ぜひ国に強く、強く申入れをしていただきたいなと思います。ぜひ困っている方へ親身に対応しつつ、ほかの課との連携も構築を進めていっていただきたいなと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３年連続過去最高ということで、税収は上がっていて、相対的に我々地方で使えるお金はあるはずですので、そういった意味でも、国民健康保険料、低所得者なのに負担が重いという構造的な問題があるということは当然承知していて、本来であれば、国が抜本的な改革をするべきなのですけれども、それに向けて、まずは区でできることをしていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"その紹介会社を通さなければ人材を確保できないような実態をどのように把握され、紹介料補助とはどのようなことなのか、その考えと内容についても伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132976?Template=document&Id=3684#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":104391,"voices":426}},{"id":"r06-20240226-8","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"建設委員会","time":"午前１０時００分～午後 ４時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を119件抜き出しています。","topics":[{"id":"topic-01","title":"第２８号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"第２８号議案、品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回オンライン決済が導入されるということで、その場合の手数料の金額は変わらないのかというところを伺いたいと思います。それと、今回このオンライン決済機能を導入して、利用される方の見込みの数があれば伺いたいと思います。今回オンライン決済を導入するということで、これができるようになれば、その手続もオンラインでできるようにしていただきたいと思うのですが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"オンライン手数料ですが、現在のところ調整中ですが、大体１％程度の手数料がかかる予定で進めているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"手数料は１％かかるということで、それは区民が粗大ごみを出すときのお金には上乗せされることはないのかというところ、区民の負担が増えるのかどうかというところを伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"手数料ですけれども、当然、区民の方に対して上乗せというのはございません。それから、減免の申請につきましては、先ほどの答弁のとおり、いろいろと研究させていただきたいと思っています。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"つけていただくということは基本だと思うのですけれども、その対応の考え方。それから、前からお願いしているのですけれども、ホームページからの一覧、どういうものがあるのかというのが分かりづらいので、そこは分かりやすいように工夫していただきたいとお願いしているのですが、それはいかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"ホームページにつきましては、すみません、このタイミングで、ホームページに一斉に修正をかけたいと思いますので、そのときに対応させていただきたいと思います。","id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"出されたものが本当に回収されるものなのかが分からないと、やはり回収しづらい。なので、そこはホームページでご案内するときに、必ず貼ってください、剥がれないようにということはお願いしたいと考えていますし、学んでくると思うのです。貼らないと持っていってくれないのだと覚えるので、それも一つの方法だと思いますので、お願いしたいと思います。ホームページのほうは、ぜひお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"確認も含めてお伺いしますが、今回、オンラインで決済ができるようになったということでありますが、経費も１％ぐらいはかかるけれども、料金には反映させないというお話でありました。","respondent":"品川品川区清掃事務所長","answer":"逆にシールの部分で、発注とかそういうところで軽減される部分もあるので、こういったところでやや業務的には減ってくるのかなと思いますし、今後、オンライン決済の量が増えていくことによって、またいろいろこういうところは変わってくるのかなと考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"その効果を、今後の推移を見ながら検証していただきたいと思いますが、今回、粗大ごみの処理だけでありますが、今もお話が出ました事業系のほうへの将来的な対応は、もう当然検討というか、方向性としてはそうだと思いますが、その際、粗大ごみ以上の件数だと思いますので、収支がどうなるかということも見通していきながら、また一方で、区民の方の利便性の向上といった視点も。","respondent":"品川品川区清掃事務所長","answer":"事業系のほうなのですけれども、事業系ごみというのは原則的な考え方は、清掃業者に委託していくというところが本来の考え方で、小さい企業とかは、なかなかそういうところが難しいというところで、区収集という形でも、例外的にまでは言わないのですけれども。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問","question":"業務の効率化という観点で、先ほどもお話が出ましたけれども、貼り忘れとか、飛んでしまうとか、現状で、どのぐらいの割合でそういうものがあるのかはいかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"確実にないとは言い切れないので、例えば一回貼って剥がしたものを、もう一回別のものに貼っているというケースですと、飛んでしまったりとか、そういうケースもあったりしまして、回収できていないという苦情を受けて、実際、手続をやっているのかどうかを調べながら。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"これを、貼っていないから、先ほど西本委員の質疑の中であったようなことを繰り返すというのは、その２点において、本当にこの条例改正がいいのかということも懸念されるので、そこはもう少し踏み込んだ考え方、例えばオンラインですから、写真を撮って添付するとかということも、今は国の事業でも民間でもやっていますので、業務の効率化、環境問題という部分から、この条例改正が資するように。","respondent":"品川品川区清掃事務所長","answer":"委員からお話があったように、画像添付。今の時代は非常に進めていかなければいけない方法ですので、こういった部分についても研究をしていきたいと考えています。","id":"exchange-008"},{"speaker":"まつざわ副委員長","kind":"確認","question":"今のシールをつけていなかったものが残っているというお話がありましたけれども、私も最近、粗大ごみを出したことがある。私の感覚だと、シールがごみになるから、オンラインになると、それがないのかなと思ったら、ごみと言ったら失礼ですけれども、また紙を貼るということは、結局、ごみのシールが紙に変わったということで、すごく細かいけれども、ごみは１個増えるという部分になるわけではないですか。","respondent":"品川品川区清掃事務所長","answer":"こういったところも、稼働までにいろいろと工夫していきたいと思います。それから、先ほども出たとおり、画像で判別させるというのは非常にいい方法ですので、こういった部分については研究をしていきたいと考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"第２９号議案、品川区道路の構造の技術的基準に関する条例の一部を改正する条例","agenda":"第２９号議案、品川区道路の構造の技術的基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"自転車通行帯を区が位置づけるということで、幅が今回、１ｍ以上ということですけれども、１ｍ以上とした理由を伺います。それと、自動運行補助施設というのも位置づけられたということで、これはどういったときに必要になってくるのか、想定されているのかというところで伺いたいのと、区内で設置をする予定というのは今のところあるのかどうか、伺います。","respondent":"森道路課長","answer":"ですので、より正確な自動運転を進めていくために必須なものと考えております。それから、設置予定ですけれども、自動運転は今、かなり進んでおりますが、今のところ、区の道路の中で設置する予定はございません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"自転車通行帯のところは、現在大体０.９ｍ前後ということで、そうすると、そこを自転車通行帯として指定できるということなのか、それとも１ｍにしなければいけないのかというところも伺いたいと思います。それと併せて、歩行者利便増進道路なのですけれども、これも今回位置づけられるということで、これはどういう仕組みで指定をされるのか、まず仕組みを伺いたいと思います。","respondent":"森道路課長","answer":"そのルートに合わせて来年度以降、１０年間でどういった優先順位で、どういった整備形態でやっていくかというのを決めていきまして、それに基づいて少しずつ進めていくという予定でおります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"それと、指定をすると、本来道路であるところにベンチとかが置かれて占用されるということになると思うのですが、その占用期間はどのくらいになるのか、また、占用するということは、普通に考えれば道路占用料というのがあると思うのですけれども、それは幾らになるとか、存在するのかどうかも含めて伺いたいと思います。","respondent":"森道路課長","answer":"区外からの参入ですとか、そういったことですけれども、今回は歩行者利便増進道路という規定を追加して、そういったものができる土台を条例の中でつくると考えていまして、具体的にどういった職種の方がというところまでは、想定といいますか、予定はないのですけれども、今。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"道路を指定してにぎわいが出ると、人が集まってくるとなると、沿道の方々にも影響してくるということになると思うので、住民の声を取り入れる仕組みがあるのかどうかというところを伺いたいと思います。それで、区内でこうした歩行者利便増進道路として指定をしようとしているところはあるのかどうか、どういった利用を想定されているのかというところを伺えればと思います。","respondent":"森道路課長","answer":"ですので、他自治体の事例を参考にしながら、しっかりとお話を伺いながら進めていくことになるだろうと考えています。それから、予定箇所につきましては、具体的にここというところが、今整理できているものではございません。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"特に広い道路というのは、なかなか品川区内にないのかなとは思うのですけれども、そうなってくると、いろいろ再開発などで生み出されたところとか、広場をつくったりした道路上のところが対象になってくるのかなという感じも思うのですが、そうしたこともあり得るのかどうか伺います。","respondent":"森道路課長","answer":"基本的には、先ほど申しましたけれども、具体的な場所は決まっておりませんが、マスタープランの中で示されている道路空間をしっかりと活用するということを受けまして、それの土台となるような条例改正ですので、そういった部分を踏まえて。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"公募のところでいろいろ聞いてきましたけれども、実際この公募を、占用制度というのは付加できるということなので、区としては、やることを想定されているのかどうかというところと、公募をしない場合というのはどうなるのかというところも伺いたいと思います。","respondent":"森道路課長","answer":"それと、再開発で比較的広げていくということとは直接関係せずに、実際に道路の空間が利活用できるというところを、地域の方々としっかりとお話をしながら決めていくことになるのだろうと思っていますので。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"幾つか確認をしたいと思います。これは現状として、先ほど０.９ｍもあるということなのですが、これを広げるということですか。これから何かあったときに、この条例を改正することによって、やりやすくするためのものなのです、今はないですということなのか、現状を、これから再開発とか、いろいろやっていくのですけれども、それを踏まえて指導していくのですかというところも含めて教えてください。","respondent":"森道路課長","answer":"マスタープランの中にはしっかりとそういった部分を書いてありますけれども、今後そういった道路がしっかりとできたときに、スムーズに区として対応が取れるように、条例に位置づけたいということが今回の趣旨です。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"自転車通行帯ですけれども、やはり怖いです。そして、(2)の交通安全施設なのですけれども、ということは、順次品川区もこれを設置する方向で、道路の改修とか道路の整備をするときに導入していきますということなのか、そこを教えてください。そういう告知をするのかしないのか、今は全く該当する道路がないので、別に告知するほどのものではないということなのか、その状況を教えてください。","respondent":"森道路課長","answer":"歩行者利便増進道路を区民にお知らせするのかですが、今、さすがにここでということが具体的にない中で、お知らせすることが限られてくるかなと思いますので、実際にそういった動きが出てきた中で。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"ポチ２のところに、「滞留空間や」の次、設置すべき施設等の規定を追加するということで、ここの有効な空間を活用しようとする際に、この読み方なのですが、設置すべき施設ということ、何かを設置しないといけないとなると、せっかく有効なスペースを、逆にこれを利用するために、そこを制限するような施設をつくらざるを得ないと受け止めていいのかどうかというところの、少し細かい話でありますが。","respondent":"森道路課長","answer":"長さについては、その道路それぞれに決まってくるものだろうと思いますけれども、にぎわいを生み出すからといって、委員おっしゃられたような今の通行がより制限されたりとか、あるいは交通安全上課題が出てくるとか。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"通行帯と、歩道上のこういうレーンができているところは、自転車がそこのみを走るので問題ないのですが、ここが途切れるようなところは、歩道上を通行せざるを得ないような場所に、段差解消といったことで誘導してもいけないですし、段差があることで特に、これは自転車とは違いますが、車椅子の方などが一般の車道から歩道に上がる際には、段差の解消が、よく言われるように求められておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"思い返して、当時は、いろいろな商店街とか繁華街の歩道も、これでまたにぎやかになって食いつこうと思ったら、いかんせん品川区はそういうところがなくて、尻すぼみになって、以来５年がたって、今回、区の条例に位置づけられるというところは、非常に意図されているのだろうなと私は理解をしていて、先ほどの２.５ｍの確認とともに、手続的には区が指定するという言い方と、公募により規定されるみたいな。","respondent":"森道路課長","answer":"有効幅員ですが、２.５ｍと申し上げたのは、最低限の幅員であると考えています。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、区道で時速６０km道路というのはどのぐらいあるか、教えていただきたいと思います。それから、(3)のほうは、そうすると有効幅員は今、特段の目安がないというところなのですが、これから区が指定をするということですので、この審査に当たっては一つ、目安検討を、どこかにまた今後、規則とかでするのかもしれませんけれども、そこはご答弁いただきたいと思います。","respondent":"森道路課長","answer":"設計速度が６０km以上ですが、今、八潮のスポーツの森の脇、都立の大井ふ頭中央海浜公園のところですが、そこにつきましては、自転車道という形で整備をしているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"自転車通行帯は、促進計画に基づいて自転車の活用を推進していくというためのもので進めてほしいと思いますが、歩行者利便増進道路は、区外からも応募ができる、道路の占用も最長２０年まで認めるというもので、大規模開発事業者の要望に応えたものだと思います。住民と協議する仕組みがないということもありますし、そのために住民の意向を無視した開発もできるということになってしまいますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"の順番を入れ替えまして、(2)および(3)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方としまして、２件の陳情","agenda":"の順番を入れ替えまして、(2)および(3)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方としまして、２件の陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"大崎西口駅前地区の建物概要、計画概要を伺いたいと思います。用途とか、何階建てとか、高さなどを伺いたいと思います。","respondent":"中道都市開発課長","answer":"今、建物等の状況につきましては、検討中です。まだ正式に決まったものではございません。ですが、準備組合は地域の方々に説明をしています。そうした中では、居住機能を含めた１棟案というところで、地域の方々にご説明をしていると聞いております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"今の説明ですと、居住機能も入った１棟案が示されているということですが、以前は居住機能があったけれども、一回オフィス機能だけになってしまったということで、陳情第５号のほうには、後ろのマンションに移ってくれと言われたということも書かれておりますが、そうした変遷の状況、実際に今、居住機能がそうするとどのぐらいになるのか、区が説明を受けているところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"建物概要につきましては、まだ正式に決まったものではございません。ですので、居住機能のスペースといったものも、今現在検討中と聞いております。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"今検討中ということですが、もともとオフィス１棟案が示されて、自分たちの計画地にも住めないという状況がある中で、やはり住み続けたいという思いで今回出されていると思います。しっかり住民の皆さんに説明をしていく、それがまず大前提ではないかと思いますけれども、いかがでしょうか。そうしたことを含めて、しっかり説明していくということが必要だと思いますが、区の考えを伺います。","respondent":"中道都市開発課長","answer":"住民の方々への説明です。当地区でまず最初に、地域全体の中で、合同説明会を３回行っております。ここの地区はマンションが５棟ありますが、マンションごと、または個別の家屋の方々といった形での説明会というのを、マンションごとに３回ずつ行っているです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところの問題点について、区はどのように捉えているのか伺います。そうした下で再開発を進めて、住民を追い出していくということはやめるべきだと思いますが、いかがでしょうか。そして、準備組合の事務局が、移転を威圧的に迫ってくるということも書かれておりますが、この実態を区がつかんでいるかどうか伺いたいのと、この事務局はどこなのか伺います。","respondent":"中道都市開発課長","answer":"個別対応等が威圧的だですが、区が今聞いていますのは、準備組合といたしましては、３名体制で個別説明を行っているです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"そうした住民が住み続けたいということを保障するようにしていくことが、地方自治体としての役割ではないかと思いますが、いかがでしょうか。こうしたことで進めていくというのはやめるべきだと思いますし、今回この陳情が２件出てきたということで、合意が取れていないと私は思いますが、区の考えを伺いたいと思います。","respondent":"中道都市開発課長","answer":"こうした中で、地域の方々が様々なご意見があるというのも、区は認識しています。ですので、区といたしましては、準備組合に対して、こういった方々に１人でも多く理解をしていただきたいと、丁寧な説明を継続して求めてきているです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"この陳情者の方々は、お一人の方は病気も抱えて、多分、生活が大変なのだと思うのですけれども、今のところに住み続けたいということですから、それを保障する地方自治体であるべきだと思います。最後に１点、確認させていただきたいのが、そうすると、オフィス１棟案というのはなくなったのかどうか伺います。","respondent":"中道都市開発課長","answer":"今回の事業の内容ですが、先ほどの説明のとおり説明会を続けてきたです。令和５年１月の説明会で、準備組合からは、住宅機能を備えた１棟案といったことの資料を基に、説明をしたと聞いております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、オフィス１棟案がなくなったとは言えないけれども、検討中だということですかね。住民の皆さんが住み続けたいと願っている当たり前の願いをむげにしないように、かなえられるようにしていただきたいと思います。そして、私はこの大崎西口駅前地区再開発はやめるべきだと、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"確認","question":"確認を幾つかしたいのですけれども、準備組合でいろいろと進められているのですが、準備組合に対して、区はどういう関わりを持っていくことができるのでしょうか。それは本当にないのですか。にもかかわらず、８割の方が前向きに考えているということは考えにくいです。なので、今回の陳情の中身と、それから、実際の準備組合側とのギャップが非常にあり過ぎると思うのですが、その辺はいかがでしょうか。","respondent":"中道都市開発課長","answer":"今回、８割の方が前向きにということなのですけれども、西口駅前の再開発の計画といったところは、先ほどのご説明のとおり、住居機能を含めた１棟案です。ですが、今回の西側にあります、駅からすると１個後ろの部分で、Ｆ南地区の再開発というところがあります。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"公金は再開発に入っていますよねという意味なのですけれども、それは全然入っていないという理解でいいですか。再開発には公金がある程度、補助金とかいろいろあるとは思うのですけれども、それが入っていないのでしょうか。入っているとすれば、どのぐらい入っているのですかということ。そこがよく分からないです。","respondent":"中道都市開発課長","answer":"先ほどの西口駅南地区のほうにというお話ですけれども、そちらは民民の中でのお話というところになります。民民の中でのお話の中で、今の西口駅前地区に住まわれている方が、先にできる西口駅南地区の再開発のほうに移りませんかというご提案をしていると聞いております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"要するに、Ｆ地区に移動してくださいと。いっときではなくて、そちらに移動してくださいという意味合いでしょうか。でも、西口の再開発について、まだどういうものをつくるか分からないのですよね。整合性がつかないというか、何も決まっていないのにもかかわらず、あちらへ引っ越してくださいというのは、住民たちは納得しないのではないですか。事情が分かれば、その辺をお聞きしたいのですが。","respondent":"中道都市開発課長","answer":"まだ検討中ということで、確定しているわけではないのですけれども、そういったお話があるということは聞いております。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"聞いていて、どういうことが起きているのか分からない。だけれども、２割の方々というのは話し合う余地がまだまだあって、まだ西口のところの状況がはっきりしていないわけだから、そこは丁寧に対応していただきたいと思います。そこのところについての準備組合に対して、区から今回、陳情が２本上がったということがあるので、そこはしっかりと伝えていただきたいと思いますが、いかがですか。","respondent":"中道都市開発課長","answer":"こういった陳情が上がったというところで、不安については、少しでも素早く払拭に努めていただきたいという形は、準備組合には常に言っておりますので、そうした観点も引き続き伝えてまいりたいと思います。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"今回の西口駅前地区の件ですが、今いろいろ質疑を伺っていたときに、事前に頂いている資料には載っていない言葉が行き来しているので、まずそこから確認をしたいのですが、Ｆ地区というのはどこのことをおっしゃっているのか。そこを確認したいと思います。","respondent":"中道都市開発課長","answer":"大崎西口駅前地区のまちづくり検討状況の地図の赤い部分が、当該の西口駅前地区となります。この西側の部分になります。こちらで今現在、西口Ｆ南地区が市街地再開発事業の工事中というところになります。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"確認で、居木神社に向かって参道があって、階段があって、神社に向かっていうと左側が、既に囲われていて工事が進んでいる。右側はまだこれからというところの中で、その視点で言うと、左側の囲われているところが、今議論になっていたＦ地区ということで理解していいのでしょうか。","respondent":"中道都市開発課長","answer":"居木神社の参道を上っていく左側の、今、工事で仮囲いがされているところが、Ｆ南地区になります。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"いろいろ質疑、議論になっている中で、区としてできることとしては、一つは、この話がどんどん進んで、準備組合から再開発組合に移行して、これが本格的にといったときに、そこの交付金が支給されて、いろいろ資金的なところが入って、それに基づいていろいろと指導なりが入るというところと、一般的に、中高層建築物の建築に係る紛争の予防と調整に関する条例で、建築紛争がありますけれども。","respondent":"中道都市開発課長","answer":"説明会につきましては、準備組合が主体となって、地域の方々に今後のまちづくりについてご説明をしています。ですので、区としましては、そこについては、特に区が主体的に説明をしているというものではございません。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"もう一度確認ですが、中高層の紛争に関しては、建物と近隣の方との調整で、説明会を設けなさいという視点であって、今回行われているのは、再開発の中の地権者の方に向けてということで、それに対しては、区は具体的に説明会を、今後４回目、５回目をしなさいと言える立場ではないということで受け止めていいのでしょうか。","respondent":"中道都市開発課長","answer":"その説明の仕方、回数などについては、区としましては、特にそこに対して、何か強制力を持った指示というものはできない状況ですが、地域の方々が１人でも不安がないような形で、丁寧にやっていただきたいというお願いは、常日頃から行っているです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味で言うと、日本は自由主義国家でありますので、私有財産制も認められているところでありまして、民民のお話の中で、行政としてどこまで対応できるかというのは、一定の制限は当然ある上で、ただ一方で、お互いに区民の方同士の話でもあるので、そこは今の行える範囲の中で、地域の方々、両者の方に対して、話合い、丁寧な説明といったところは。","respondent":"中道都市開発課長","answer":"市街地再開発事業を行っていくというところで、地域主体のまちづくりというところを区は支援していきたいですので、１人でも多く、不安な部分を解消して、前に進んでいただきたいというところで、区としましては、準備組合または組合に対して。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"１点だけ、先ほどの後ろのマンション、Ｆ南地区に８割の方が移ることに賛同しているということなのですが、民民の話だということなのですけれども、マンションに入れるということは保証されるのかどうか。権利変換ということでは、再開発事業の中ではやられないということで、Ｆ南地区のマンションに確実に移れますということは言えるのかどうか、そういう仕組みがあるのかも含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"実際にその８割の方が移るかどうかというのは、今後の個人の考えですが、移るというところで前向きに捉えている方が８割いるということを聞いているです。保証ですが、いわゆる権利の不動産のお話ですので、契約等を踏まえて進んでいくものと、区としては認識しています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、契約ということですから、契約が折り合わなければ移れないということにもなってくるのかなと思います。本当に住まいが保証されるのかという問題もありますし、先ほどから、住み続けたい人が住み続けられないということで、今、準備組合という状況ですから、まだ中止することができると思いますので、それはやめるべきだと改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"まつざわ副委員長","kind":"意見","question":"結論を出すで、不採択でお願いします。いろいろお話を聞いてまいりました。まちづくりというのは、基本、地権者の方の話合い、準備組合の中の話合いの中で、行政がどうこう介入するというのがなかなかない部分ではありますが、大きな集会が３回ずつあって、個別に入ったという話も聞いていますが、引き続き、お話を丁寧に聞くように周知していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"若林委員","kind":"確認","question":"本日結論を出すでお願いします。質疑で確認もいたしました、準備組合に対する区の直接的な強制力、権限というのは、現在はあまりないという中で、準備組合からの説明の仕方においては、８割の方はご納得いただいているという部分がある一方で、ざっくり２割の方は、まだまだご納得というか、理解、認識、説明を十分に受けていないということを、この２つの陳情の中で確認もできました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住み続けたいと願う住民を追い出すものであり、住民が何も分からないまま進められているということで、しっかり説明すべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。品川区の権限というのはあまり大きくはないかと思いますけれども、しっかりと伝えていただきたいと思います。それから、まだ２割の方々が納得されていないということを考えると、十分納得した上で、まちづくりというのを進めていかなければならないと考えていますので、そちらも強く求めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"田中委員","kind":"意見","question":"結論を出すでお願いしたいと思います。先ほどの質疑を通じまして、品川区ができること、そしてまた、できることの中において、しっかり丁寧な説明を今後も引き続きしていただけるというお話もございましたので、そこはぜひ尽くしていただいた上で、この陳情に関しましては、不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。私はこの中に、説明が二転三転しているということ、そういう認識だということだと思います。受ける側としては、そういう気持ちがあるということなので、それも踏まえて、準備組合等々には丁寧な進め方をしていただきたいとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いしたいと思います。理由につきましては、陳情第４号と同趣旨であります。ただ、引き続き区役所としては、丁寧な説明を求めていただけるようなご対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"特に今回、陳情代表者を含め３８名が名を連ねて計画変更を求めているということで、これをどのように受け止めているのか伺いたいと思います。それと今回の東五反田二丁目第３地区の建物の概要、どういったものになっているのか、高さ等を含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"組合のほうは、令和６年９月までに何かしらの方針等を報告するといった形をこの陳情者の方々にお伝えをしたということも聞いておりますので、区といたしましては、組合が今検討している動向というものを注視していきたいと考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ話合いは行っているというような説明でした。それが実際今になって、今５年は過ぎているということですか、その段でもまだこうした声が上がって、変わっていないということだと思うのですけれども、令和元年９月の説明会でも検討したいということは言っていたようですが、その説明会から実際変更した部分があるのかどうか、区の把握しているところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"今回のこういった計画、建物の配置等について、令和元年９月の近隣説明会の中では、まずはそこから、今回の計画で建物の配置等について大きい変更は特になかったというような認識です。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"実際にセットバックをしたというところでも、このガラスの映り込みなどはあるということも書かれておりますが、実際、確かにガラス面がきれいに垂直にあるとここに映り込んで、ほかのマンションの階も見えてしまうということもあり得るのかなと思うのですけれども、区の認識を伺いたいということと、やはりそういった面でいえば、このガラス面に角度をつければそういったことはないのかなと思うのですが。","respondent":"中道都市開発課長","answer":"ガラスの映り込みですが、ガラス等の仕様につきましては、事業計画の中などでまだ検討中というところで、実際にどのガラスを使うか、ガラスは使うとは思うのですけれども、どういったガラスを使う、詳細な部分については今検討しているという状況ですので。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"仕様は今検討中ということですけれども、これはもうある意味当初から、令和元年９月から、そういった声は上がっているわけですから、そうしたところを、本来であればもうそこは住民に配慮して、早めに決めてもいいのかなという気はいたします。ぜひ住民への配慮をしっかりしていただきたいということで、伺いたいと思います。","respondent":"中道都市開発課長","answer":"今組合のほうでは、住民の方とお話合いをして、そうしたブラインドの運用なども含めて今後検討していきますというようなところ、検討するといった形で、答えのほうは令和６年９月までには一定程度示すというようなお話もいただいておりますので、区としましては。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"ゲートシティのほうでは計画決定前からお話合いをされてきたと。本来そういったことが必要だと思うのですけれども、そもそもこの東五反田二丁目第３地区は、決定される前の説明会でも実際同じ要望が出ていたわけですから、住民の要望を反映してやっていくことが必要かなと思うのですが、区の紛争予防条例でも、近隣住民との良好な関係を保持するようにということで求めていると思います。","respondent":"中道都市開発課長","answer":"近隣説明会のほうで、プライバシーの確保をというご質問があったですが、事業者側のそのときの回答としては、個別の対応と認識していると答えたということは聞いてあります。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした状況があるという中で、やはりしっかり意見を区のほうに届けてもらうということができなかったと思うので、そうした説明会の周知の方法も検討いただきたいと思うのです。例えば通常建物の説明会を行うときは、高さの２倍の範囲にチラシをまいたりということをやりますが、そうしたこともしっかりして周知をしていくということをやるべきではないかと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"その周知という部分につきましては、やはりより皆様に知っていただく機会といったものをどのように設けていくのかということは検討してまいりたいと思います。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ広く知らせていただいて、きちんと意見を出せる、出してもらえるようにしていただきたいと思いますし、区が、この答弁の中でも調整役はやっていきたいということですので、ぜひ調整していっていただいて、住民と事業者との横の関係が保持できるようにしていっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"確認","question":"少し制度的なところを確認させてほしいのですけれども、この外観などの規制というものは何かあるのですか。例えば、ここのこれまでの経緯というところがあって、都市計画などがあって、この建物自体の規制というものが決められたものがあるのでしょうかということが１つです。そこであります。","respondent":"中道都市開発課長","answer":"ですから、今回道路が１２ｍ、空地がお互いに１２ｍずつの３６ｍという空間を設けているというところで、地区計画以上の空間を設けているというところで、一定程度配慮はしている、事業者としましては、そういった考えで事業を計画したというところで、お話は聞いているです。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"その場合チェックをするという、そのような機関というものは品川区に設けられているのですか。それを、プライバシーなど、個人的なプライバシーについてはやはりかなり配慮をしなければいけないとは思うのですけれども、そこをチェックするということは、これから建設に当たってと、この前の段階ですけれども、計画の段階でどこまで品川区が強く申し上げることができるのでしょうか。","respondent":"鈴木都市計画課長","answer":"都市計画課のほうで景観の関係を所管しておりますので、私のほうからお答えするのですが、この地区、大崎駅周辺地区ということで、景観形成の基準が定められている、重点地区に定められておりまして、そうした基準が定められております。","id":"exchange-056"},{"speaker":"西本委員","kind":"確認","question":"だって映り込んだら嫌ではないですか。だからそれは、私は事業者のほうは考えているのだろうなと思ってはおりますけれども、やはりそこは本当にそうなっているのかという、品川区としてのチェックする段階というか、そのようなものがあると助かるなと思うのですが、これは景観法のところでチェックすることは可能なのでしょうか。決まりはないにしろ。そのようなところで確認作業はできないのでしょうか。","respondent":"鈴木都市計画課長","answer":"プライバシーの観点で、景観条例も区のほうにはありますけれども、そうした中で、条例の中ではプライバシーに関する、何か基準やチェック項目が設けられておりませんので、なかなかプライバシーに関する部分について、景観の観点から区は指導等。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、やはり住んでいる方々を守っていくという、そのような態度というものは、やはり品川区としては必要なことだと思いますので、どの機会でできるのか分かりませんが、今回このような陳情が出てきているので、またかなり心配されているということは十分に、準備組合の方、再開発に携わっている方、建築担当の方、関係者に、強く申し上げていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"プライバシーというと、なかなか数字で表すということが難しく、お互い感情的な、もう見え方も含めてになりますので、私の知る限り、他自治体でプライバシーに踏み込んで何か条例を定めてチェックをかけているという事例は聞いたことがないのですが、区としては。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問","question":"午前中の大崎地区でのお話も同様でありますけれども、日本は法治国家なので、法律に基づいた対応しかできないという前提がある中で、ただ一方で、住民の方のご心配事は、では法の範囲の中でどうやって対処できるかということを追求していかなければいけないという、そのような視点でお伺いをしますが、今回パークタワー東京サウスの住民の方々が陳情を出されていらっしゃいます。","respondent":"中道都市開発課長","answer":"今回の陳情の、区のほうに声が届いているものは、このパークタワーの方々のみということになっております。","id":"exchange-059"},{"speaker":"田中委員","kind":"確認","question":"すみません。改めて確認なのですが、マークウエストはいわゆる業務棟という位置づけなのでしょうか。","respondent":"中道都市開発課長","answer":"業務棟になります。","id":"exchange-060"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、恐らくパークタワーの方々同様に、今回の新たに再開発内にできる住宅棟に住む方々からも、今回の業務棟に対してのプライバシーの侵害があってはならぬという思いは、恐らく、これから建設されるものですし、これから住まわれる方が入ってくるわけですが、やはり同様の視点で感じるだろうと推測をするのですけれども、同じ地区内での開発で業務棟と住宅棟がそれぞれできる。","respondent":"中道都市開発課長","answer":"配慮ですけれども、まだガラスの仕様や、ブラインドの運用など、そうしたことも含めて、今後検討していくというように聞いていますので、区としましては、そうしたところも踏まえて、周辺住民への配慮といったところを確認していきたいと考えております。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"恐らく、私は子どもの立場から立っても、同様の心配事、特に子ども自身ですし、保護者の方々からも、同様の心配事は当然起きてくると思いますので、私は区の立場で言えるものとしては、１つは区立義務教育学校を運営する主体として、しっかりそこへの子どもに対する安全性、プライバシーの確保といった視点からも、私はしっかり物申していただきたいですし、そのときに併せて近隣の方々の懸念事項も。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、細かいガラス部の仕様というものは今後検討していくということになりますので、そうしたところで、周辺への配慮といったものをどの程度組合は考えているのかといったところを、区としては注視していきたいと考えております。","id":"exchange-062"},{"speaker":"田中委員","kind":"意見","question":"今の前段の話は、セットバックして空地をということは平面の話でありまして、プライバシーというものは、上空から、上層階から反対側をのぞけるかどうかとか、あるいは校庭を見下ろす際に子どものプライバシーをどう確保するかという視点なので、そこは今後、先方も検討されるというお話ですし、今後区の立場としても、強制はないものの、要請というか、このような声があるということも含め、あともう一つは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"若林委員","kind":"質問・要望","question":"２月に建築側とこの陳情者の方々との協議、お話合いがされて、９月までに一定のお答えがあると。この９月というものは、建築はどのような状況になっているのか、スケジュール的に教えていただきたいということと、あわせて、なぜ９月までご回答が、検討がかかるのかというところも、何かご承知されているところがあれば教えてください。","respondent":"中道都市開発課長","answer":"外の熱をあまり建物の中に入れると、どうしても暖房であったり、冷房であったりという環境性能が悪くなるという、そこの工夫といたしましては、一定程度反射をさせるというところがガラスの特性で、そうすると熱を中に入れないと、そういったものがあるのですけれども。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"ガラスの熱の件は、新庁舎の話の中でもご説明、基本設計の中間報告で、ああ、なるほどなと。この資料の中の、もう１点伺いたいことは、住宅棟が西側にあって、業務棟が東側にあると。通常この地図だけを見ると、なぜ住宅棟が西側にあるのかなと。要するに業務棟で日中は日照が遮られるわけです。ということで、この配置はなぜこのような形になったのかということはいかがでしょうか。","respondent":"中道都市開発課長","answer":"事業計画のこういった建物計画につきましては組合のほうで検討されてきたというところで、詳細にこの配置になった理由というものは、なかなか区が全て知るものではないという認識ですが、今回は１,５００m2の大きい公園をつくるといったところも。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"ということで、想像の範囲ですけれども、公園の話もありましたが、逆にこの配置で、もっと抜き差しならない状況にはならなかったのかなというところから見て、この業務棟についても、もう既に質疑が重ねられておりますけれども、やはり住環境をしっかりと、近隣のマンションにお住まいの方を守るというところで、この業務棟のことについても、区のできる権限の中で、また範囲の中で。","respondent":"中道都市開発課長","answer":"区といたしまして、こういったまちづくりの中で、周辺の住民の方々、または今回新しく移り住む方々、新しく働く方々、そうした中で、皆様がいいまち、いい働き場であるといった形を区としてもつくっていきたいと考えておりますので。","id":"exchange-066"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"しかし、一方でプライバシーの侵害という配慮、１２ｍ、１２ｍ下がった３６ｍのこの空間が、要は業者のほうが空間を設置しているからいいというのか、それともやはり住民の声が、それでも配慮が足りないということが、ここが重要な観点だと思っていますので、区としてなかなか追及することが少ないということも認識しておりますが、やはりこういった課題があるという以上、今回このような陳情に上がった以上。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すでお願いします。今一重の、この業務棟に関しては、近隣住民の方のプライバシーと住環境を守るよう、品川区からも積極的に引き続き取り組んでいただくというご答弁もいただきました。一方で、この業務棟の設計変更など、そのようなご要望については、区の権限の中で強制力がないということもありますので、陳情としては不採択という結論になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。やはり住民に配慮した計画にすべきだと考えますので、採択をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。プライバシー、先ほども確認させていただきましたが、それを規定するものが何もないということにおいては、今後条例化するかしないかは別にしても、チェック機関というものは何かしらあってよかろうかなと思います。今後そのようなことも配慮していただきたいなという思いがありますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、先ほど述べましたように、区ができる範囲のことはやっていただいている上で、業務棟に関しましては、同じ敷地内にできる住宅棟への配慮は当然するものと思われますので、同様の配慮は近隣住民にも、住宅にもしていただきたいことと、学校の立場からも、しっかり配慮してもらいたいということをしっかりお伝えしていただくという前提で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、先ほどの陳情第７号と同様の理由から、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"今回、記念碑があって、そこに様々再開発組合員の方、理事長や副理事長代理等、いろいろ名前が書かれているということで、ここについて伺いたいのですが、その記念碑について、地権者の全員の名前が書かれているのかどうかというところと、陳情の中でもこの再開発組合役員の中で、これは組合員でない人というものはいるのかどうかというところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"あくまでこれは組合のほうがつくったものです。理事等、組合員ではない方ですが、もともとここに権利者でいらっしゃった方が、引っ越し等の理由で権利者でなくなった方、もしくは事業協力者といった方はいるというようなことは聞いております。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"役員の中で、そうすると何名の方が組合員で、何名の方が組合員ではないのかというところを伺いたいと思います。この陳情の中では、再開発についての合意がしっかり取れているのかということも言われていますので、そこのところの確認もさせていただきたいと思います。","respondent":"中道都市開発課長","answer":"３４.５といった形で、０.５名ですが、共同名義の方がいらっしゃいますので、こういったところは小数といった形になってあります。ここの同意率といたしましては、８０.２％といったところです。こうした中で、適正に組合のほうが設立していると区は認識しています。","id":"exchange-074"},{"speaker":"若林委員","kind":"意見","question":"議事進行。前回の陳情審査を思い出していただければ結構だと思うのですが、退場させました。この状況を許すと、ほかの陳情者の方も、品川区議会の委員会というものは、傍聴席で審議妨害をしてもいいのだと、このように勘違いをされるおそれもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"この間、説明があったところから、パルム駅前地区については、たしか８８％というご説明だったと思うのですが、それが４％増えているということですけれども、そことの関係を伺いたいと思います。この陳情にも、空き店舗はたくさんあるということで出されておりますけれども、そこの実際戻ってきた住民の方というものはどれだけいらっしゃるのかということを伺います。","respondent":"中道都市開発課長","answer":"実際に戻ってきた方ですが、権利変換の中で、区としては、最終的には戻ってくるのか、または外に引っ越しをされるのかということは、把握できる部分ではありますけれども、一方でその後に民民間での売買等があると、区としては、なかなか詳細な部分は把握できないです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際現在はどうかということが分からないというお話でしたけれども、事業が終わったときというのですか、建物ができたときに戻ってきた方というものは分かるということですので、明らかにしていただきたいと思いますが、いかがでしょうかというところです。そこをしっかりと明らかにしていきたいと思いますので、ご答弁いただけたらと思います。","respondent":"中道都市開発課長","answer":"住民の方ですが、権利変換後に個人で権利を売買、要するに土地、自分の新しい建物の権利を個人で売買しているというような状況もあると、区としては、そこの部分についてはなかなか把握ができないです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、権利変換時の同意と残留の数というものは、割合というものは完璧に一致しているということでいいのか、そこのところを伺いたいと思います。やはり今まで隣の、近所の方とつながりがあったというものが、再開発でこうした近所付き合いがなくなってしまっているということだと思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"そうした中で様々、今イベントやサークルなどが行われているというところで、行政の側としますと、そういった中でコミュニティというものは形成されていっているというような認識です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、そうすると地権者の数つながりで、現在の小山三丁目第１・第２地区の地権者数、区分所有者数も教えていただきたいと思いますが、借地権者数で、同意をしている方の人数と割合を伺いたいと思います。","respondent":"中道都市開発課長","answer":"そういった近所付き合いがどうだというところは、行政としてはなかなか把握できないところではありますが、区としましては、駅前の広場といったところで、イベントなどができるスペースをつくったり、滞留空間を設ける。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"合意はきちんと得られていないと思います。実際、今陳情の中でもありましたけれども、同意を広げていくというところで、区の職員が３月３１日までに本組合の設立を行っていくということで、地域の方に回っているというようなことが書かれてありましたが、実際そうしたことを行っているのかどうか、もし行っているのであれば、なぜ区はそうしたことを職員にさせているのかというところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"陳情には、令和６年３月３１日までに行うといった形が書いておりますけれども、区としてはそのような対応はしていないです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"そう受け取られるということはよくないということだと思いますので、それは気をつけていただきたいと思います。まさに陳情でも事実との乖離があるということで言われていますので、ご説明いただきたいと思います。中小企業では、やはりなかなか大変だということで、そうした再開発を進めていくということが、大企業の支援をしていくということにつながると思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"その工事自体が地域の活性化といったものも、１つ要素としてあるかというように認識はしております。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"構想のところでは、やはり区としてはマスタープランビジョンというものは確かにつくっていると思います。そうした中で、区も一体になって進めているということかなと思いました。そうすると、そこを優遇していると。これは区としてはどのように考えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"はその大企業、やはりそういったところは技術力であったり、そういったところでも安心感といったものにもつながっているかと考えております。物価高騰についてですが、やはり今、世の中では資材が高騰しています。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"物価高騰ですね。認可時に資金計画を出されるということで、そうすると区としては、そこで事業の破綻のリスクはないと考えているのかどうかというところを伺いたいと思います。この間質疑をしてきたところで、やはり再開発によってコミュニティも壊され、住み続けたいという人が住み続けられないということになっておりますので、こうした再開発はやめるべきだということは言っておきたいと思います。","respondent":"中道都市開発課長","answer":"事業破綻ですけれども、繰り返しの答弁になりますが、そうした資金計画というものは、今事業者のほうで、今の状況に合わせて再度見直して、事業といったものをどのように行うのかということは検討しています。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"この再開発をして、商店街のほうのにぎわい、それから住民が戻ってきたかどうかなど、いろいろな観点から評価をしてほしいということだと思うのです。その検証というところを考えられたかどうかということを、まず１点お聞きしたいと思います。ですから、そのようなことを、品川区民の皆様方に説明できないようなことをしているのかどうかということをお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"はそうした中で、市街地再開発事業であれば、そうした方向性にのっとって適正にまちづくりが行われるかどうかということはやはり判断をしながら、また、そういった途中、途中できちんと説明会等を踏まえて。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"その課題は何で、それを解決するためにこれからどのような手順を踏んでいくのか、それをどう住民たちに、地域の方々にご理解していただいて、一緒に進めていけるものなのかというように、やはり再開発をして、武蔵小山はすごく大きな開発になりますので、いろいろな事情があるかと思いますけれども、そこはしっかりと基準というものをそろそろ、基準というのですか、目標というのですか。","respondent":"中道都市開発課長","answer":"公金、補助金の使い道ということで、事務事業評価も併せてですけれども、予算特別委員会、決算特別委員会、もしくは国のほうからの会計検査といったところで、区といたしましては、そうした機会を設けてきちんと対応していっているというところで。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"伺いたいと思います。不信感が募ってしまった結果かなと思うのですけれども、今回この旧荏原第一地域センターは、武蔵小山のビル２階というところで、それを今も品川区が所有しているのかというところと、今後の利用計画ということで、資料に出ていますが、それを伺いたいということと、新しい地域センターが再開発ビルに入ったのはなぜなのかというところも陳情にありましたので、伺いたいと思います。","respondent":"中道都市開発課長","answer":"今後も継続して図書の取次所といったところ、武蔵小山には図書館が今現在ございませんので、こういった図書の取次所で本に対して触れていただきたいというところで、継続して図書取次所を行っていきたいと考えています。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"それと、旧荏原第一地域センターのところの購入費と経緯についても説明してほしいということで、購入費から現在までに無駄がなかったのかということで分析や評価はしているのかというところを伺いたいということと、購入費用が駅前通り地区の補助金７４億円に含まれているのかというところも聞いておりますので、ご説明いただければと思います。","respondent":"中道都市開発課長","answer":"こうしたものも、予算特別委員会やこういった委員会の場で報告等しまして、区としましては適正な執行であると認識しています。補助金に入っているのかですが、これは過去の、旧地域センターはもちろん昭和５４年の契約ということなので、今回の補助金には入っていないです。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした中で、この陳情の中にも、第２地区の権利者でいるためにこの地域センターを保有しているのかということも言われているという状況なわけです。そうしたところで、またこの小山三丁目第１・第２地区でも、同様のことが起こりかねないということになると思いますので、小山三丁目第１・第２地区について、その再開発を中止すべきだと、これは強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。そしてまた駐輪場、地域センターと、地域の陳情、また要望が組み込まれた開発だと考えています。しかしながら、やはり再開発というものはいろいろな言葉、いろいろな住民の気持ちというものがありますので、引き続き区としては、聞ける限りしっかりとした対応を取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにいたしましても、いわゆる都市再開発法等法令にのっとって、地権者の方々と事業者、そして都市計画決定を経て、品川区もそれにのっとって公金を投入するという、しっかりとした一定の手続の下進められているものと理解をしておりますので、今後の再開発についても、しっかりと、談合とか、捏造とかという、陳情、また質疑もありましたけれども、そのようなご指摘を当然受けない、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。先ほども申し上げましたけれども、まちづくりマスタープランはいろいろあるわけです。その中で、方向性を区としては示しておりますよと。どうだったかということはなかなか公表されていないというところもあって、それが今回の陳情等々で分かったかなと思いますので、その辺は今後の検討材料にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"近隣の大きな課題はいろいろあります。区役所から相当離れた西の目黒区に近いところでありますので、そのような意味では、区役所の出張所機能というものは、地域としてぜひとも求められるところでありまして、今回の再開発を機に、大きな拠点としてつくっていただけているということも、地域にとっても貢献されていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"のだて委員","kind":"確認","question":"本日結論を出すということで、趣旨採択です。職員の発言は事実確認ができないですけれども、住民は３月３１日に申請するという受け止めをしているわけですので、そうした脅すようなことはやめるべきだと思いますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。それで私の意見は不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択です。一致しない部分もありますが、全体として住民追い出しの再開発中止を求めるもので、やめるべきだと私も思いますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。大企業の利益を生み出す超高層再開発事業に税金を投入するということはやめるべきだと、考え直すべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。小山三丁目第１地区・第２地区の再開発は、現居住者を住み続けられなくするという計画であり、中止すべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出す、不採択でお願いします。再開発の在り方というものはやはり、これから大きな課題になると思います。ただ、その課題を含めつつ、中止というところかどうなのかというところについては、まだ同意という形はできませんので、不採択という形にいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"のだて委員","kind":"確認","question":"本日結論を出すということで、採択です。税金を投入してまで実施された事業ですので、確認、検証をすべきだと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。この陳情の趣旨というものは、住民合意の在り方を示されているのだろうと思います。ですから、住民合意というものは必要なことではあるものの、そのやり方については今後研究していただきたいという思いで、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"若林委員","kind":"確認","question":"本日結論を出すで、荏原第一地域センターおよび武蔵小山駅前周辺地域の行政サービスの拡充ということも確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択です。説明を求めるものですので、区としても疑念を晴らすためにも説明すべきだと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。まだまだ説明については不足している部分があるのだろうなということは実感をいたしました。これを今後改善をしていただきたいと要望いたしまして、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"このしながわお休み石を設置してきたということで、このお休み石の役割を伺いたいと思います。そして経費についても書かれているので伺いたいのですが、このお休み石の維持管理費と設置するときの経費、それを伺いたいと思います。そして、今後このお休み石を増やしていこうというお考えはあるのかどうかというところ、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それから今後ですが、平成８年度事業を開始した当時は、例えばですが、平成１０年には４５基ですとか、あるいは平成１３年、平成１４年は２３基、２８基、非常に設置できる場所も多かったというところで、予算をしっかり組んで整備を進めてきてございまして、平成２１年度。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"お休み石として、やはり様々役割を発揮してウェルビーイングにもつながるということで、今は維持管理をやっているということですが、住民の要望によっては増やすということなのか、そこのところを伺いたいということと、現状で、区としては十分だと考えているのかどうかも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"イメージしていただくと、品川区内で都道、国道ということが、広幅員の道路としてはあるわけなのですが、やはり区内の国道、都道というものが、例えば第１京浜など、非常に歩道が狭いというところもあって、計画的に区道ではない国道。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、まちの方からも声があるということですので、ぜひベンチ、このしながわお休み石の設置を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、必要性は物すごく、十分分かるのですけれども、歩道があそこはないので、区道ですが歩道はないので、歩道があるところにしかお休み石は設置できないということで、願意を反映することはちょっとできなかったわけですが、今のだて委員との質疑を伺った中でも、要は限られた、歩道がある、しかも国道、都道の狭い歩道はあって、なかなか設置には適さないような場所も考えられている中で。","respondent":"鈴木都市計画課長","answer":"区内の区道、都道、国道、歩道があるところを全て調査をかけて、設置可能な場所を全て整理をしたというところは今までございませんので、ただ、私もあの当時担当として、この地域を調査をかけて回ってきた中では、やはり相当設置も進めてきて、設置できる可能性のあるところは。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"ベンチとしては、お休み石以外でいうと、公園がありますけれども、公園の中にはほぼほぼ、もう１００％に近いというか、恐らく１００％かなと思いますが、ベンチは設置されているという状況なのでしょうか。","respondent":"高梨公園課長","answer":"区では現在２７４か所の公園・児童遊園を管理しておるのですが、その中のほぼほとんどの公園・児童遊園の中には、ベンチが設置されているものというように認識しております。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問","question":"そのような意味でいうと、公共でできるところとしては、例えば公共の施設の入り口周辺などに、スペースがあればですが、そのようなところが可能かどうかということと、もう一つは民間の土地で、そのようなお休み石のようなベンチ類を、ご了解いただいた上でですけれども、設置をするということも、可能性はゼロではないと思うのですが、今までの話は公共施設においてのベンチ設置でしたが。","respondent":"鈴木都市計画課長","answer":"民間の再開発の中で、公開空地的なところに、この事業の趣旨を賛同いただいて、お休み石を設置したケースはあります。","id":"exchange-111"},{"speaker":"田中委員","kind":"意見","question":"そのような意味でも、再開発、先ほど来ずっと議論がありますが、喜ばれるものとしては、そのようなベンチ、お休み石設置なども１つの内容だと思いますので、ぜひこれも再開発を進める上での１つのポイントとしていただいた上で、この陳情者の方の趣旨としては、今現在、公の施設の中で設置可能なところは、これで打切りということでは当然なくて、まだまだ今後も。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"まつざわ副委員長","kind":"確認","question":"お休み石、前回も同じような陳情があって、たしか品川区は随分早くからやられてきて、それで２８４というものも、周囲の区に比べると大変多いということが分かりまして、品川区はそういったところには大変力を入れていただいているなというものが現状です。だから結局、設置できるところも限りがあるから、これからは直していくという、そういった方向性でまず合っているのか確認させてください。","respondent":"鈴木都市計画課長","answer":"一定整備を平成８年度から進めて、ご指摘のとおり座面のところが自然木ですので、そうしたところが風雨にさらされて非常にささくれ立ってきたというところもあって、平成３０年からは計画的に年間４０基ずつ、その座面の改修を行ってきて、今は今度木調のお休み石が。","id":"exchange-113"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"それでベンチはこれ以上、なかなか難しいということは分かったのですけれども、陳情の内容によると、要はお休みをするところが少ないということで歩きづらいということは分かるのです。例えば、所管が違うから要望なのですけれども、たしか今度フレイル予防ではないですが、薬剤師会が、要は熱中症対策で、お休みしていいですよと。どんどん薬局の中に入ってきてお休みしてくださいと。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"これは前回も陳情がありましたので、十分に区のほうの状況は分かっております。それで改修をしているというところですから、なかなか広げることは難しいだろうなと思うのですが、先ほど民間の方々のご協力という中でいうと、これ敷地の中に入ってしまうと、セキュリティの問題があるから無理だと思うのです。宣伝にもなりますので。そのような啓発はできるのではないかなと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"事例的に、それに併せて、誰もが入って使えるようなところにベンチも併せて整備していただいている事例もあって、先ほど景観審議会のお話もさせていただきましたが、景観審議会の委員の方から、やはりファニチャー、ベンチなどといったものは、非常に景観の視点とともに。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すです。可能なところは、今後とも地域の声も含めてしっかりと聴きながら、区として進めていただきたいということで、陳情については不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"木村委員","kind":"質問・要望","question":"本日結論を出します。私は以前このことで採択した記憶がありますけれども、やはりこれから人は年を取り、食事や適度な運動、そして、やはりほっとするその心の安らぎ、それを求めるのは、私はベンチを見るとほっとするのです。そのような意味では、以前もこのことに対しても賛成をいたしましたけれども、今回、心をまた新たに賛成をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。やはり議論の中でも、フレイルやウェルビーイングにも資するものだということで、やはり増やしていくということが健康にも資するということで、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきということで、陳情者の方の趣旨は物すごく分かるので、趣旨採択としたいところでありますが、議会のルールにのっとりまして、また、質疑を通じても、区役所としてできるところは今しっかり対応していただいているということもありましたので、今回は、この内容については不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/250442?Template=document&Id=4400#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":80212,"voices":356}},{"id":"r06-20240226-9","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"文教委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"第１８号議案、品川区立児童センター条例の一部を改正する条例","agenda":"第１８号議案、品川区立児童センター条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"児童センターの運営の現状について伺いたいのですけれども、２５ある児童センターは直営館と委託館に分かれていると思っているのですが、何館ずつぐらいに分かれているのか。それと分かればざっくりでもいいのですけれども、平均の勤続年数など、以上、４点を伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"平均勤続年数については、手元に資料ないので、お答えができません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"資格要件などについてももしあれば、後でお伺いします。２０２２年度ですと、それが５７人と減っているわけですが、このときに２館、委託が拡大したと思うのですけれども、拡大した理由といいますか、２館ぐらいが委託になった、拡大された児童センターの名前を教えてもらいたいのと、あと今後、運営方式を考えるに当たって、区の方針としては委託館を増やしていく考えなのかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"現況をまずちょっとはっきりした上で、今後の運営方針に関わってくるということなので伺っております。よろしくお願いします。","respondent":"藤村子ども育成課長","answer":"こちらはあり方検討の報告等でも申し上げてきたところなのですけれども、若年層の職員とベテラン職員という形で、年齢層が二極化している形なので、職員の育成を図るためもございまして、館のほうに厚めに職員を配置するという目的で、委託を増やしたという形になっております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"区としては、今後、指定管理館を増やしていく考えなのでしょうか、伺いたいと思います。指定管理者による運営になると、これらはどうなるのか伺いたいと思います。委託館や指定管理が増え、直営館が減ってしまうと、直営館のこれらの事業の負担というのは、ますます増え、現行でも大変だという声も聞いているのですけれども、そういった憂いてしまうのではないかと思うのですが、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"親育ち支援事業などといった直営館でやっている事業ですとか、地域の方にご利用いただく事業に関しましても、今、委託館という観点がありますけれども、館長のほうがそちらの管理というか、こういった事業を推進していきましょうというところは全体として取り組んでいるので。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"この児童福祉の提供者が指定管理者に代わると、引継ぎ業務についてはどうなるかといったところが１点と、また、今現在働いている職員についてはどうなるかといったところをお聞きしたいと思います。","respondent":"藤村子ども育成課長","answer":"職員についてですが、どういった業者が選定されるかというところが分からないので、そこの職員の引き継ぎに関しましては、決まった業者によっていくのかなとは思います。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。改正の目的で、より一体的な運営を効率よく行うために指定管理者にということですけど、これは逆に言うと、そういう業者があるということですか。児童発達支援センターを運営したことがあって、児童センターなども運営したことがあるところが、実際に今、既にそういう業者があって、そういうところを見据えた改正案か、そこだけちょっと教えてください。","respondent":"藤村子ども育成課長","answer":"一体的な運営というところで、今回、障害者施設と児童センターという枠組みですので、ピンポイントにそうした業者があるという状態ではないのですけれども、そういった可能性があるような業者もいらっしゃるということなので、そういったところを踏まえて。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"一体的に効率よくというのは分かるのだけれども、それこそ児童センターと児童発達支援センターは別に違うものなので、やはり逆に１つのところがやって、未経験でうまくいかないというのは逆にないように選定をしていただきたいなと思うので、そこだけちょっと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"確認","question":"１点だけ、確認なのですけれども、別紙１のこの平面図、配置計画はあれなのですけれども、２階の新設の避難すべり台というのがあると思うのですが、これは消防法に絡んで児童に対してはすべり台という考え方でいいのですか。階段とかというのもあるのかもしれないのだけれども、「すべり台」という記載があるので、ちょっとどういうことなのかなと。ちょっとその確認だけ、すみません、お願いします。","respondent":"藤村子ども育成課長","answer":"建物に係る部分で、消防法にというところは、細かくお答えはできないところなのですけれども、避難経路の充実というところで、外部階段の改修ですとか、すべり台の新設というところで、今回、加えたものになっておりますので。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"３つ目は、残念ながら、以前、児童発達支援センターに関する指定管理がいろいろ課題があって、途中で交代ということになったのですけれども、児童発達支援センターの指定管理をするというのは大変重要であり、かつ非常に大変な業務だと思うのですが、その辺の指定管理をするときの見込みというか、区としてどういう姿勢で選定していくのかというところをお尋ねします。","respondent":"藤村子ども育成課長","answer":"フローレンスの立場というところですけれども、フローレンスに関しては、今、ベルの委託事業者という立場になっておりますので、選定の中でどうなってくるかというところは、通常どおり、指定管理の公募を行いますので。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"指定管理を否定するつもりは全くなくて、導入する際には、こういった様々な課題を解決して、指定管理していっていただきたいということでちょっとお尋ねしました。児童発達支援センターの中身についてはちょっとここはあれですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問","question":"過去にも２つの事業者の一体の指定管理が、一旦は認められたかなと思ったのですけれども、結局はそれができなくなってしまったということもあって、高橋しんじ議員のご質問はその辺のことをお聞きになられたのかなと思ったんですが、お答えが。","respondent":"藤村子ども育成課長","answer":"例えば今の考えている募集形態として、応募形態として２種類あるかと思いまして、１つの法人が児童センター部分と児童発達支援センター部分を両方とも指定管理を受けるというパターンと、あと共同事業体という形で、１つの業者、例えば２社が組んで。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはり指定管理で任せてしまうということについての行政の立ち位置が難しくなるのではないかという心配の一方で、やはり民間事業者の専門性のある創意工夫が活かされるというメリットもあるというふうに考えておりますので、ぜひその辺をよく見極めた指定管理の業者の選定にしていただきたいのと、やはり共同事業体というように排除しないことになっていますが、ちょっと過去のこともあって。","respondent":"藤村子ども育成課長","answer":"区の指定管理の方針上もこの共同事業体というのは決して排除されているわけではないので、例えば、施設を２社が運営することになれば、どちらがどういった施設管理をしていくとか、そういったところを明確にしていくことができれば。","id":"exchange-012"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"共同事業者については、今しっかりご答弁いただきましたので、もし共同事業体となった場合は、ぜひそのような過去の反省を活かしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"確認","question":"今後、選定される業者にもよるという話もありましたが、現在、働いている職員の対応、引き継ぎなど、慎重な判断と確認をした上で、今までより増した効率的な運営をしていただければと思います。公明党は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほど申し上げました意見をしっかり活かしていただきたいということを前提に賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"今回、大原児童センターに児童発達支援センターを併設して、インクルーシブな空間をつくると。環境を整備するということは私は意味があることだと思っていますけれども、児童センター全体に指定管理者を導入することに、道を開く本条例には賛成できないということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"第１９号議案、品川区子ども・子育て会議条例の一部を改正する条例","agenda":"第１９号議案、品川区子ども・子育て会議条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これから策定予定の品川区子ども計画なのですけれども、この子どもとあるのですが、対象は何歳から何歳ぐらいまでの対象の計画になるのでしょうか、伺います。それと、これまでの子ども・子育て支援事業計画では、重要な計画の内容として、保育需要を把握し、教育・保育施設などの５年間の整備計画を策定してきたと思うのですけれども、この新しい計画ではこれらはどうなるのでしょうかというのが２点目。","respondent":"今井保育教育運営担当課長","answer":"最後、委員のメンバーの中で、若者支援の部分の目線がちょっと薄くなってしまうのではないかというご指摘ですけれども、その辺は区としても十分認識しているところでございまして、現行の子ども・子育て会議のメンバーは。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"先ほどの説明だと、若者のところの部分がどうしても薄くなるので、この５名を追加するのは、若者へのいろいろな施策の有識者を入れるという認識でいいのか、その辺をちょっともう１回、教えてください。","respondent":"今井保育教育運営担当課長","answer":"今回、５名追加するのは、基本的な考え方としては、今回、計画として追加になる子ども・若者計画の部分で、若者支援の知見を有する方ということで、学識経験者の方というよりは、どちらかというと、その知見を有する方という枠で入っていただく予定です。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"意見","question":"いわゆる一本化するとどっちかに比重が行ってしまうと、せっかく一本化して、まとめてよくしようとしているのに、それが一方に偏ってしまうと逆効果を生じてしまう可能性があるので、その辺をぜひバランスを考えて、委員の選定も含めてやっていただければというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問","question":"若者支援の知見を有する方というご答弁が、今までのやり取りの中であったのですけれども、学識経験者とかだと、ある意味、どこかの大学の先生とか、そういうイメージが湧くのですが、若者支援の知見を有する方というのを、どういう基準でどういう感じで選定されるのかなと思って、例えばだから既にそういう事業に携わっている方とか。","respondent":"今井保育教育運営担当課長","answer":"追加になるメンバーについては、現在でもどのような形で、どのようなメンバーで入っていただいたほうがいいのかというところは、検討中のところではあるのですけれども、考え方としては、現在、青少年問題協議会という会議体がございまして。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ただ、せっかく若者支援の知見を有する方という、先ほど基準とか伺いましたけれども、ある意味、少し幅広に捉えるような何か設定の仕方をしたのであれば、ほかにもいろいろな実際の支援を行っておられる方とか、いろいろ多分いらっしゃると思いますので、今のご答弁で了解をいたしましたが、それプラス少し視野を広げたようなことも今後、考えていっていただけたらありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"ゆきた委員","kind":"意見","question":"小・中・高生で、それぞれの幅広いニーズがあると思われます。今後、さらに発展する子ども・子育て会議で、幅広い子ども・若者の声や意見を洗い、媒体を通して吸い上げて反映していただければと思います。公明党は賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"賛成いたします。先ほども意見を言いましたけれども、やはり子ども・子育て支援プラス今、なかなか生きづらい若者も増えているのも承知しておりますので、ぜひその方たちへの支援が行き届くような形にしていただきたいと思います。これは要望です。賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"一体的に計画を検討するメリットもあると思います。賛成するのですけれども、やはりそれぞれの計画で定めていた待機児童解消策ですとか、若者を意識して視野に入れた施策を相対的に薄まってしまったなということがないように、これは強く求めたいというか、くぎを刺しておきたいといいますか、そういうのがないように、ぜひいい計画をつくっていただきたいと思いますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-03","title":"第２０号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第２０号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"重要事項とは、例えばどのようなものなのか伺いたいと思います。例えば区立園で実際に、インターネットを利用して公衆の閲覧に供すという、この具体的なやり方というのは、実際どのようなものになるのでしょうか、伺います。","respondent":"石井保育支援課長","answer":"重要事項なのですけれども、法令名称では運営規定などと定められてありますが、例えば開所時間ですとか、あと実費徴収の費用ですとか、あと嘱託医がどういうふうな形になっているのか、保育園の入園の際に施設のほうが各保護者に説明するようなことです。","id":"exchange-025"},{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ確認なのですけれども、これは要はインターネット上にきちんと載せてくださいということなのですよね。これは今回、国のあれで下りてきたのだろうけれども、ほかにもこういうのはあるのですか。要するに、インターネット上に載せないという今、逆にそういう情報というのはこういったものに対してあるのかどうか、そこだけ教えてください。","respondent":"石井保育支援課長","answer":"特に子育て支援施設に関しましては、もうインターネットで公開したりとか、ホームページに載せるのが当たり前な部分がありますので、ではことさらこの規制を加えたところでというようなところはないと認識しております。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"確認","question":"それで、保育園に通わせている方に伺っても、そんなの見たことがないということで、保育園としては、掲示をされているのかもしれないけれども、目につかない。そういうことの改善につながると考えてよろしいのでしょうかということを１点、確認させてください。","respondent":"石井保育支援課長","answer":"よって、今回の改正で、財務情報が透明化されるかというご質問については、そのような状況ではないのですけれども、今後また国において検討はされているということで認識はしています。","id":"exchange-027"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"さらに言えば、私は保育園には入れませんので、本当に掲示されているかどうかの確認ができないわけですよね。補助金の義務なので、その辺については、ぜひ今回の検討に入れてないのであれば、少し外れてしまいますけれども、よりよい掲示の方法も考えていただいた上で、ぜひ今後はそういうことも求めていっていただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"第３０号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第３０号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"公務災害補償基礎額が引上げとなった理由は何なのかと。東京都、国なのかもしれないのですけれども、その理由を伺いたいというのと、あとこれは参考までに分かればいいのですが、削除された婦人補導院その他これらに準ずる施設というのは何なのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"その他で準ずる施設ですけれども、補導院のほかに今、民間のほうでもそういう支援をする施設等がありますので、そのことを指しているものと考えております。","id":"exchange-029"}]},{"id":"topic-05","title":"第３３号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する規約","agenda":"第３３号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する規約","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ご説明を伺って、ここの共同経理課のところに東京都も加われば、完全に一元化されて、児童養護施設等の事務負担はさらに軽減されたと思われるのですが、東京都も含めて共同組織を設置するという議論はなかったのでしょうか。あったとしたら、なぜ東京都は加わらなかったのか、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"今度できる措置費共同経理課に東京都も加われば、当然、施設側からすると１か所で済む話ですが、現状、東京都としては、少し様子を見たいということで、回答をいただいていると聞いております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"当該組織の共同設置は現場からの要望も聞いていますし、事務負担軽減のために大切なことだと思いますので、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-06","title":"品川区内保育園等あり方基本方針パブリックコメントの結果の概要","agenda":"品川区内保育園等あり方基本方針パブリックコメントの結果の概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"請願第１号は品川保育問題協議会からの署名が、足し合わせたところ、１,４６９名からの署名。その第１号についてはそこで、第２号全体についてちょっとお伺いしたいのですけれども、今回の、２次の４月の入園募集の結果が出たと思うのですけれども、２次の認可保育園の不承諾数と年齢内訳ができれば、そのうち何歳が何人とか分かれば教えていただきたいと思います。","respondent":"石井保育支援課長、立木保育課長、今井保育教育運営担当課長","answer":"今回、品川区における運営費の加算に関しては、民間会社の経営努力を後押しするという考え方で実施しておりますので、あくまでも品川区としては。合計いたしますと、申込み申請が２,８１４、うち内定が２,０７４、不承諾が７４０となっています。一方で、施策の内容について、社会情勢の変化等を踏まえた方針であるということで、賛成いただいているようなお声も頂戴していますので。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと伺いたいのですけれども、品川区としては、これでも経営努力というのでしょうか。せめてＮＰＯですとか社会福祉法人立からでも、経営努力もちょっとというレベルではないので、定員割れ補助を実施すべきだと思いますけれども、第１号については、いかがでしょうかというご質問をします。その議事録や資料などは区民に公開すべきだと思いますけれども、いかがでしょうか、質問です。","respondent":"石井保育支援課長、今井保育教育運営担当課長","answer":"その８,０００円の補助に加えて、さらに、例えば東京都の実施している保育サービス推進事業等も合わせると、やはりこれについては運営費の補助になるのではないかと考えています。検討内容といたしましては、他区の実施状況等々の確認も行いながら、昨年度、実施しました子ども・子育て支援事業計画の中間見直しにおいて実施いたしましたニーズ調査の結果等々も反映いたしまして。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"第１号に関してなのですが、やはり先ほどのちょっと現場の実態、苦境というのをあまりに見ていないなというご答弁だなと思いまして、何か空きがあるのだったら空きスペースを使って、これだけの補助もあるので事業やったらみたいな感じに聞こえるのですけれども、ちょっとそれは現場の苦しい実態にあまりにもそぐっていない認識、ご答弁だと思いますので。","respondent":"今井保育教育運営担当課長","answer":"２点目のご質問ですけれども、公共施設の方針との整合のところですけれども、あくまで今回、お示ししているあり方基本方針につきましては、これはこれとして、区内保育施設全体の議論の中でお示しさせていただいたものということで、公共施設の方針ありきのものでは。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区は株式会社私立園を急激に増やして、今や公立園４３、私立園は１０３園と逆転しました。ちょっと抑えますということになるのでしょうか。そういう考えなのでしょうか、伺いたいと思います。このＳＶ園、サポーター園の役割について、改めて聞かせていただきたいのと、区は将来的にはＳＶ園、サポーター園以外の区立園はなくすという考えなのでしょうか、伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"委員のおっしゃった数を減らす前提で、企画からの要請があって、今回のあり方基本方針なのかというようなところだと理解しましたというお話ですけれども、こちらについては全くそのようなことはなくて、あくまで子ども未来部として、保育課として。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"それと、ちょっと続けて。代表質問でも伺いましたけれども、答弁は定員の見直しで、保育環境をよくするというご答弁でして、この基本方針案にも第４章の２５ページ等に「区内の保育需要等を考慮しつつ、施設に適した定員の見直しを行う」と書いているのです。その定員の見直しということと、区立園の数を減らすというのはちょっと矛盾すると思うのですけれども、そこについて伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"現状の機能に新たな機能を担っていただくといった上では、定員の見直しなどを行いながら、負担軽減とセットで考えていきたいといったつもりで、行っていくといったところで予定しているものですので、なるべく早期にこういった取組と併せて実施していきたいということで。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、コロナのところはちょっと踏まえて、当然、踏まえていますと言うけれども、踏まえているならば、そのときのニーズ調査を基にこういう方針を立てるのですかというのは、ちょっと私は納得いかないということで、見誤るのではないのでしょうかと思いますし、この請願第２号の裏面の上のほう、問題2)というところに書いていますけれども、何かすごい今、空きが出ていますということを言うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田副委員長","kind":"質問","question":"保育園の今後の空きが出た場合の事業についてですけれども、国のほうでも、今は議論の中でも、基本的には働いている親御さんのための保育園ということですが、今後に向けてはその方向性が少し変わるということを伺っております。その説明がなかったのですけれども、それについて、ぜひ伺いたいと思います。","respondent":"石井保育支援課長","answer":"基本的に保育所は保育の必要な児童を預かる場所という認識がまるっきり変わるということではございません。","id":"exchange-038"},{"speaker":"吉田副委員長","kind":"質問","question":"品川区としては、その方針にも従った運営をしていくという考え方でよろしいでしょうか。","respondent":"石井保育支援課長","answer":"例えば補助制度などでそういった多機能化を後押ししていったりとかいったこともありますし、このあり方基本方針につきましても、今後、在宅子育て世代に対する支援の強化というようなこともうたってありますので、そういった意味では、国の方向と並行していきながら。","id":"exchange-039"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ならば、私たちなりの工夫でやっていこうということで、最初はもう赤字垂れ流しで事業に参入をいたしました。その辺についての今後の私立保育園の評価の仕方は今までとちょっと変わるのか、やはり私立保育園を認めていくのであれば、その辺の保育事業についてにちょっとフォーカスしたような事業の見方をしていただきたいと思うのですけれども、その辺の方針はどうなっているでしょうか。","respondent":"石井保育支援課長","answer":"確かに委員のおっしゃるとおり、保育園を設置者の要件ということで、財務情報については審査されるところですが、その後、お金の使い道といったことについてもありますけれども、現行どおり、きちんと指導検査ですとか、あとは保育園に対する運営指導のところで、日々。","id":"exchange-040"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"今、現行どおりとおっしゃいましたけれども、今まででいうと、具体的に指摘していても、例えば財務情報の中でおもちゃへの支出が非常に低いとか、それから働いている、保育に従事している人への人件費率が大変低いというのが、そうではない運営事業者もありますけれども、既存の保育事業者にはあって、その辺の点検をぜひしてほしいとこれまで要望してきたかと思うのですが、それについては、今後。","respondent":"石井保育支援課長","answer":"令和６年１０月より、児童相談所が品川区に設置されることにより、来年度以降、品川区が、私立保育園に対する認可権を持つというところでは責任が多くなると感じております。","id":"exchange-041"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なので、そうなったら別の事業に取り組めることこそが私たちの力ではないかということで、事業に取り組んでまいりましたので、その辺の工夫はぜひ区としても活かせるように、支援のあり方ということを考えていただきたいと思うのですけれども、その点について、改めてもう１回お考えを伺いたいと思います。いかがでしょう。","respondent":"石井保育支援課長","answer":"そういった民間の創意工夫を今後、引き続き、区としても後押しするとともに、先ほども申し上げましたけれども、児童相談所設置市ということで、より強力な指導監督権限を行使するに当たっては、保育園が適正な運営を今後やっていけるように、引き続き。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"３点、お尋ねします。１つは公設民営化から、さらに公私連携型保育所という流れを、今後の再整備の中でお話しされたのですが、まずは、公設民営化したときの、区の監督というかグリップというかそれはどのような形で民営化園になされていくのかというのが１つ。そこから、一つはさっきの公設民営と似た話が一つあって、いわゆる区によるチェック機能をどのように確保していくのかということが１つ。","respondent":"今井保育教育運営担当課長","answer":"２点目が職員の入れ替わりへの対応というところでございまして、こちらについてもちょっと民設民営化の進め方をどのようにしていくかといったところも、現在ちょっと詳細については検討中のところですけれども、仮にここで職員が入れ替わるといったようなところになれば。","id":"exchange-043"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。本当に一人ひとりの子どもが大切にされなければいけないのは当然のことだと思います。それで、先ほど課長からもご説明があったように、本当に変化が生じているのです。十分な説明というところは誤解を生じないように、今後、丁寧に説明を行っていただきたいということで、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。理事者からの答弁をお聞きする中で、配置基準についても区独自で手厚い基準を設けていますし、国の基準改正に向けて前向きに準備されていく姿勢を確認させていただきました。定員未充足に対する補助に関しても、保育園の質を上げるため、後押ししていく対策をとられていくことを確認させていただきましたので、この請願については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"区が区立保育園の民営化に当たっては、保護者や園児の疑問点を解消して、これまでの保育の質を低下させることなく移行することが重要であるため、ガイドラインでもしっかり定められて、区が民間保育園の運営から手を放してしまうということではないことを確認いたしました。だから自治体としての保育教育の責任については、これからもしっかり果たしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと１点、配置基準については、国も少し全国の切実な世論、運動、声の下で、改善に腰を上げるような方向もあるようですが、もともと１歳児では品川区は５対１にしていたということもありますので、もし国がそういう動きになるということであれば、さらにそこに上乗せをして、区としてさらに努力していただきたいということをちょっとつけ加えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。公設公営で存続というところがありますが、民営化そして公私連携を進めていく中で、今、区の関わり方を説明していただきましたので、十分に理念やいろいろな方針が進められていけると思います。それから請願項目２、３については都が対応していますので、これをさらにもっと進めていっていただきたいと思いますが、現状はしっかりと進められていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。説明とこれまでの質疑応答を受けて、区立であろうと私立であろうと、一人ひとりの子どもが大切にされている保育事業や施策はこれまでもやっていただいていると思いますし、これからもしっかりとやっていただけるということは確認をしました。これは要望で終わりますが、結論としては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。理由としては、先ほどのご説明があったように、保護者、職員、あと当事者の子どもの声を今後もしっかりと現場の声を聞いていただいて取り組んでいただきたいと思います。それと、パブリックコメントによって６分類されている。これは本当にそれぞれ記載があって、これが基本方針に反映されていると思いますので、今後もどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"ゆきた委員","kind":"確認","question":"本日、結論を出すで、不採択でお願いします。ほかの２つの項目に関しても、答弁をお聞きする中で、あらゆる媒体を通して情報発信されている点や、方策、方針についても様々な現場の代表の声を受けて方策の策定をしている姿勢を確認させていただきましたので、この請願自体については、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"本日、結論を出すで、結論は不採択といたします。ちょっとだけ理由を述べます。さっきと重なるところもあると思うのですが、請願項目の１につきましては、民営化方針の撤回というより、もし民営化するのであれば、その事業のチェックをきちんとやっていただきたいということです。ということで結論は不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"安藤委員","kind":"意見","question":"本日、結論を出すで、採択です。様々質疑させていただきましたが、実態にも合わず、必要性もなく、子どもの発達権利保障に重要な公立保育園を統廃合し、民間に売り渡すことに道を開くこの方針案は撤回すべきだと思います。子どもが減るから保育園も減らすというのでは、少子化もとめられず、行政の責任も果たせないと思います。したがいまして、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。先ほどと同じ理由になってきますけれども、やはり、まず、あり方基本方針のほうのご説明は理解しました。そして民営化というか、区の関わり方もグリップを利かせていくということですので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほどの請願のときにも言いましたけれども、様々な処遇改善などを行っていただきたいと思いますが、いわゆる需要と供給だったり、社会情勢、子育て環境、財政状況など、保育園のみならず、在宅子育て支援なども含めて、時代に合った、そして未来を見据えて、様々な方々から意見も聞きながら、総合的に判断をしていって、方針をつくっていっていただきたいなと思いますので、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799105?Template=document&Id=5122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":44138,"voices":173}},{"id":"r06-20240226-5","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"総務委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず(9)第３２号議案、第二戸越幹線整備工事（下流部シールド）請負契約の変更","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず(9)第３２号議案、第二戸越幹線整備工事（下流部シールド）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ご説明ありがとうございました。材料費が引き続き値上がりしているところで、事業者も大変苦労があるなと思うのですけれども、為替について伺いたかったのです。実際の材料費高で見て判断するということなのか、為替についてご説明いただけたら。","respondent":"佐藤（聡）経理課長","answer":"ただいまのご質問についてですけれども、いわゆる材料費等というところで見ていると思いますので、そういった為替の変動によります原材料の部分だと思いますので、そういったものも含めて、単価といいますか、工材費が上がれば、東京都、国のほうで、そういった単価を出しまして。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"最初にお聞きしたいのですが、今回納期が遅れて８４日間延長ということですけれども、簡単でいいのですが、理由を教えていただけますか。","respondent":"北原河川下水道課長","answer":"現在はそれが解決しまして、到達まで至っているです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今、原因が分かりまして、業者の作業工程の問題なのか、砂利とかそういう処理の問題なのか、そこら辺は我々も分かりませんが、ここでインフレスライドするというのですが、延長は８４日間しかないのですよね。３か月に満たないと思うのですが、それに対しても、インフレスライド条項というものは適用すべきなのですか。でも、このようにもう工期が終わる寸前にインフレスライドを適用する意味があるのですか。","respondent":"北原河川下水道課長","answer":"インフレスライドについてですけれども、基準日を設けまして、その基準日以降に工事を行った内容について、価格を改定するという形になっておりまして、基準日は令和５年５月３１日となっておりますので、それ以降に行った工事の内容について。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"変更の理由云々、あとインフレスライド適用の時期、今説明を受けましたので、我々が見ると、この８４日間でそれだけインフレスライドを適用するのはおかしいなというふうに思うのですが、そのように遡って適用されるというのもまた不思議だなと思いますし、我々も民間業者を調べていますけれども、民間ではほとんどこういうことがなくて、業者が泣いているという話も我々は聞いているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つは、細砂層が出たと。これで機械がというお話があったけれども、これは当初も入札をかけているのですが、そういうのが出てきたときはどちらの責任ですか。土がそうだからこうでしたというのは、それはそれで合っているのだろうけれども、現実がそうだったと。それを最初から見込んでいたのか、見込んでいないからこれはオーケーですよと。そこら辺を教えていただきたいと思います。","respondent":"北原河川下水道課長","answer":"ただ、想定よりも細かい砂が分布していたということで、掘り進めることはできたのですけれども、管が詰まるというところまでは想定できなかったというところになりまして、そういう意味では、今回。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"今ので大分分かりました。それから、今、自然由来のヒ素系の土が出てきたというのは、素直に書いたほうがいいのではないか。これぐらいかかってしまいましたと。それはもう、どちらが悪いとも言えないのだけれども、それも理由に書いてしまったほうがよかったような気がしてならないのですが、どうかなというのが２つあります。","respondent":"北原河川下水道課長","answer":"ただ、当初３７億というものに対して、４７億と大きく上がっていることについては、主要な原因が、汚染土とインフレスライドにあったという説明をさせていただいたものになります。もう１点が……。","id":"exchange-006"}]},{"id":"topic-02","title":"第１１号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","agenda":"第１１号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"主な改正理由は、大きく２つだと、今説明がありましたが、(1)の番号利用法改正に伴う規定整備について、伺いたいと思います。どこの点が利点だと思っているのか、その点を伺いたいと思います。(2)の、システム連携の終了に伴う改正。今後もまたこういった対応が幾つか予定されているといったら語弊があるかもしれないですが、何か説明できる現状があれば伺いたいと思います。","respondent":"横田情報推進課長","answer":"２点目の、条例で今後またこのような改正があるかですが、新しくマイナンバーを使う事務が発生した際には、条例改正を追加で行いますし、なくなった場合は削除するということを予定しておりまして、喫緊であるかというと、この２点ということになります。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"迅速に進めていくという言い方は、不安を感じる方にとっては、知らないところでますます広がっていくということの表れだと思いますので、態度表明は後でもう一言述べますけれども、マイナンバーカードをさらに進めるものなので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"塚本副委員長","kind":"確認","question":"１点だけ確認したいのですけれども、不勉強なのですが、項番２の(2)の今回必要がなくなったので削除しますよという、システム連携の終了に伴って、1)のほうが欠番扱いということで、空欄で項目２６とか２７が残るのですよね。これはなぜですかという。全部削除しないで欠番扱いにすることの意味だけお伺いしたいので、お願いします。","respondent":"横田情報推進課長","answer":"今回の条例ですが、この後ろにも事務が幾つかございまして、この情報連携のほかに、個人情報保護委員会のほうに、この項番何番で提出するというのがございまして、そちらのほうも修正があったり、影響が大きいためこのような欠番扱いというふうにしております。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど中塚委員からお話がありましたけれども、区民サービスが様々どんどん広がって、いろいろなものが出来上がっておりますが、品川区として迅速な区民サービスに対応するためには、こういう制度、法律から省令に変えるという、そういうことをやって、できるだけ、私は今後も合理化を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"賛成しますが、一言だけ。先ほど中塚委員からお話があったので、私はマイナンバーカード、省令になって、品川区は積極的に推し進めてといいますか、いろいろ利用できる範囲を広げていくべきだと思っていますし、それを迅速に対応できるようにしていくということは非常にいいことだと思っていますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"そしてもう１点、第４条第２項に「区または関係機関等に相談するよう努めるもの」とありますが、相談することを努力義務とすることなのか、確認させてください。つまり、併せて言いますと、いじめを受けている本人に、新たに保護者、教職員、品川区または関係機関に相談することを義務づけるための一部改正ということでよいのか、なぜ本人に義務づけるのか、伺います。","respondent":"勝亦総務課長","answer":"そういった中で、いじめを受けているという主観的な部分についても、いじめを受けた場合、相談をしていってくださいという考え方が必要ということで、この第２項、いじめを受けていると思うとき、第３項にもいじめを受けていると思う。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"努めるものというところは、努力義務という部分に当てはまるという説明でした。私が伺ったのは、いじめを受けている本人に、いじめの報告義務を追加した理由は何かと伺いました。改めてご説明ください。","respondent":"勝亦総務課長","answer":"義務という言い方が、難しいかもしれないのですけれども、いじめを受けても、自分がいじめかなと思ったら、決して自分の中で抱え込まずに、先生や親、学校等に相談してくださいという、そういった趣旨です。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"説明では相談してください、趣旨ととどめておりますが、条文上は努めること。こうした子どもに、保護者や先生や品川区に相談することを義務づけることは、つらい思いをしている本人をさらに追い詰めるものだと私は思いますが、いかがでしょうか。繰り返されて脅されているわけですよね。ちくったら陰湿化する、そういう実態が子どもたちの関係性の中にあるということは、ご存じなのか伺いたいと思います。","respondent":"勝亦総務課長","answer":"努力義務の部分に関してですけれども、こちらは努力義務といっても、この努力を果たさないと不利益を課すぞというような趣旨の「努める」ということではございませんで、一般的な考え方としまして、悪いことを見たら１１０番しましょう、体調が悪い人を見たら１１９番しましょう。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"ますます先生の見えないところでいじめが繰り返される。今、義務を果たさないと不利益を課すものではないとおっしゃったけれども、今回条例上「努める」と記載をする変更ですから、努めなければ、何なのかと。いじめの禁止という、いじめの罰則化を強化するものだと思いますが、改めて伺いたいと思います。こういう改正で、いじめが止まると区長部局は本当に思っているのか、改めて伺いたいと思います。","respondent":"勝亦総務課長","answer":"いじめはあります。そういった中で、いじめを完全に解決するルール、手法は、現在我々が持ち合わせている科学、理論、そういったもので、この方法を使えばいじめがなくなるという手法はないと認識しております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは私も１ミリも否定しません。しかし、今回の改正は、いじめを止める方向とは真逆だと思います。次に、第１９条、いじめに対する措置についてですけれども、私はそれぞれ条文がありますが、いじめ防止の条例で規定すべきことは、児童生徒がいじめを受けずに安心して学校に通う権利があるのだと。つまり、不当な介入には当たらないというのは、どういう理屈なのか、そこをご説明いただきたいと思います。","respondent":"勝亦総務課長","answer":"第１９条の部分ですけれども、こちらにつきまして、まず、いじめの事実の把握。それから、法律に沿った対応ができていないときに、勧告を出すことを定めているところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここは大事な部分なので、もう一度詳しくご説明いただきたいのですけれども、どういうケースになると、不当な介入に当たるのか。子どもと直接接するのは先生たちや学校ですから、そこについての区長部局の見解も伺いたいと思います。そうした区長部局の役割は、いじめ解決への環境整備だと私は思うのですけれども、前文に書かれているとおっしゃっていましたが、改めてその点も伺いたいと思います。","respondent":"勝亦総務課長","answer":"こちらについて、「教育委員会と連携し」とありますけれども、対応を行っていく中で、教育への不当な介入、こういったものは発生しないというふうに考えております。教育委員会におきましても、委員がおっしゃったようないじめへの対応を行っております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"意見","question":"最後に一言、教育委員会と区長部局がいじめを解決するために、いじめをしている子どもがいじめを止めるために、やめるために連携していくことは、必要なことだと私は思います。これはより追い詰めるものだな、陰湿化するものだなと私は思いますので、私の意見を受け止めていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"今、中塚委員から質問がいろいろ出たので、この中で継続してお伺いしたいところがあるのですけれども、まず、政治的な中立のところ、お話出ましたけれども、これは行政だけではなくて我々議員もそこの定義というか、なぜそれがあるのかというものを考えなくてはいけないというふうに考えておりまして、介入が許されない教育内容について関与がなされると、これは政治的に偏ってしまうところがあると思います。","respondent":"勝亦総務課長","answer":"教育の内容に関して踏み込んでいくというよりは、対応の部分を見て、そういった介入というご心配の部分もありますので、２の(4)ですが、公正かつ中立な判断ができる第三者の意見を聞いた上でという、さらにより確度を高めるような形で対応していきたいと考えております。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"そこのバランスをどう考えるのかというところで、今回は第三者性を担保するような仕組みをつくっていただいたというふうに理解いたしました。なので、これは半分要望もあるのですけれども、もう少しこの児童生徒に対して、この通報の努力義務を課すと至った際に、どういうふうな検討がなされたのかというところをもう一度ご答弁いただければと思います。お願いします。","respondent":"勝亦総務課長","answer":"こちらの「努めるものとする」、完全に禁止するとすると、そういった表現ではなく、「努めなければならない」という表現になろうかというところはあるんですけれども、こういったいじめに関してはなかなかご本人が相談しづらい、できないという部分で。","id":"exchange-020"},{"speaker":"松本委員","kind":"意見","question":"趣旨としては、ご回答いただいたとおりと思います。中塚委員はそれと絡んでほかのこともいろいろおっしゃられていて、ただ、それはこの努力義務のところと並行して行えることと私は思いますけれども、ただそこの部分は、区長部局の態度として、ここは被害者の自主的な対応というところを尊重するということは、ぜひ心に留めておいていただけるといいかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最初に教えていただきたいのは、これは平成２８年に、教育委員会、教育長も含めて、区長部局、最初に区長の管轄下になったときにこの条例ができたのかなと思っているのですが、違うのかな。間違っていたらごめんなさい。あのときなのかなと思っていますが、それで今回、令和６年４月１日からなので、平成２８年から初めてこれを改正することになるのか、そのときかなというのを最初に教えてください。","respondent":"勝亦総務課長","answer":"こちらについては、いじめ防止対策推進法に基づいて設置したものというふうに理解しています。改正につきましては、先の令和５年第４回定例会においても、教育委員会のほうから改正の提案を行う等、改正等は行っているところです。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません。現場を知らなくて、連携していきますと言うのだけれども、何でもかんでも上げてもらいますと言うのですが、上げてもらったら報告で、その後区長部局で一歩踏み出すのはどうするのですか。調査をかけようとかどうするかといっても、それも教育委員会と連携してやっていくということになりますよね。そこら辺はどういうつもりでこれをやっていかれるおつもりなのかというのを教えてください。","respondent":"勝亦総務課長","answer":"学校、教育委員会におけるいじめ対応につきましては、従前のとおり、学校でも当然先ほどありましたように、教育の精神的な部分、人間的な部分の教育から始まって、いじめへの対応ですとかそういったものの学校での役割というものは重要なものだと考えております。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"事前通告みたいなことをするけれども、予算特別委員会でこれはやろうと思っていたので、通告しておきます。なったとしても、どういうふうにしたらいいのだということを教育委員会だって考えているわけですよね。ですから、具体的なことは予算特別委員会の１０分間の中で一本勝負でそれをやるので、ぜひ、それだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"確認","question":"今度区長にも相当な責任が行くわけですから、そうなのかなあというのを思いました。本来は１つのクラスに１０人に１人でも補助員がついて、子どもたちを監視しているような体制があれば、または、防犯カメラがついていて、子どもたちが集まっているというのを確認できるようなそういうものがあればいいのかなと。今、お話ししたのですが、質問というよりはどういう方向で進むのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"塚本副委員長","kind":"確認","question":"今までの質疑に少し出てきているところもあるのですが、今回この条例が出てきて、今情報の一元化という、いただいている委員会資料のところでも、教育委員会からと区長部局からの情報管理の一元化と。そこの確認が１点です。運用というか、手続的なところですけれども、そこに上がっているものをどのように１事案ずつそれぞれ対応していくのか。現状について、お伺いしたいと思います。","respondent":"勝亦総務課長","answer":"情報の共有に関しましては、現在、共通のフォーマットを、いつ発生したのかとか、必要な項目を教育委員会のほうと詰めまして、共通の項目をそれぞれ同じ項目で共有し合うという考え方であります。","id":"exchange-026"},{"speaker":"塚本副委員長","kind":"意見","question":"基本的な決め事としては最低限月１というのも分かるのですけれども、いじめというのはリアルタイムに対応しなければいけないことなので、そういった事案が、緊急性がある事案が上がってきたときに、所管における手続というのがないと、対応が遅れてしまうとか、漏れてしまうとかそういうことになり得るので、そこのところはすごく大事だなと感じています。","respondent":"勝亦総務課長","answer":"詳細な事務フロー等についてはまだ定めてございませんけれども、まず今おっしゃいましたように、取り漏れ等が起こってはいけませんので、現状区長部局のほうで受けている相談等々につきましても、情報の確認ですとかそういったものはリアルタイムで相談員のほうから学校。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"例えばそれは、いじめる側も、いじめられた側もというところで言うと、まずはいじめられた側のところかなと思いますが、区長部局として、そういった報告がぜひタイムリーに飛んでくるというところでは、どういった視点を持って、教育委員会とは違う視点、第三者委員会というお話もここで出てきていますが、中立的な判断というところでは、どういうふうにいじめを捉えていくのかというのを。","respondent":"勝亦総務課長、堀越総務部長","answer":"それぞれが第三者的な、中立的な立場に立って、被害を訴えている方、学校、それから加害者に対して中立的、第三者的に、客観的に、弁護士等の意見も踏まえながら、対応を図っていきたいと思います。今回のこの条例につきましては、先ほど努力義務云々の話もありましたけれども、自発的な対応をして、我々が、区長部局、教育委員会がしっかりお子さんを守るのだよというような姿勢を示して促したいということと、そのほか。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問・要望","question":"賛成です。最後に少しだけ、意見をもう１回。今独立性の話も少し出ました。なので、第三者的な視点でというのは、極めて大事なのかなというふうに思っております。それに加えて、大事なのは運用のところ。運用のところで気をつけていただくことを要望いたしまして、態度としては賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"意見","question":"これが、ここまで上がってきて、それから教育委員会に来るというときは、事案が発生して、相当大きくなってからだと思っていて、私はここに書いてあるとおりで、早期発見早期解決なので、そこの現場の中でそれが行える環境整備を、区長部局と教育委員会、それこそ現場でどういうのがいいかというのを考えるべきだと先ほどからずっと言っていて、それはどこかで、予算特別委員会でやりますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"意見","question":"先ほども述べましたが、いじめを受けている本人に、いじめを報告することを条例で義務づけることは、つらい思いをしている本人をさらに追い詰め、そして、ちくったなどといじめの陰湿化につながるので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"「学校教育、社会教育その他の教育の場において、ジェンダー平等と性の多様性を尊重し合う社会を支える意識の形成およびメディア・リテラシーの育成に向けた取組が行われること」と規定がありますけれども、この基本理念に教育を踏まえた理由について、具体的に学校教育、社会教育その他の教育の場と具体的に明記した理由について、私もとても大事な規定だと思いますので、そこを伺いたいと思います。","respondent":"加島人権啓発課長","answer":"そのような思いから、基本理念の(6)を入れ込んでおります。このうち、中で入れておりますメディア・リテラシーの育成についてですけれども、こちらは検討委員会のほうでは、主にＳＮＳ上で起きている人権侵害を想定して入れたものです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"性的マイノリティ当事者の話を伺うと、私が共通しているなと思うことの１つが、学校でちゃんと教えてさえくれれば、このような苦しい思いをすることはなかったと。死にたくなるような思いをすることはなかったという話をよく伺います。笑うような態度で傷ついたという方もよく伺うのです。少し今後の展開も伺いたいと思います。中小企業ではまだまだという実態もあります。","respondent":"加島人権啓発課長","answer":"子ども用の内容につきましては、現在教育総合支援センターの指導主事にご協力いただきまして、調整をしており、そういったものが完成いたしましたら、学校現場の協力を得て、ぜひ使っていただきたいなと考えているところです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ様々な機会を捉えて、理解を広げる取組を具体化していただきたいなと思います。今こうした誤解や偏見が広がっているだけに、メディア・リテラシーの取組も先ほど紹介がありましたけれども、トランスジェンダーへのバッシングを乗り越えるための学校教育や社会教育、メディア・リテラシーにどう取り組んでいくのか、改めて伺いたいと思います。","respondent":"加島人権啓発課長","answer":"そういった中で、メディア・リテラシーというところにつきましては、今、人権啓発課のほうでインターネット上の人権侵害等、数年前に講演会、それから懸垂幕等で周知を行っているところですけれども、リーフレットを作る過程の中において。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"トランス女性のふりをして、性犯罪目的で女子トイレに入る人がいるとの意見もＳＮＳなどでよく伺いますが、それは犯罪を犯すその人が悪いのであって、属性を丸ごと排除することは問題だと思います。トランスジェンダーなどの属性で排除したり、犯罪を起こす集団のように扱ったり、ばかにしたり笑ったりすることは、この条例の理念に反することだと私は思いますが、最後にいかがでしょうか。","respondent":"加島人権啓発課長","answer":"どちらか一方というふうに我慢を押しつけていく社会というのは持続可能なものではないというふうに考えておりますので、区といたしましては、この条例をきっかけに、どのような社会が誰にとっても生きやすい社会なのか、過ごしやすい社会なのかということを考えていく。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"パブリックコメントを私も拝見していて、なかなかこの問題というのは、理解の程度と申し上げていいのか分かりませんが、理解の程度というものに物すごくグラデーションがあるというふうに思います。区長という影響力のある立場の人から説明していただく。そういう機会を増やしていただくのが、1つ大事ではないかと思いますが、質疑といいますか、要望なのですが、ご見解を伺えればと思います。","respondent":"加島人権啓発課長","answer":"ただいま委員からございました、周知・啓発をどのように図っていくかというのは、本当に難しい課題だというふうに思っております。ジェンダー平等ですとか、性の多様性に特化した講座というのを、今年度行ってきたのですけれども、特化してしまうと集まらないのです。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問・要望","question":"一方で、気をつけないといけないといいますか、逆に反発が強まるみたいなところで、今のお話を聞いていて、１個事例があったのは、港区がたしか男女共同の何かのときに、女性の団体に区役所内にブースか何かを作っていただいたみたいなものがあったのですけれども、そこに男性を否定するというか、男性は要らないみたいな感じのことが書かれてしまって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問・要望","question":"ジェンダー平等と性の多様性を尊重し合う社会を実現するための条例、私は賛成します。ただ、前もお話ししたと思いますが、私は時間をかけて、ゆっくり進んでいただきたいと思います。焦るのではなく、少しずつ皆さんに理解してもらうように。まだまだ私たちの周りでも、そういう議論さえしていない方もたくさんいらっしゃいます。どうぞそこら辺を考えながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"意見","question":"私もそれはできていたと思うし、いろいろな世界でも、そういう人を私はたくさん知っているけれども、普通にやってきたのだろうと思っているので、あえてこういうふうにすることが本当に皆さんにとってよく理解していただく、これからが勝負かなと思うので、ぜひまたよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"この条例は、ここからがスタートだと、改めて私も今日の議論を聞いて思いました。あらゆる差別をなくして、誰もが自分らしく過ごせる社会に向けて、力を尽くしていただきたいと期待しまして、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-03","title":"第１５号議案、品川区職員定数条例の一部を改正する条例","agenda":"第１５号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"保健予防課が、２プラスで減が８ということですけれども、子育て支援はますます大切になってきますし、子どもの虐待も含めて、保育園の１４減というのはなぜか改めて伺いたいのと、保健所についても、コロナの対策が５類になったというお話がありましたが、コロナの事態を経験して、保健所の役割や日常的な体制の脆弱さが浮き彫りになったという議論がある中、ここで下げるというのは。","respondent":"崎村人事課長","answer":"先ほどお話しいたしましたけれども、感染症が５類に移行となって以降、感染症対応の業務というのはかなり縮小してきている中で、その分をそのまま保健予防課に置いておくのが適切なのかというのはまた別の問題なのかなというふうに考えております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"１点、これはもう完全な要望ですけれども、先ほど口頭では各職種の増員の理由というのをおっしゃっていただいたのですが、できれば事前に我々もそこの部分が、各課の増員の理由というのが分かっていると、より議論が充実するのかなというふうに思っておりますので、こちらは要望させていただいて、結論としては、賛成というふうに意見を申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"中塚委員","kind":"意見","question":"区立認可保育園の民営化は、進めるべきではないと思います。保健所は、機能の強化こそ必要だと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-04","title":"第１６号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第１６号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認させてください。裏面の参考のところ、第８条の２項で、「１,４７０円を超えない」と書いてあるのですが、これは、例えば職能給とかいろいろあるではないですか。どういう人が携わろうと１,４７０円を超えないと、決まりがそうなっているということで理解すればいいですか。あまりに、特にこれは１日だから、やけに手当が安いなと思っているのだけれども。","respondent":"崎村人事課長","answer":"今、委員からお話がありましたように、特に職種によって額が変わるということはなく、基本的には保育士ですとか児童指導の職、また看護師ですとか心理職についても、一時保護業務に携わる予定の職種としてはあるのですけれども、特に職種として額に変更等はないものです。","id":"exchange-044"}]},{"id":"topic-05","title":"第３１号議案、選挙長等の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"第３１号議案、選挙長等の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"ご説明ありがとうございました。改正内容の説明で(1)と(3)ですが、それぞれの実態に応じて変更するということで、よいと考えています。私は、これは正当な民主主義のコストだと思いますので、こういうのは堂々と主張すべきだと考えていますが、ぜひ現場の声とか実態とか、もう少しご説明いただけたらと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"近年、障害のある方への対応や、去年あたりからですが、投票所内における撮影など、いろいろな新しい課題とかが発生するたびに、基本的には管理者の方の判断を仰いで対応したり、また立会人の方にも、そういうルールに違反するような行動がないかというところを見ていただくなど。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"投票管理者および投票立会人報酬が日額として、１日１３時間拘束されて選挙のお手伝いをしているわけで、その分、応分に働いた、職務時間が長くなったら、やはりそれなりに対応していくということは、私は賛成です。ならば、やはり相応の金額、報酬にするべきだと思うのですが、それについて選挙管理委員会はどのように思いますか。これはやはり何かアンバランスでおかしいと思うのですが、いかがですか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただし、職務については、それぞれ委員会で参集する以外にも、いろいろ地域の方との対応とか、それから、選挙があればまた長時間の従事等があるので、委員の皆さんとしてはしっかりと職務を果たすという気持ちで行っているということは、委員会のほうで発言がありました。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういうふうに、片や一生懸命選挙を手伝ってくださる方もいるので、区民から理解されるようなやはり報酬等を、私は選挙管理委員会でも考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-06","title":"第３５号議案、品川区役所の位置を定める条例","agenda":"第３５号議案、品川区役所の位置を定める条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"新庁舎建設を進める、具体化する条例だと考えています。初めに、本会議での副区長の説明の中で、可決について、過半数ではなく３分の２の特別何とかと言っていたと思うのですけれども、私も経験がないので、そこの仕組みについて若干説明していただきたいと思います。つまりこの答弁で言うまちづくりの機運とはどの地区のことなのか、更新とは何か、ご説明いただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"２点目にございました、本会議でご答弁差し上げたものにつきましては、大井町駅周辺地域まちづくり方針に基づくところのご説明を申し上げておりまして、こちらは広町地区だけに関わるところではないご質問にもなっているところから。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問","question":"始めの採決の条件についてはよく分かりました。ありがとうございました。後半のまちづくりの機運、大井町駅周辺地域まちづくり方針についての答弁ということで、これを必要に応じて更新していきたいと、そういう趣旨だったと思います。いずれにしても新庁舎が位置するのは広町開発であります。開発利益を最優先にする新庁舎建設、今回の条例改正はやめるべきだと思いますが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"このたび基本構想、基本計画、そして、この基本設計を進捗していく中で、実施設計という次のフェーズに行くに当たりまして、やはり議会の皆様のご理解、ご納得をいただきながら進めてまいりたいと考えていますので、何とぞご理解のほどよろしくお願いいたします。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"もう１点だけ、建設費用について伺いますけれども、４００億円が５６０億円に増えましたということですけれども、１ドルが１５０円になる中、輸入に頼る資機材が様々値上げをしていると。現庁舎の耐久年度は、繰り返し指摘するとおり数十年あります。今まさに材料が高いこの時期にお構いなしに進めていいのかと思いますけれども、いかがでしょうか。つまり私はそもそも反対ですが、少なくとも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"須貝委員","kind":"意見","question":"今、中塚委員からありましたが、条件的には、この場所云々はいささか不満もありますが、私は、ＪＲ、民間と一体になって、一緒になって新庁舎建設が進められるということは、賛成です。将来の区民生活が、これによって豊かになるということを希望して止みません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"松本委員","kind":"意見","question":"この条例を出すタイミングですけれども、これはこのタイミングなのか、もう少し後なのか、あるいは早いのか、いろいろあると思うのですが、このタイミングで出された理由と、一般論で結構ですけれども、他の自治体でこういう同様の新庁舎建設をするときのタイミングについて、ご説明いただければと思います。","respondent":"山下新庁舎整備課長","answer":"位置を定める条例について提案するタイミングというところのご質問ですけれども、今回、基本設計の進捗に伴いまして、ご説明申し上げました広町二丁目２番５号という住所の付定の手続きをなすことができました。","id":"exchange-052"},{"speaker":"松本委員","kind":"意見","question":"これはタイミングとしては、多分、議会で新庁舎について議決をするというのは、ほかになかなかタイミングとしてはないタイミングなので、そういう意味では、先ほど中塚委員からいろいろと新庁舎の賛成、反対の話がありましたが、事実上、多分ここが、区議会議員たちがこの新庁舎について賛否、議決という形で表明する最後のタイミングなのかなと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"石田（秀）委員","kind":"質問","question":"その隣がこれだけ広いのだから、別に２の２の２のほうが覚えやすいのではないかと私は思ったのだけれども、そういう議論が全くないまま今日提出されたから、こういうのはどうやって決まるのですかとしか言いようがないのだけれども。","respondent":"山下新庁舎整備課長","answer":"この位置に添うと２の２の５ですねということで、書類を受け取っているところでございまして、今の広町２の１の３６に類するように、この２の２の５というところが皆様に慣れ親しまれるように、こちらとしても努めてまいりたいと考えています。","id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"区民の利益より開発利益を優先する新庁舎建設に反対します。庁舎は開発事業者のものではなく、区民のものです。資材高騰が続く中、少なくとも一旦中止し、引き続き新庁舎建設についての住民議論を深めるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"}]},{"id":"topic-07","title":"令和６年請願第３号、学校側の人権侵害から生徒児童を護る対策","agenda":"令和６年請願第３号、学校側の人権侵害から生徒児童を護る対策","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"本会議での質疑も皆さん、お聞きになったかと思いますけれども、そのことだということです。なので、意見書を出すべきだと、まず初めに意見を述べておきたいと思います。事実の問題として、こういう問題が起きていることを区は知っているのか、報道を把握しているのか、あくまで事実の問題を確認したいということと、品川区は人権侵害、人権侵犯だと思っているのか、ここを確認させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"中塚委員","kind":"確認","question":"先生の指摘によってこれは変えられたそうですけれども、そのデータが消去されたかどうかが確認されないと、このような事態が起きているわけです。少なくともこういう人権侵害については、例えば学校と生徒はよく話し合うべきだとか、一人一人の人権を保障すべきだとか、人権宣言をしている品川区としては改善が必要だとか、そういう立場こそ示すべきだと思いますが、改めていかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"もう１回ぐらいいいじゃないですか。判断しないという答弁が、それはおかしいでしょうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"中塚委員","kind":"意見","question":"こういう品川区の態度だからこそ品川区議会が、請願にも書かれているとおり、こういう人権侵害は許されないと意見を上げるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういう状況の中で、我々議会が東京都に意見書を出していくとか、そういうことは、私はこの場ではするべきではないと思っているので、皆さんのお考えは分かる面もあるけれども、我々議会が責任を持ってお答えをするのであれば、今、東京都にこのような意見書を出すというのは、私は品川区議会の、例えばこれは総務委員会が中心になるのか、全体が中心になるのか分からないけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"須貝委員","kind":"質問","question":"すみません。もう１回少し戻してしまうかもしれないですが、品川区で意見書を出すということならば、やはり品川区として私はしっかり調査をしなければいけないと思うのです。もう一度お聞きしますが、ほかの人も聞いていますが、向こうが調査を受け入れる義務があるのか、また品川区として調査できるのか、あと指導する立場にあるのかということを、それだけ教えてください。","respondent":"勝亦総務課長","answer":"今ございましたように、そういった意味では品川区で調査等を行う権限はございません。ただ、先ほど中塚委員がおっしゃいましたけれども、そういったご相談等があれば、もちろん区としては真摯にお伺いして、必要な機関につなぐ必要があるとは考えてあります。","id":"exchange-061"},{"speaker":"須貝委員","kind":"意見","question":"なかなか踏み込めないとなると、我々もきちんと実態調査をしない限り、なかなか意見書を出すというのは難しいと思います。今の時点では、品川区としてしっかり相談に、子どもたちも含めて、児童・生徒に対しても乗ってあげる。今、私が言えるのはそこまでです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問・要望","question":"私としても、意見書を委員会として出すということは重い判断だろうと考えていますので、しっかりと調査していくとか事実を確認していく必要性というのは、非常に感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"私も意見書を出すことを議会として、また委員会として求めていくことは、困難とは考えています。消費者契約の関係になってくるのだろうと思っています。今現状では、この具体的なほうの事案がどうなっているかといったら、報道を見る限り、人権救済の申立てをされている。さらに、所管は東京都ですから、東京都が何らかの対応をしていくのが本来の筋だとは思いますけれども、そうしたことが行われていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"澤田委員","kind":"確認","question":"本日結論を出すで、不採択です。区内の私立学校の話というのもありますけれども、中身に対して事実確認が行われていない中、仮にこれが事実だとしても、介入する権限がないのかなと考えています。しかしながら、子どもたちを守るためにも相談等をしっかり聞いていただいて、しっかりと都や国へとつないでいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"塚本副委員長","kind":"質問","question":"本日結論を出します。結論は不採択です。理由としては、これまでの委員のお話とも重なりますけれども、請願では特定されていないですが、今までの議論の中で品川翔英高校ということで、１つの私学の話で、今そこの中で人権救済申立て、そういうところにも今かかっている話という、事実関係についての議論がなされている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"大倉委員","kind":"質問","question":"理由については、先ほど松本委員から、これを認めてしまうと事実認定になってしまうというところは非常に大きいのだろうなと改めて思いましたし、この権限自体は調査しないと分からないというところは、第一義的には確かに都のほうで判断していくというところで、今回、今、この意見書を出すということについては、議会としてなかなか難しいという判断を改めてしましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"須貝委員","kind":"提案","question":"本日結論を出すということと、不採択でお願いします。ぜひその方たちに相談して、私は今回の、皆さん、提出された、請願書を出された方の意見をその方たちが認めてくれて、そして、その学校にきちんと提案できるような方向で進んでいただければいいと思います。私も区議会議員で、関われないということは残念ですが、そういう道がありますので、ぜひ頑張っていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"松本委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いしたいと思います。理由は、先ほど大半を申し上げさせていただきましたので、そのとおりですが、最後に１つ申し上げるならば、本件の請願代表者の方がお幾つの方なのかということは、出てこないところです。ただ、内容的にはやはり学校の話ということなので、一定、未成年の方、学生の方が動かれていることは推測できます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"石田（秀）委員","kind":"確認","question":"でも実際は、２００人が中学１年生なのに卒業するときは１５０人。高校に行かせるときは１５０人、きちんと全員高校に行けているという言い方なのだけれども、なるほどこういう言い方かと思って、それでどうしてくれという話があったのだけれども、こういうことも私立ではあるのは事実だと思っているし、私もそのときはそれを確認したけれども、しかし、これがまさに私立で、ではどこが指導するのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"初めに、まず区のほうで人権侵害との判断はしないと言っているからこそ、区議会から品川区に対して、東京都へ意見を出すことを働きかけるべきだと思いますので、意見書を出すべきだと思います。それと、皆さんのご意見を伺いましたが、私立高校も公教育です。これは区に言う話ではないのだけれども、自分の自己表現だし、そうありたいし、そう見られたい、それが青春なのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"}]},{"id":"topic-08","title":"令和６年請願第４号、消費税減税を求める請願","agenda":"令和６年請願第４号、消費税減税を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ皆さんと一緒に、消費税の減税を国に求めていきたいと思います。もっといえば保守本流、様々な国の人々が選挙で選んでいる政権でどうこう言うつもりはないですけれども、多くが資本主義国であり、多くが保守と言われる政治をやっている国も含めて、１００か国以上が減税しているということは、これが国民の所得を増やすことにつながるし、これが経済を動かしていく個人消費の引き金になると思うからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"須貝委員","kind":"質問・要望","question":"代表質問で申し上げましたが、年金だけに頼って生活している高齢者が１,０００万人以上いる。非正規雇用が２,３００万人、中小企業で２,６００万人働いている。今回、この消費税減税を求める請願ですが、品川区民を捉えれば、やはり区民に直結する話なので、こういう請願、国に出してどうなのだという話ではないですが、区民を代表するならば、やはり私は意見書は出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この前話があったように、我々も前は全区民に３万円で中学生以下５万円という話もあって、これは１３５億円ぐらいかかってしまったけれども、これがいいのかという話もあるけれども、区議会として品川区民の方々に、今こういう状況にあるときに何を品川区として政策を打っていくのかというのが、これから求められているのだろうと思っていますし、子育てをしている家庭については相当今、給食費の無償化や。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。区民からのご意見は様々伺っていますが、品川区議会において、消費税に対して責任を持って議論できる材料がそろっていない、また権限も有していないことから、どちらかに区議会からかじを切ることは避けたいと思います。ただ、物価高騰など厳しい経済状況に苦しむ区民、事業者に対しては、適切に手を差し伸べていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"塚本副委員長","kind":"質問","question":"本日結論を出すということで、結論は不採択です。理由は、いわゆる消費税というのは社会保障の財源ということで、ここを減税するということは、その社会保障をどうするのかという国の形に関わることをまず第一義に考えますので、景気対策、不況脱却、こういう手段としてはやはり適さないものだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"大倉委員","kind":"質問・要望","question":"消費税減税については先ほど来、社会保障のというところでもありますし、国の根幹に関わるところもあって、どこまで減税していくのを求めるのかとか、どういった減税を求めて、減税になったときの効果とかというところでいうと、私たちにはまだまだ分からない部分も多いのかなというところで、求めていくということについてはできるのはできるのですが、私たち議会としては、しっかりと今区議会でできること。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、採択でお願いいたします。私が申し上げているのは、決して景気対策でも不況対策でもありません。これはまさに国民の救済策だと私は思っています。今の時期は、消費税を減税することによって、それで幅広い国民の生活が助かるということを考えたら、今は、今はですよ、消費税減税が一番的確な、私は国民の救済策だと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。内容といたしましても、我が党としても日本維新の会としても消費税の減税を求めているところですので、こちらについては、私ども品川区議会日本維新の会としても是と考えているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"質問","question":"７万円の話もあったけれども、１週間ぐらい前にありがとうと言われたけれども、こういうことを品川区はやっていないかといえばそんなこともないわけで、私はそういうことを優先してやるべき話であって、だから、そういう意味で、私は消費税をここで減税する立場にはないということを先ほど来明確に言っているわけで、だから国がどうと言うつもりもなくて、私はそこの部分については不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問・要望","question":"一点だけ、消費税は国税だから国会で議論すべきであってとか、品川区が国に意見を求める立場にないなどの意見がありましたけれども、でも、品川区も法人住民税の国税化については意見を上げているわけだし、ふるさと納税についての理不尽さは意見を上げているし、その意見については私と同じ意見だし、消費税になると意見を言わないというのはどうかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"}]},{"id":"topic-09","title":"令和６年陳情第１号、政党機関紙の庁舎内勧誘行為の実態調査を求める陳情","agenda":"令和６年陳情第１号、政党機関紙の庁舎内勧誘行為の実態調査を求める陳情","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"改めて少し確認ですが、こういった、例えばアンケートではなくて、今、相談体制が十分できているという認識ですが、こうした行為があれば、すぐそういった相談窓口、相談を受け入れる体制があるということでいいのですよねという確認です。","respondent":"崎村人事課長","answer":"そういったご相談だけではなくて、全ての相談が人事課に寄せられるようになっておりますし、昨年の７月から区長が直接みる目安箱というのもできまして、直接そういった相談が受けられやすいといいますか、相談に対するハードルは下がっているのかなと考えているところです。","id":"exchange-082"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由としては、前回と同様に、苦情や相談実績、指導実績もないことから、実態調査をすぐに行う必要は現時点ではないと考えます。しかしながら、もし今後相談などがあった場合は、迅速に、適切に対応していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"塚本副委員長","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。今、人事課長から答弁があったとおり、現状でそういった事実は全く認められないということで、そういった中で現状、さらなる何か調査等を実施するというところには当たらないだろうということで、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。区の職員の相談しやすい環境づくりというのも今もう進めていただいているというところで、こういった意見も相談も寄せられていないということから、現状すぐにというところではないかと思います。もしまたそういったことが増えてくるようであれば、また別途対応すべきではあると思いますが、現在必要ないと思っていますので不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。理由ですけれども、まず、心理的圧力をかけて特定政党の機関紙を購入させるという行為は、許されてはいけないとは思っておりますが、一方で、他の自治体でこうした事案があるからといって本区であるかといったら、それは全くそんなことは事実とは限らない。かえって行政と議会の関係性を壊しかねないとも感じますので、本件については不採択と申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/131056?Template=document&Id=2290#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":71703,"voices":321}},{"id":"r06-20240227-6","meetingId":"r06-cm02","date":"2024年2月27日","dateIso":"2024-02-27","committee":"区民委員会","time":"午前１０時００分～午後 ０時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965719?Template=document&Id=2984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1357,"voices":9}}]);
